  const wingR = makeWing(torso, { side: 1, span: 7.4, mat: mats.membrane, boneMat: mats.plate, glowMat: mats.membraneGlow, x: 0.9, y: 1.9, z: 0.25, baseRot: [-1.15, -0.25, 0.15] });
