      mat: mats.skin, dark: mats.dark, eyeMat: mats.eye, teeth: mats.teeth, mouth: mats.mouth, claw: mats.claw,
      x: 0, y: 0.25, z: -0.35, scale: 0.95 * nc.scale, snout: 1.05, horns: 2, crest: true,
