  rig.tail = [...tailA.segs, ...tailB.segs];
  rig.tailA = tailA.segs; rig.tailB = tailB.segs;
  rig.chestGlow = add(torso, sphere(0.3, 8, 6), mats.plateHot, 0, 1.3, -0.85);
  rig.glowParts = [rig.chestGlow];
  rig.heads = rig.necks.map(n => n.head);
