/* Web Audio synthesizer. All roars, impacts, beams, rain and ambience are
   generated at runtime so the game works fully offline. */

export class AudioEngine {
  constructor(settings) {
    this.settings = settings;
    this.ctx = null;
    this.master = null;
    this.sfx = null;
    this.music = null;
    this.noiseBuffer = null;
    this.ambient = null;
    this.rain = null;
    this.weather = 'clear';
    this.started = false;
    this.lastRoar = 0;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.knee.value = 18;
      comp.ratio.value = 5;
      comp.attack.value = 0.004;
      comp.release.value = 0.22;
      this.master = this.ctx.createGain();
      this.master.gain.value = this.settings.get('sound') ? 0.75 : 0;
      this.master.connect(comp);
      comp.connect(this.ctx.destination);
      this.sfx = this.ctx.createGain();
      this.sfx.gain.value = 0.85;
      this.sfx.connect(this.master);
      this.music = this.ctx.createGain();
      this.music.gain.value = this.settings.get('music') ? 0.36 : 0;
      this.music.connect(this.master);
      this.noiseBuffer = this.makeNoise(3);
      this.started = true;
      this.startAmbient();
    } catch (e) { console.warn('audio unavailable', e); }
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      d[i] = last * 3.2;
    }
    return buf;
  }

  setSound(on) { if (this.master) this.master.gain.setTargetAtTime(on ? 0.75 : 0, this.ctx.currentTime, 0.05); }
  setMusic(on) { if (this.music) this.music.gain.setTargetAtTime(on ? 0.36 : 0, this.ctx.currentTime, 0.2); }

  tone({ freq = 440, endFreq = null, type = 'sine', dur = 0.3, gain = 0.2, delay = 0, attack = 0.01, release = null, detune = 0, filter = null, q = 1, dest = null, pan = 0 }) {
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const p = this.ctx.createStereoPanner ? this.ctx.createStereoPanner() : null;
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t0 + dur);
    osc.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t0 + attack);
    const rel = release ?? dur * 0.5;
    g.gain.setValueAtTime(Math.max(0.0002, gain), t0 + Math.max(attack, dur - rel));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    let node = osc;
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = filter.type || 'lowpass';
      f.frequency.setValueAtTime(filter.freq || 1200, t0);
      if (filter.endFreq) f.frequency.exponentialRampToValueAtTime(Math.max(40, filter.endFreq), t0 + dur);
      f.Q.value = q;
      node.connect(f); node = f;
    }
    node.connect(g);
    if (p) { p.pan.value = Math.max(-1, Math.min(1, pan)); g.connect(p); p.connect(dest || this.sfx); }
    else g.connect(dest || this.sfx);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  noise({ dur = 0.3, gain = 0.2, delay = 0, filter = 'lowpass', freq = 800, endFreq = null, q = 0.8, attack = 0.005, pan = 0, dest = null, playbackRate = 1 }) {
    if (!this.ctx || !this.noiseBuffer) return;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = playbackRate;
    const f = this.ctx.createBiquadFilter();
    f.type = filter;
    f.frequency.setValueAtTime(freq, t0);
    if (endFreq) f.frequency.exponentialRampToValueAtTime(Math.max(30, endFreq), t0 + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f); f.connect(g);
    const p = this.ctx.createStereoPanner ? this.ctx.createStereoPanner() : null;
    if (p) { p.pan.value = Math.max(-1, Math.min(1, pan)); g.connect(p); p.connect(dest || this.sfx); }
    else g.connect(dest || this.sfx);
    src.start(t0, Math.random() * 1.2);
    src.stop(t0 + dur + 0.05);
  }

  click() {
    this.tone({ freq: 680, endFreq: 420, type: 'triangle', dur: 0.07, gain: 0.07 });
  }
  hover() {
    this.tone({ freq: 1100, endFreq: 900, type: 'sine', dur: 0.04, gain: 0.025 });
  }
  confirm() {
    this.tone({ freq: 160, endFreq: 240, type: 'sawtooth', dur: 0.18, gain: 0.08, filter: { type: 'lowpass', freq: 900 } });
    this.tone({ freq: 320, endFreq: 480, type: 'triangle', dur: 0.3, gain: 0.06, delay: 0.05 });
  }

  roar(def) {
    if (!this.ctx || !this.settings.get('sound')) return;
    const now = performance.now();
    if (now - this.lastRoar < 900) return;
    this.lastRoar = now;
    const f = def.family;
    const pan = (Math.random() - 0.5) * 0.6;
    if (f === 'rodan') {
      this.tone({ freq: 620, endFreq: 240, type: 'sawtooth', dur: 1.1, gain: 0.15, filter: { type: 'bandpass', freq: 1600, endFreq: 500 }, q: 2, pan });
      this.noise({ dur: 1.2, gain: 0.2, filter: 'highpass', freq: 900, endFreq: 300, pan });
      this.tone({ freq: 920, endFreq: 380, type: 'square', dur: 0.7, gain: 0.05, pan });
    } else if (f === 'mothra') {
      this.tone({ freq: 520, endFreq: 880, type: 'sine', dur: 1.4, gain: 0.1, pan });
      this.tone({ freq: 784, endFreq: 1174, type: 'triangle', dur: 1.6, gain: 0.06, delay: 0.1, pan });
      this.tone({ freq: 1046, endFreq: 1568, type: 'sine', dur: 1.2, gain: 0.04, delay: 0.22, pan });
      this.noise({ dur: 1.6, gain: 0.06, filter: 'highpass', freq: 2400, pan });
    } else if (f === 'mecha') {
      this.tone({ freq: 110, endFreq: 70, type: 'square', dur: 0.9, gain: 0.18, filter: { type: 'lowpass', freq: 500 }, pan });
      this.tone({ freq: 880, endFreq: 440, type: 'sawtooth', dur: 0.5, gain: 0.08, pan });
      this.noise({ dur: 0.8, gain: 0.18, filter: 'bandpass', freq: 1400, q: 3, pan });
      this.tone({ freq: 1760, endFreq: 1200, type: 'sine', dur: 0.9, gain: 0.03, pan });
    } else if (f === 'ghidorah') {
      this.tone({ freq: 210, endFreq: 90, type: 'sawtooth', dur: 1.6, gain: 0.18, filter: { type: 'bandpass', freq: 900, endFreq: 320 }, q: 1.5, pan });
      this.tone({ freq: 315, endFreq: 150, type: 'square', dur: 1.4, gain: 0.07, detune: 12, pan });
      this.tone({ freq: 460, endFreq: 220, type: 'sawtooth', dur: 1.2, gain: 0.05, detune: -18, delay: 0.08, pan });
      this.noise({ dur: 1.7, gain: 0.12, filter: 'bandpass', freq: 1200, endFreq: 400, q: 1.4, pan });
    } else if (f === 'kong') {
      this.tone({ freq: 95, endFreq: 58, type: 'sawtooth', dur: 1.5, gain: 0.22, filter: { type: 'lowpass', freq: 700, endFreq: 220 }, q: 2, pan });
      this.tone({ freq: 142, endFreq: 86, type: 'square', dur: 1.1, gain: 0.09, detune: 8, pan });
      this.noise({ dur: 1.5, gain: 0.16, filter: 'bandpass', freq: 520, endFreq: 200, q: 1.2, pan });
      // chest pounds
      for (let i = 0; i < 3; i++) this.tone({ freq: 55, endFreq: 35, type: 'sine', dur: 0.22, gain: 0.2, delay: 0.5 + i * 0.22, pan });
    } else if (f === 'shimo') {
      this.tone({ freq: 62, endFreq: 34, type: 'sawtooth', dur: 2.0, gain: 0.2, filter: { type: 'lowpass', freq: 420, endFreq: 120 }, pan });
      this.noise({ dur: 2.1, gain: 0.16, filter: 'lowpass', freq: 900, endFreq: 180, pan });
      this.tone({ freq: 180, endFreq: 80, type: 'sine', dur: 1.8, gain: 0.06, pan });
    } else if (f === 'scylla') {
      this.tone({ freq: 300, endFreq: 120, type: 'sawtooth', dur: 1.2, gain: 0.12, filter: { type: 'bandpass', freq: 1200, q: 4 }, pan });
      this.noise({ dur: 1.3, gain: 0.18, filter: 'highpass', freq: 1800, endFreq: 600, pan });
      for (let i = 0; i < 5; i++) this.tone({ freq: 420 + i * 90, endFreq: 300 + i * 60, type: 'square', dur: 0.5, gain: 0.025, delay: i * 0.07, pan });
    } else if (f === 'tiamat') {
      this.tone({ freq: 70, endFreq: 42, type: 'sawtooth', dur: 1.8, gain: 0.2, filter: { type: 'lowpass', freq: 600, endFreq: 180 }, q: 1.8, pan });
      this.noise({ dur: 1.8, gain: 0.14, filter: 'bandpass', freq: 700, endFreq: 220, q: 1.2, pan });
      this.tone({ freq: 230, endFreq: 120, type: 'triangle', dur: 1.4, gain: 0.05, pan });
    } else {
      // Godzilla family
      const base = f === 'godzilla' ? 58 : 62;
      this.tone({ freq: base + 18, endFreq: base - 10, type: 'sawtooth', dur: 1.9, gain: 0.22, filter: { type: 'lowpass', freq: 900, endFreq: 180 }, q: 2.4, pan });
      this.tone({ freq: base * 1.5, endFreq: base * 0.9, type: 'square', dur: 1.5, gain: 0.08, detune: 9, pan });
      this.tone({ freq: base * 0.5, endFreq: base * 0.35, type: 'sine', dur: 2.2, gain: 0.12, pan });
      this.noise({ dur: 1.8, gain: 0.14, filter: 'bandpass', freq: 600, endFreq: 160, q: 1.4, pan });
      if (f === 'godzilla' && def.build?.evolved) {
        this.tone({ freq: 240, endFreq: 120, type: 'sawtooth', dur: 1.5, gain: 0.05, delay: 0.15, pan });
      }
    }
  }

  impact(power = 1, pan = 0) {
    const p = Math.max(0.3, Math.min(2, power));
    this.tone({ freq: 120 * p, endFreq: 34, type: 'sine', dur: 0.25 + p * 0.15, gain: 0.18 * p, pan });
    this.noise({ dur: 0.12 + p * 0.08, gain: 0.14 * p, filter: 'lowpass', freq: 1400, endFreq: 240, pan });
    if (p > 0.8) this.noise({ dur: 0.5, gain: 0.08 * p, filter: 'highpass', freq: 2200, endFreq: 600, pan });
  }

  stomp(power = 1) {
    this.tone({ freq: 48, endFreq: 22, type: 'sine', dur: 0.7, gain: 0.32 * power });
    this.tone({ freq: 90, endFreq: 32, type: 'sawtooth', dur: 0.5, gain: 0.1 * power, filter: { type: 'lowpass', freq: 320 } });
    this.noise({ dur: 0.65, gain: 0.2 * power, filter: 'lowpass', freq: 700, endFreq: 100 });
  }

  explosion(power = 1, pan = 0) {
    this.noise({ dur: 1.2, gain: 0.28 * power, filter: 'lowpass', freq: 2400, endFreq: 90, pan });
    this.tone({ freq: 70, endFreq: 24, type: 'sine', dur: 1.1, gain: 0.25 * power, pan });
    this.tone({ freq: 160, endFreq: 50, type: 'sawtooth', dur: 0.7, gain: 0.1 * power, filter: { type: 'lowpass', freq: 600 }, pan });
    for (let i = 0; i < 4; i++) this.noise({ dur: 0.1, gain: 0.08, filter: 'highpass', freq: 1800, delay: 0.1 + Math.random() * 0.6, pan });
  }

  glass(pan = 0) {
    this.noise({ dur: 0.5, gain: 0.09, filter: 'highpass', freq: 3200, endFreq: 1800, pan });
    for (let i = 0; i < 7; i++) this.tone({ freq: 1600 + Math.random() * 2400, endFreq: 900 + Math.random() * 1200, type: 'sine', dur: 0.12 + Math.random() * 0.2, gain: 0.015, delay: Math.random() * 0.25, pan });
  }

  whoosh(pan = 0) {
    this.noise({ dur: 0.35, gain: 0.12, filter: 'bandpass', freq: 600, endFreq: 1800, q: 1.4, pan });
  }

  beamStart(def, duration = 1.4) {
    if (!this.ctx || !this.settings.get('sound')) return () => {};
    const f = def.special;
    const t0 = this.ctx.currentTime;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(0.14, t0 + 0.08);
    g.gain.setValueAtTime(0.14, t0 + duration - 0.25);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    g.connect(this.sfx);
    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    const baseFreq = f.type === 'freezeBeam' ? 280 : f.type === 'tripleBeam' ? 120 : f.type === 'godrays' ? 440 : 90;
    osc.frequency.setValueAtTime(baseFreq, t0);
    osc.frequency.exponentialRampToValueAtTime(baseFreq * 1.8, t0 + 0.15);
    osc.frequency.exponentialRampToValueAtTime(baseFreq * 0.7, t0 + duration);
    const f1 = this.ctx.createBiquadFilter();
    f1.type = 'bandpass';
    f1.frequency.value = f.type === 'freezeBeam' ? 1800 : 700;
    f1.Q.value = 2.5;
    osc.connect(f1); f1.connect(g);
    const noise = this.ctx.createBufferSource();
    noise.buffer = this.noiseBuffer;
    noise.loop = true;
    const f2 = this.ctx.createBiquadFilter();
    f2.type = 'highpass'; f2.frequency.value = 600;
    const ng = this.ctx.createGain(); ng.gain.value = 0.07;
    noise.connect(f2); f2.connect(ng); ng.connect(g);
    const lfo = this.ctx.createOscillator();
    const lfoGain = this.ctx.createGain();
    lfo.frequency.value = 11; lfoGain.gain.value = 30;
    lfo.connect(lfoGain); lfoGain.connect(osc.frequency);
    osc.start(t0); noise.start(t0); lfo.start(t0);
    osc.stop(t0 + duration + 0.05); noise.stop(t0 + duration + 0.05); lfo.stop(t0 + duration + 0.05);
    return () => { try { g.gain.cancelScheduledValues(this.ctx.currentTime); g.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.05); } catch {} };
  }

  thunder() {
    this.noise({ dur: 2.4, gain: 0.18, filter: 'lowpass', freq: 600, endFreq: 60, attack: 0.02 });
    this.tone({ freq: 52, endFreq: 26, type: 'sine', dur: 1.8, gain: 0.12, delay: 0.15 });
  }

  alert() {
    this.tone({ freq: 220, endFreq: 220, type: 'square', dur: 0.12, gain: 0.06 });
    this.tone({ freq: 330, endFreq: 330, type: 'square', dur: 0.12, gain: 0.05, delay: 0.16 });
  }

  victory() {
    const notes = [130.8, 164.8, 196, 261.6, 329.6];
    notes.forEach((n, i) => {
      this.tone({ freq: n, type: 'triangle', dur: 1.4, gain: 0.06, delay: i * 0.13, attack: 0.02 });
      this.tone({ freq: n * 0.5, type: 'sine', dur: 1.6, gain: 0.05, delay: i * 0.13 });
    });
    this.noise({ dur: 1.8, gain: 0.05, filter: 'highpass', freq: 2000, delay: 0.5 });
  }

  defeat() {
    [110, 98, 82, 55].forEach((n, i) => this.tone({ freq: n, endFreq: n * 0.8, type: 'sawtooth', dur: 1.1, gain: 0.07, delay: i * 0.25, filter: { type: 'lowpass', freq: 400 } }));
  }

  startAmbient() {
    if (!this.ctx || this.ambient) return;
    const t0 = this.ctx.currentTime;
    const g = this.ctx.createGain();
    g.gain.value = 0.0001;
    g.gain.exponentialRampToValueAtTime(0.09, t0 + 3);
    g.connect(this.music);
    const osc1 = this.ctx.createOscillator(); osc1.type = 'sine'; osc1.frequency.value = 41.2;
    const osc2 = this.ctx.createOscillator(); osc2.type = 'triangle'; osc2.frequency.value = 61.7;
    const osc3 = this.ctx.createOscillator(); osc3.type = 'sine'; osc3.frequency.value = 82.4; osc3.detune.value = -7;
    const lfo = this.ctx.createOscillator(); lfo.frequency.value = 0.06;
    const lfoG = this.ctx.createGain(); lfoG.gain.value = 0.035;
    lfo.connect(lfoG); lfoG.connect(g.gain);
    const filter = this.ctx.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = 280;
    osc1.connect(filter); osc2.connect(filter); osc3.connect(filter); filter.connect(g);
    osc1.start(t0); osc2.start(t0); osc3.start(t0); lfo.start(t0);
    this.ambient = { g, osc1, osc2, osc3, lfo };
  }

  setWeather(kind) {
    if (this.weather === kind) return;
    this.weather = kind;
    if (!this.ctx) return;
    if (this.rain) {
      try { this.rain.stop(); } catch {}
      this.rain = null;
    }
    if (kind === 'rain' || kind === 'storm') {
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer; src.loop = true;
      const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 1200;
      const f2 = this.ctx.createBiquadFilter(); f2.type = 'lowpass'; f2.frequency.value = 7000;
      const g = this.ctx.createGain(); g.gain.value = kind === 'storm' ? 0.16 : 0.1;
      src.connect(f); f.connect(f2); f2.connect(g); g.connect(this.music);
      src.start();
      this.rain = { src, g };
    }
  }

  setMaster(on) { this.setSound(on); }
}

import * as THREE from 'three';

/* ---------------------------------------------------------------------------
   FX: pooled GPU points, rigid debris, cinematic beams, shockwaves, rain.
--------------------------------------------------------------------------- */

function canvasTexture(draw, size = 64) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  draw(ctx, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
const softCircle = canvasTexture((ctx, s) => {
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.35, 'rgba(255,255,255,0.8)');
  g.addColorStop(0.7, 'rgba(255,255,255,0.22)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, s, s);
});
const streakTexture = canvasTexture((ctx, s) => {
  const g = ctx.createLinearGradient(0, 0, 0, s);
  g.addColorStop(0, 'rgba(255,255,255,0)');
  g.addColorStop(0.5, 'rgba(255,255,255,1)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(s * 0.35, 0, s * 0.3, s);
});
const glowTexture = canvasTexture((ctx, s) => {
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.2, 'rgba(255,255,255,0.9)');
  g.addColorStop(0.5, 'rgba(255,255,255,0.3)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, s, s);
});

const PARTICLE_VERT = `
attribute float aSize;
attribute float aAlpha;
attribute vec3 color;
varying vec3 vColor;
varying float vAlpha;
void main() {
  vColor = color;
  vAlpha = aAlpha;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
  gl_Position = projectionMatrix * mv;
}`;
const PARTICLE_FRAG = `
uniform sampler2D map;
varying vec3 vColor;
varying float vAlpha;
void main() {
  vec4 t = texture2D(map, gl_PointCoord);
  if (t.a < 0.02) discard;
  gl_FragColor = vec4(vColor, t.a * vAlpha);
}`;

class ParticleLayer {
  constructor(scene, max, additive, texture) {
    this.max = max;
    this.items = [];
    this.positions = new Float32Array(max * 3);
    this.colors = new Float32Array(max * 3);
    this.sizes = new Float32Array(max);
    this.alphas = new Float32Array(max);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
    geo.setDrawRange(0, 0);
    const mat = new THREE.ShaderMaterial({
      uniforms: { map: { value: texture } },
      vertexShader: PARTICLE_VERT,
      fragmentShader: PARTICLE_FRAG,
      transparent: true,
      depthWrite: false,
      vertexColors: true,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = additive ? 4 : 2;
    scene.add(this.points);
    this.geo = geo;
  }

  emit(p) {
    if (this.items.length >= this.max) this.items.shift();
    this.items.push(p);
  }

  update(dt) {
    const items = this.items;
    let write = 0;
    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      p.life -= dt;
      if (p.life <= 0) continue;
      p.vy -= (p.gravity || 0) * dt;
      const drag = Math.max(0, 1 - (p.drag || 0) * dt);
      p.vx *= drag; p.vz *= drag;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
      if (p.y < 0.4 && p.vy < 0) {
        p.y = 0.4;
        p.vy *= -0.18;
        p.vx *= 0.7; p.vz *= 0.7;
      }
      const t = p.life / p.maxLife;
      const alpha = p.fade === 'in' ? Math.min(1, (1 - t) * 4) * t : t * (p.alpha ?? 1);
      const size = p.size * (p.grow ? (1 + (1 - t) * p.grow) : 1);
      const idx = write++;
      this.positions[idx * 3] = p.x;
      this.positions[idx * 3 + 1] = p.y;
      this.positions[idx * 3 + 2] = p.z;
      this.colors[idx * 3] = p.r;
      this.colors[idx * 3 + 1] = p.g;
      this.colors[idx * 3 + 2] = p.b;
      this.sizes[idx] = size;
      this.alphas[idx] = Math.max(0, Math.min(1, alpha));
      // keep alive items compacted
      if (write - 1 !== i) items[write - 1] = p;
    }
    items.length = write;
    this.geo.setDrawRange(0, write);
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }

  clear() { this.items.length = 0; this.geo.setDrawRange(0, 0); }
}

function hexToRgb(hex) {
  return { r: ((hex >> 16) & 255) / 255, g: ((hex >> 8) & 255) / 255, b: (hex & 255) / 255 };
}

export class Effects {
  constructor(scene, settings) {
    this.scene = scene;
    this.settings = settings;
    const scale = settings.particleCount;
    this.max = Math.floor(2200 * scale);
    this.additive = new ParticleLayer(scene, Math.floor(1200 * scale), true, softCircle);
    this.normal = new ParticleLayer(scene, Math.floor(1600 * scale), false, softCircle);
    this.debris = new DebrisPool(scene, Math.floor(150 * scale));
    this.beams = [];
    this.shockwaves = [];
    this.flashes = [];
    this.shake = { amount: 0, time: 0, duration: 0 };
    this.lightPool = [];
    this.rain = new Rain(scene, settings);
    this.enabled = true;
    this.tmp = new THREE.Vector3();
  }

  setQuality() {
    // Quality changes apply to future bursts; pools remain stable for simplicity.
    this.rain.setQuality(this.settings.get('particles'));
  }

  shakeCamera(amount, duration = 0.35) {
    if (!this.settings.get('cameraShake')) return;
    this.shake.amount = Math.max(this.shake.amount, amount);
    this.shake.time = Math.max(this.shake.time, duration);
    this.shake.duration = Math.max(this.shake.duration, duration);
  }

  getShake(dt) {
    const s = this.shake;
    if (s.time <= 0) { s.amount = 0; return { x: 0, y: 0 }; }
    s.time -= dt;
    const k = s.amount * Math.max(0, s.time / Math.max(0.001, s.duration));
    return { x: (Math.random() - 0.5) * k, y: (Math.random() - 0.5) * k };
  }

  emit(kind, pos, opts = {}) {
    const q = this.settings.particleCount;
    const n = Math.max(1, Math.round((opts.count ?? 10) * q));
    const color = opts.color ?? 0xffaa55;
    const c = hexToRgb(color);
    const speed = opts.speed ?? 8;
    const spread = opts.spread ?? 0.6;
    const size = opts.size ?? 2.2;
    const life = opts.life ?? 1;
    const gravity = opts.gravity ?? 0;
    const drag = opts.drag ?? 0.4;
    const grow = opts.grow ?? 0;
    const layer = opts.additive ? this.additive : this.normal;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const b = Math.acos(2 * Math.random() - 1);
      const sp = speed * (0.35 + Math.random() * 0.8);
      const dx = Math.sin(b) * Math.cos(a), dy = Math.cos(b), dz = Math.sin(b) * Math.sin(a);
      layer.emit({
        x: pos.x + dx * spread, y: Math.max(0.4, pos.y + dy * spread * 0.6), z: pos.z + dz * spread,
        vx: dx * sp + (opts.vx || 0), vy: dy * sp * (opts.up ?? 1) + (opts.vy || 0), vz: dz * sp + (opts.vz || 0),
        life: life * (0.6 + Math.random() * 0.8), maxLife: life,
        size: size * (0.6 + Math.random() * 0.9), r: c.r, g: c.g, b: c.b,
        gravity, drag, grow, alpha: opts.alpha ?? 0.9, fade: opts.fade,
      });
    }
  }

  dust(pos, radius = 4, count = 30, color = 0xa89a86) {
    this.emit('dust', pos, { count, color, speed: radius * 0.8, spread: radius * 0.5, size: radius * 0.9, life: 2.6, gravity: -1.8, drag: 0.7, grow: 1.8, alpha: 0.42, up: 0.4 });
    this.emit('dust', pos, { count: Math.round(count * 0.4), color: 0x6a6258, speed: radius * 0.4, spread: radius * 0.8, size: radius * 1.2, life: 3.6, gravity: -0.8, drag: 0.5, grow: 2.4, alpha: 0.25, up: 0.2 });
  }

  sparks(pos, count = 14, color = 0xffc46b, speed = 18) {
    this.emit('sparks', pos, { count, color, speed, spread: 0.4, size: 1.5, life: 0.55, gravity: 32, drag: 0.5, additive: true, alpha: 1 });
  }

  glass(pos, count = 24) {
    this.emit('glass', pos, { count, color: 0xbfe8ff, speed: 14, spread: 1.2, size: 1.2, life: 1.2, gravity: 26, drag: 0.15, additive: true, alpha: 0.8 });
  }

  fire(pos, count = 22, color = 0xff7a2e, size = 2.8) {
    this.emit('fire', pos, { count, color, speed: 12, spread: 1.2, size, life: 0.8, gravity: -7, drag: 1.2, additive: true, grow: 0.8, alpha: 0.9 });
    this.emit('smoke', pos, { count: Math.round(count * 0.5), color: 0x332f2c, speed: 6, spread: 1.6, size: size * 1.6, life: 2.2, gravity: -3, drag: 0.8, grow: 2, alpha: 0.35 });
  }

  smoke(pos, count = 18, color = 0x4b4744) {
    this.emit('smoke', pos, { count, color, speed: 5, spread: 1.4, size: 3.2, life: 2.8, gravity: -2.5, drag: 0.8, grow: 2.2, alpha: 0.3 });
  }

  ice(pos, count = 24, color = 0xbfefff) {
    this.emit('ice', pos, { count, color, speed: 14, spread: 0.9, size: 1.8, life: 1.3, gravity: 12, drag: 0.4, additive: true, alpha: 0.9 });
    this.emit('mist', pos, { count: Math.round(count * 0.5), color: 0xdff8ff, speed: 5, spread: 1.5, size: 3, life: 2.2, gravity: -1, drag: 1, grow: 2, alpha: 0.22 });
  }

  acid(pos, count = 20, color = 0xc6ff4d) {
    this.emit('acid', pos, { count, color, speed: 10, spread: 1.1, size: 2, life: 1.4, gravity: 18, drag: 0.4, additive: true, alpha: 0.9 });
    this.emit('mist', pos, { count: 10, color: 0x8fff55, speed: 4, spread: 1.4, size: 2.4, life: 2, gravity: -1, drag: 1, grow: 1.5, alpha: 0.2 });
  }

  blood(pos, count = 10) {
    this.emit('dust', pos, { count, color: 0x5a1f1f, speed: 8, spread: 0.5, size: 1.4, life: 0.9, gravity: 22, drag: 0.2, alpha: 0.55 });
  }

  explosion(pos, power = 1, color = 0xff8a3d) {
    this.fire(pos, Math.round(35 * power), color, 3.2 * power);
    this.sparks(pos, Math.round(30 * power), 0xffd27a, 26 * power);
    this.dust(pos, 8 * power, 30 * power, 0x8a7a68);
    const flash = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
    flash.position.copy(pos);
    flash.scale.setScalar(8 * power);
    this.scene.add(flash);
    const light = new THREE.PointLight(color, 220 * power, 120 * power, 2);
    light.position.copy(pos);
    this.scene.add(light);
    this.flashes.push({ sprite: flash, light, life: 0.5, maxLife: 0.5, power });
    this.shakeCamera(0.7 * power, 0.6);
  }

  shockwave(pos, radius, color = 0xffc46b) {
    const geo = new THREE.RingGeometry(0.82, 1, 64, 1);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.75, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(geo, mat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(pos.x, 1.2, pos.z);
    ring.scale.setScalar(1);
    this.scene.add(ring);
    const ring2 = new THREE.Mesh(geo, mat.clone());
    ring2.material.opacity = 0.3;
    ring2.rotation.x = -Math.PI / 2;
    ring2.position.set(pos.x, 0.7, pos.z);
    this.scene.add(ring2);
    this.shockwaves.push({ ring, ring2, life: 1.2, maxLife: 1.2, radius, color });
    this.dust(pos, radius * 0.28, Math.round(40 * this.settings.particleCount), 0xb4a48c);
  }

  beam(opts) {
    const group = new THREE.Group();
    const coreMat = new THREE.MeshBasicMaterial({ color: opts.color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false });
    const outerMat = new THREE.MeshBasicMaterial({ color: opts.secondary ?? opts.color, transparent: true, opacity: 0.25, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const core = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 10, 1, true), coreMat);
    const outer = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 12, 1, true), outerMat);
    group.add(core, outer);
    const impact = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color: opts.color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }));
    impact.scale.setScalar(10);
    const light = new THREE.PointLight(opts.color, 300, 140, 2);
    group.add(impact, light);
    this.scene.add(group);
    const b = {
      group, core, outer, impact, light, coreMat, outerMat,
      start: opts.start.clone(), end: opts.end.clone(),
      width: opts.width ?? 2.2, life: opts.duration ?? 1.2, maxLife: opts.duration ?? 1.2,
      color: opts.color, secondary: opts.secondary, sparkTimer: 0, damageTick: 0,
      updateStart: opts.updateStart || null,
    };
    this.beams.push(b);
    return b;
  }

  updateBeam(b, dt, camera) {
    if (b.updateStart) b.updateStart(b.start);
    const dir = this.tmp.subVectors(b.end, b.start);
    const len = Math.max(0.1, dir.length());
    dir.normalize();
    const mid = new THREE.Vector3().addVectors(b.start, b.end).multiplyScalar(0.5);
    b.group.position.copy(mid);
    b.group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    const pulse = 1 + Math.sin(performance.now() * 0.04) * 0.18;
    b.core.scale.set(b.width * 0.55 * pulse, len, b.width * 0.55 * pulse);
    b.outer.scale.set(b.width * 1.5 * pulse, len, b.width * 1.5 * pulse);
    b.impact.position.copy(b.end).sub(mid);
    b.impact.scale.setScalar((b.width * 4 + Math.sin(performance.now() * 0.05) * 2) * pulse);
    b.light.position.copy(b.impact.position);
    b.light.intensity = 200 + Math.random() * 120;
    const t = b.life / b.maxLife;
    b.coreMat.opacity = Math.min(1, t * 3) * 0.95;
    b.outerMat.opacity = Math.min(0.4, t * 2) * 0.35;
    b.impact.material.opacity = Math.min(1, t * 4) * 0.9;
    b.life -= dt;
    b.sparkTimer -= dt;
    if (b.sparkTimer <= 0 && b.life > 0) {
      b.sparkTimer = 0.06;
      this.sparks(b.end, 3, b.color, 16);
    }
    if (b.life <= 0) {
      this.scene.remove(b.group);
      b.core.geometry.dispose(); b.outer.geometry.dispose();
      b.coreMat.dispose(); b.outerMat.dispose();
      b.impact.material.dispose();
      return false;
    }
    return true;
  }

  update(dt, camera) {
    this.additive.update(dt);
    this.normal.update(dt);
    this.debris.update(dt);
    for (let i = this.beams.length - 1; i >= 0; i--) {
      if (!this.updateBeam(this.beams[i], dt, camera)) this.beams.splice(i, 1);
    }
    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const s = this.shockwaves[i];
      s.life -= dt;
      const t = 1 - s.life / s.maxLife;
      const sc = 1 + t * s.radius;
      s.ring.scale.setScalar(sc);
      s.ring2.scale.setScalar(sc * 0.92);
      s.ring.material.opacity = (1 - t) * 0.7;
      s.ring2.material.opacity = (1 - t) * 0.25;
      if (s.life <= 0) {
        this.scene.remove(s.ring, s.ring2);
        s.ring.geometry.dispose(); s.ring.material.dispose();
        s.ring2.material.dispose();
        this.shockwaves.splice(i, 1);
      }
    }
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.life -= dt;
      const t = f.life / f.maxLife;
      f.sprite.scale.setScalar(8 * f.power * (1 + (1 - t) * 1.8));
      f.sprite.material.opacity = t * 0.95;
      f.light.intensity = 220 * f.power * t;
      if (f.life <= 0) {
        this.scene.remove(f.sprite, f.light);
        f.sprite.material.dispose();
        this.flashes.splice(i, 1);
      }
    }
    this.rain.update(dt, camera);
  }

  clear() {
    this.additive.clear();
    this.normal.clear();
    this.debris.clear();
    for (const b of this.beams) {
      this.scene.remove(b.group);
      b.core.geometry.dispose(); b.outer.geometry.dispose();
      b.coreMat.dispose(); b.outerMat.dispose();
      b.impact.material.dispose();
    }
    this.beams.length = 0;
    for (const s of this.shockwaves) {
      this.scene.remove(s.ring, s.ring2);
      s.ring.geometry.dispose(); s.ring.material.dispose(); s.ring2.material.dispose();
    }
    this.shockwaves.length = 0;
    for (const f of this.flashes) {
      this.scene.remove(f.sprite, f.light);
      f.sprite.material.dispose();
    }
    this.flashes.length = 0;
    this.rain.clear();
  }
}

class DebrisPool {
  constructor(scene, max) {
    this.scene = scene;
    this.max = max;
    this.items = [];
    this.geo = new THREE.BoxGeometry(1, 1, 1);
    this.materials = [
      new THREE.MeshStandardMaterial({ color: 0x8a857d, roughness: 0.9 }),
      new THREE.MeshStandardMaterial({ color: 0x6a6660, roughness: 0.95 }),
      new THREE.MeshStandardMaterial({ color: 0x4d4a46, roughness: 0.9 }),
      new THREE.MeshStandardMaterial({ color: 0xa69c8c, roughness: 0.92 }),
      new THREE.MeshStandardMaterial({ color: 0x3a3a3e, roughness: 0.7, metalness: 0.3 }),
      new THREE.MeshStandardMaterial({ color: 0x7c5b40, roughness: 0.9 }),
    ];
    this.meshes = [];
    for (let i = 0; i < max; i++) {
      const m = new THREE.Mesh(this.geo, this.materials[i % this.materials.length]);
      m.visible = false;
      m.castShadow = true;
      m.receiveShadow = true;
      scene.add(m);
      this.meshes.push(m);
    }
    this.cursor = 0;
  }

  spawn(pos, size, velocity, opts = {}) {
    const mesh = this.meshes[this.cursor];
    this.cursor = (this.cursor + 1) % this.max;
    const item = {
      mesh, size, life: opts.life ?? 20,
      vx: velocity?.x || 0, vy: velocity?.y || 0, vz: velocity?.z || 0,
      ax: (Math.random() - 0.5) * (opts.spin ?? 5), ay: (Math.random() - 0.5) * (opts.spin ?? 5), az: (Math.random() - 0.5) * (opts.spin ?? 5),
      settled: false, active: true, bounces: 0,
    };
    mesh.material = opts.material || this.materials[Math.floor(Math.random() * this.materials.length)];
    mesh.scale.set(size.x, size.y, size.z);
    mesh.position.copy(pos);
    mesh.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    mesh.visible = true;
    this.items.push(item);
    if (this.items.length > this.max) {
      const old = this.items.shift();
      old.mesh.visible = false;
      old.active = false;
    }
    return item;
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const d = this.items[i];
      if (!d.active) { this.items.splice(i, 1); continue; }
      d.life -= dt;
      if (!d.settled) {
        d.vy -= 48 * dt;
        d.mesh.position.x += d.vx * dt;
        d.mesh.position.y += d.vy * dt;
        d.mesh.position.z += d.vz * dt;
        d.mesh.rotation.x += d.ax * dt;
        d.mesh.rotation.y += d.ay * dt;
        d.mesh.rotation.z += d.az * dt;
        const minY = Math.max(d.size.x, d.size.y, d.size.z) * 0.3;
        if (d.mesh.position.y < minY) {
          d.mesh.position.y = minY;
          d.vy *= -0.28;
          d.vx *= 0.68; d.vz *= 0.68;
          d.ax *= 0.7; d.ay *= 0.7; d.az *= 0.7;
          d.bounces++;
          if (Math.abs(d.vy) < 2 || d.bounces > 4) {
            d.vy = 0; d.vx *= 0.4; d.vz *= 0.4; d.ax *= 0.2; d.ay *= 0.2; d.az *= 0.2;
            d.settled = true;
          }
        }
        if (Math.abs(d.vx) + Math.abs(d.vz) < 0.2) d.settled = true;
      }
      if (d.life <= 0) {
        d.mesh.visible = false;
        d.active = false;
        this.items.splice(i, 1);
      }
    }
  }

  clear() {
    for (const d of this.items) d.mesh.visible = false;
    this.items.length = 0;
  }
}

export class Rain {
  constructor(scene, settings) {
    this.scene = scene;
    this.settings = settings;
    this.max = 1600;
    this.count = 0;
    this.positions = new Float32Array(this.max * 6);
    this.velocities = new Float32Array(this.max);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    const mat = new THREE.LineBasicMaterial({ color: 0xa9c8e8, transparent: true, opacity: 0.32, depthWrite: false });
    this.lines = new THREE.LineSegments(geo, mat);
    this.lines.frustumCulled = false;
    this.lines.visible = false;
    scene.add(this.lines);
    this.geo = geo;
    this.intensity = 0;
    this.wind = 0;
    this.setQuality(settings.get('particles'));
  }

  setQuality(q) {
    this.max = q === 'low' ? 450 : q === 'medium' ? 900 : q === 'ultra' ? 2400 : 1500;
    // Rebuild if arrays are too small
    if (this.positions.length < this.max * 6) {
      this.positions = new Float32Array(this.max * 6);
      this.velocities = new Float32Array(this.max);
      this.geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    }
    for (let i = 0; i < this.max; i++) {
      if (!this.velocities[i]) this.velocities[i] = 80 + Math.random() * 90;
    }
    this.count = this.max;
    this.geo.setDrawRange(0, 0);
  }

  setIntensity(kind) {
    this.intensity = kind === 'storm' ? 1 : kind === 'rain' ? 0.62 : 0;
    this.lines.visible = this.intensity > 0;
    this.lines.material.opacity = kind === 'storm' ? 0.42 : 0.3;
    this.wind = kind === 'storm' ? 22 : 8;
  }

  update(dt, camera) {
    if (!this.intensity) return;
    const n = Math.floor(this.max * this.intensity);
    const area = 420;
    const cx = camera ? camera.position.x : 0;
    const cz = camera ? camera.position.z : 0;
    for (let i = 0; i < n; i++) {
      const i6 = i * 6;
      let x = this.positions[i6], y = this.positions[i6 + 1], z = this.positions[i6 + 2];
      if (y < 0 || y > 260 || Math.abs(x - cx) > area || Math.abs(z - cz) > area) {
        x = cx + (Math.random() - 0.5) * area * 2;
        z = cz + (Math.random() - 0.5) * area * 2;
        y = 120 + Math.random() * 140;
      }
      const v = this.velocities[i];
      y -= v * dt;
      x += this.wind * dt;
      this.positions[i6] = x;
      this.positions[i6 + 1] = y;
      this.positions[i6 + 2] = z;
      this.positions[i6 + 3] = x - this.wind * 0.04;
      this.positions[i6 + 4] = y + 3.5;
      this.positions[i6 + 5] = z;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.setDrawRange(0, n * 2);
  }

  clear() {
    this.lines.visible = false;
    this.geo.setDrawRange(0, 0);
  }
}

import * as THREE from 'three';

/* ---------------------------------------------------------------------------
   Sky, sun/moon, clouds, fog, weather and city-light orchestration.
--------------------------------------------------------------------------- */

const PALETTES = {
  night: { top: 0x040814, horizon: 0x101b30, bottom: 0x03050a, sun: 0xa9c4ff, fog: 0x0a1322, ambient: 0x1b2338, hemiSky: 0x243a5c, hemiGround: 0x080a10, sunInt: 0.22, hemiInt: 0.45, exposure: 0.95, night: 1, fogDensity: 0.0016, cloud: 0x1b2436 },
  dawn: { top: 0x23395e, horizon: 0xff8a58, bottom: 0x3b2a2c, sun: 0xffa268, fog: 0x6b5a5c, ambient: 0x443c4c, hemiSky: 0x5a6a88, hemiGround: 0x2a1c18, sunInt: 1.25, hemiInt: 0.7, exposure: 1.02, night: 0.42, fogDensity: 0.0013, cloud: 0x8a6a64 },
  day: { top: 0x2e6cb4, horizon: 0xaecbe0, bottom: 0x66757d, sun: 0xfff2d8, fog: 0x9ba9b6, ambient: 0x5f6974, hemiSky: 0x8fb4d8, hemiGround: 0x44423e, sunInt: 2.15, hemiInt: 0.95, exposure: 1.0, night: 0, fogDensity: 0.00085, cloud: 0xd8e2ea },
  dusk: { top: 0x19274a, horizon: 0xff6338, bottom: 0x38252f, sun: 0xff7a48, fog: 0x6a4648, ambient: 0x3d2c3c, hemiSky: 0x536484, hemiGround: 0x241a1c, sunInt: 1.15, hemiInt: 0.65, exposure: 1.04, night: 0.55, fogDensity: 0.0012, cloud: 0x8a5a52 },
};

function lerp(a, b, t) { return a + (b - a) * t; }
function lerpColor(a, b, t, out = new THREE.Color()) {
  return out.setHex(a).lerp(new THREE.Color(b), t);
}
function mixHex(a, b, t) {
  const A = new THREE.Color(a), B = new THREE.Color(b);
  A.lerp(B, t);
  return A.getHex();
}

function makeCloudTexture() {
  const size = 256;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const rnd = () => Math.random();
  for (let i = 0; i < 38; i++) {
    const x = 40 + rnd() * (size - 80);
    const y = 70 + rnd() * (size - 140);
    const r = 18 + rnd() * 55;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255,255,255,0.5)');
    g.addColorStop(0.55, 'rgba(255,255,255,0.18)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

const SKY_VERT = `
varying vec3 vDir;
void main() {
  vDir = normalize((modelMatrix * vec4(position, 1.0)).xyz);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;
const SKY_FRAG = `
uniform vec3 topColor;
uniform vec3 horizonColor;
uniform vec3 bottomColor;
uniform vec3 sunColor;
uniform vec3 sunDir;
uniform float flash;
varying vec3 vDir;
void main() {
  float h = vDir.y;
  vec3 col;
  if (h > 0.0) col = mix(horizonColor, topColor, pow(clamp(h, 0.0, 1.0), 0.55));
  else col = mix(horizonColor, bottomColor, pow(clamp(-h, 0.0, 1.0), 0.45));
  float d = max(dot(normalize(vDir), normalize(sunDir)), 0.0);
  col += sunColor * pow(d, 180.0) * 1.6;
  col += sunColor * pow(d, 12.0) * 0.12;
  col += vec3(1.0, 0.95, 0.85) * flash;
  gl_FragColor = vec4(col, 1.0);
}`;

export class Environment {
  constructor(scene, settings, effects) {
    this.scene = scene;
    this.settings = settings;
    this.effects = effects;
    this.city = null;
    this.hour = 19.2;
    this.targetHour = 19.2;
    this.weather = 'clear';
    this.targetWeather = 'clear';
    this.timeSpeed = 0;
    this.autoCycle = false;
    this.renderer = null;
    this.current = { ...PALETTES.dusk };
    this.target = { ...PALETTES.dusk };
    this.fogDensity = 0.0012;
    this.targetFog = 0.0012;
    this.flash = 0;
    this.lightningTimer = 4;
    this.lightning = null;
    this.clouds = [];
    this.moonSprite = null;
    this.sunSprite = null;

    // Sky dome
    this.skyMat = new THREE.ShaderMaterial({
      uniforms: {
        topColor: { value: new THREE.Color(PALETTES.dusk.top) },
        horizonColor: { value: new THREE.Color(PALETTES.dusk.horizon) },
        bottomColor: { value: new THREE.Color(PALETTES.dusk.bottom) },
        sunColor: { value: new THREE.Color(PALETTES.dusk.sun) },
        sunDir: { value: new THREE.Vector3(0.4, 0.3, -0.8) },
        flash: { value: 0 },
      },
      vertexShader: SKY_VERT,
      fragmentShader: SKY_FRAG,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(3000, 32, 20), this.skyMat);
    this.sky.frustumCulled = false;
    scene.add(this.sky);

    // Lights
    this.hemi = new THREE.HemisphereLight(PALETTES.dusk.hemiSky, PALETTES.dusk.hemiGround, PALETTES.dusk.hemiInt);
    scene.add(this.hemi);
    this.ambient = new THREE.AmbientLight(PALETTES.dusk.ambient, 0.55);
    scene.add(this.ambient);
    this.sun = new THREE.DirectionalLight(PALETTES.dusk.sun, PALETTES.dusk.sunInt);
    this.sun.castShadow = settings.get('shadows');
    this.sun.shadow.mapSize.set(2048, 2048);
    this.sun.shadow.camera.left = -260;
    this.sun.shadow.camera.right = 260;
    this.sun.shadow.camera.top = 260;
    this.sun.shadow.camera.bottom = -260;
    this.sun.shadow.camera.near = 10;
    this.sun.shadow.camera.far = 1200;
    this.sun.shadow.bias = -0.0006;
    this.sun.shadow.normalBias = 1.2;
    this.sun.position.set(300, 500, 200);
    this.sun.target.position.set(0, 0, 0);
    scene.add(this.sun, this.sun.target);
    this.lightningLight = new THREE.DirectionalLight(0xddeaff, 0);
    this.lightningLight.position.set(-200, 500, 100);
    scene.add(this.lightningLight);

    // Stars
    const starGeo = new THREE.BufferGeometry();
    const starPos = new Float32Array(900 * 3);
    for (let i = 0; i < 900; i++) {
      const a = Math.random() * Math.PI * 2;
      const y = Math.random() * 0.85 + 0.1;
      const r = Math.sqrt(1 - y * y);
      starPos[i * 3] = Math.cos(a) * r * 2600;
      starPos[i * 3 + 1] = y * 2600;
      starPos[i * 3 + 2] = Math.sin(a) * r * 2600;
    }
    starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
    this.stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xcddcff, size: 3.2, transparent: true, opacity: 0, sizeAttenuation: true, depthWrite: false, fog: false }));
    this.stars.frustumCulled = false;
    scene.add(this.stars);

    // Sun / moon sprites
    const glow = this.makeGlowTexture();
    this.sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: glow, color: 0xffe6b0, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
    this.sunSprite.scale.setScalar(260);
    scene.add(this.sunSprite);
    this.moonSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: glow, color: 0xd8e4ff, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
    this.moonSprite.scale.setScalar(150);
    scene.add(this.moonSprite);

    // Clouds
    const cloudTex = makeCloudTexture();
    for (let i = 0; i < 16; i++) {
      const mat = new THREE.SpriteMaterial({ map: cloudTex, color: 0x8a6a64, transparent: true, opacity: 0.34, depthWrite: false, fog: false });
      const s = new THREE.Sprite(mat);
      const a = Math.random() * Math.PI * 2;
      const r = 500 + Math.random() * 1400;
      s.position.set(Math.cos(a) * r, 260 + Math.random() * 260, Math.sin(a) * r);
      const sc = 420 + Math.random() * 620;
      s.scale.set(sc, sc * 0.42, 1);
      s.userData.speed = 2 + Math.random() * 5;
      scene.add(s);
      this.clouds.push(s);
    }

    // Fog
    this.scene.fog = new THREE.FogExp2(PALETTES.dusk.fog, this.fogDensity);

    // Lightning geometry
    this.lightningGroup = new THREE.Group();
    this.lightningGroup.visible = false;
    scene.add(this.lightningGroup);
    this.lightningLife = 0;

    this.applyHour(19.2, true);
    this.setWeather('clear', true);
  }

  makeGlowTexture() {
    const c = document.createElement('canvas'); c.width = c.height = 128;
    const ctx = c.getContext('2d');
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.15, 'rgba(255,255,255,0.95)');
    g.addColorStop(0.4, 'rgba(255,255,255,0.32)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
    const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
  }

  attachCity(city) { this.city = city; this.applyCityState(); }
  attachRenderer(renderer) { this.renderer = renderer; }
  setShadows(on) {
    this.sun.castShadow = on;
    if (this.renderer) {
      this.renderer.shadowMap.enabled = on;
      this.renderer.shadowMap.needsUpdate = true;
    }
  }

  setTimePreset(name) {
    const map = { night: 0.5, sunrise: 6.2, dawn: 6.2, day: 12, noon: 12, sunset: 18.4, dusk: 18.4 };
    if (map[name] !== undefined) this.setHour(map[name]);
  }

  setHour(h) {
    this.targetHour = ((h % 24) + 24) % 24;
    this.hour = this.targetHour;
    this.applyHour(this.targetHour, false);
  }

  samplePalette(hour) {
    const keys = [
      [0, 'night'], [5, 'night'], [6.2, 'dawn'], [8.5, 'day'],
      [16.5, 'day'], [18.4, 'dusk'], [20, 'night'], [24, 'night'],
    ];
    for (let i = 0; i < keys.length - 1; i++) {
      const [h0, n0] = keys[i], [h1, n1] = keys[i + 1];
      if (hour >= h0 && hour <= h1) {
        const t = (hour - h0) / Math.max(0.0001, h1 - h0);
        const A = PALETTES[n0], B = PALETTES[n1];
        return {
          top: mixHex(A.top, B.top, t), horizon: mixHex(A.horizon, B.horizon, t), bottom: mixHex(A.bottom, B.bottom, t),
          sun: mixHex(A.sun, B.sun, t), fog: mixHex(A.fog, B.fog, t), ambient: mixHex(A.ambient, B.ambient, t),
          hemiSky: mixHex(A.hemiSky, B.hemiSky, t), hemiGround: mixHex(A.hemiGround, B.hemiGround, t),
          sunInt: lerp(A.sunInt, B.sunInt, t), hemiInt: lerp(A.hemiInt, B.hemiInt, t),
          exposure: lerp(A.exposure, B.exposure, t), night: lerp(A.night, B.night, t),
          fogDensity: lerp(A.fogDensity, B.fogDensity, t), cloud: mixHex(A.cloud, B.cloud, t),
        };
      }
    }
    return { ...PALETTES.night };
  }

  applyHour(hour, immediate = false) {
    this.hour = hour;
    const p = this.samplePalette(hour);
    this.target = p;
    if (immediate) this.current = { ...p };
    const angle = ((hour - 6) / 12) * Math.PI;
    this.sunDir = new THREE.Vector3(Math.cos(angle) * 0.8, Math.sin(angle), 0.35).normalize();
    this.moonDir = this.sunDir.clone().multiplyScalar(-1);
    this.applyCityState();
  }

  applyCityState() {
    if (!this.city) return;
    const night = this.current.night ?? 0;
    this.city.setNight(night);
    this.city.setFog(this.current.fog, this.fogDensity);
  }

  setWeather(kind, immediate = false) {
    this.weather = kind;
    this.targetWeather = kind;
    if (this.effects) this.effects.rain.setIntensity(kind);
    if (kind === 'clear') this.targetFog = this.current.fogDensity * 0.85;
    if (kind === 'rain') this.targetFog = Math.max(0.0018, this.current.fogDensity * 2.4);
    if (kind === 'storm') this.targetFog = Math.max(0.0025, this.current.fogDensity * 3.4);
    if (kind === 'fog') this.targetFog = Math.max(0.006, this.current.fogDensity * 7);
    if (immediate) this.fogDensity = this.targetFog;
    if (this.city) this.city.setWetness(kind === 'rain' || kind === 'storm');
  }

  update(dt, camera) {
    if (this.autoCycle) {
      this.hour = (this.hour + dt * 0.012) % 24;
      this.applyHour(this.hour);
    }
    // Smooth atmosphere interpolation
    const speed = 1 - Math.exp(-dt * 1.2);
    const c = this.current, t = this.target;
    for (const key of ['sunInt', 'hemiInt', 'exposure', 'night', 'fogDensity']) c[key] = lerp(c[key], t[key], speed);
    for (const key of ['top', 'horizon', 'bottom', 'sun', 'fog', 'ambient', 'hemiSky', 'hemiGround', 'cloud']) c[key] = mixHex(c[key], t[key], speed);
    this.fogDensity = lerp(this.fogDensity, this.targetFog, speed);

    // Sky uniforms
    this.skyMat.uniforms.topColor.value.setHex(c.top);
    this.skyMat.uniforms.horizonColor.value.setHex(c.horizon);
    this.skyMat.uniforms.bottomColor.value.setHex(c.bottom);
    this.skyMat.uniforms.sunColor.value.setHex(c.sun);
    this.skyMat.uniforms.sunDir.value.copy(this.sunDir);
    this.skyMat.uniforms.flash.value = this.flash;

    // Lights
    const sunElev = Math.max(0, this.sunDir.y);
    const nightFactor = c.night;
    const weatherDim = this.weather === 'storm' ? 0.4 : this.weather === 'rain' ? 0.62 : this.weather === 'fog' ? 0.55 : 1;
    this.sun.position.copy(this.sunDir).multiplyScalar(600);
    this.sun.intensity = c.sunInt * weatherDim;
    this.sun.color.setHex(c.sun);
    this.hemi.intensity = c.hemiInt * (0.75 + sunElev * 0.25);
    this.hemi.color.setHex(c.hemiSky);
    this.hemi.groundColor.setHex(c.hemiGround);
    this.ambient.color.setHex(c.ambient);
    this.ambient.intensity = 0.35 + nightFactor * 0.35;
    this.stars.material.opacity = Math.max(0, nightFactor - 0.15) * 0.9;
    this.stars.visible = this.stars.material.opacity > 0.02;
    this.sunSprite.position.copy(this.sunDir).multiplyScalar(2400);
    this.sunSprite.material.color.setHex(c.sun);
    this.sunSprite.material.opacity = Math.max(0, 0.85 - nightFactor * 0.6) * (this.weather === 'clear' ? 1 : 0.3);
    this.moonSprite.position.copy(this.moonDir).multiplyScalar(2400);
    this.moonSprite.material.opacity = Math.max(0, nightFactor * 0.9 - 0.05);
    this.scene.fog.color.setHex(c.fog);
    this.scene.fog.density = this.fogDensity;
    if (this.renderer) this.renderer.toneMappingExposure = c.exposure;
    this.applyCityState();

    // Clouds
    for (const s of this.clouds) {
      s.position.x += s.userData.speed * dt * (this.weather === 'storm' ? 3 : 1);
      if (s.position.x > 1900) s.position.x = -1900;
      s.material.color.setHex(c.cloud);
      s.material.opacity = (this.weather === 'fog' ? 0.2 : this.weather === 'storm' ? 0.55 : 0.32) * (0.6 + nightFactor * 0.4);
    }

    // Storm lightning
    if (this.weather === 'storm') {
      this.lightningTimer -= dt;
      if (this.lightningTimer <= 0) {
        this.triggerLightning(camera);
        this.lightningTimer = 2.2 + Math.random() * 5.5;
      }
    }
    if (this.lightningLife > 0) {
      this.lightningLife -= dt;
      const k = Math.max(0, this.lightningLife / 0.35);
      this.flash = k * 0.35;
      this.lightningLight.intensity = k * 3.5;
      this.lightningGroup.visible = k > 0;
      if (this.lightningLife <= 0) { this.lightningGroup.visible = false; this.flash = 0; }
    } else {
      this.lightningLight.intensity = 0;
      this.flash = 0;
    }
  }

  triggerLightning(camera) {
    const cx = camera ? camera.position.x : 0;
    const cz = camera ? camera.position.z : 0;
    const x = cx + (Math.random() - 0.5) * 500;
    const z = cz + (Math.random() - 0.5) * 500;
    while (this.lightningGroup.children.length) this.lightningGroup.remove(this.lightningGroup.children[0]);
    const pts = [];
    let px = x, py = 500, pz = z;
    for (let i = 0; i < 14; i++) {
      pts.push(new THREE.Vector3(px, py, pz));
      px += (Math.random() - 0.5) * 35;
      py -= 32 + Math.random() * 12;
      pz += (Math.random() - 0.5) * 35;
    }
    const geo = new THREE.BufferGeometry().setFromPoints(pts);
    const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: 0xcfe6ff, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
    this.lightningGroup.add(line);
    this.lightningGroup.visible = true;
    this.lightningLife = 0.35;
    this.lightningLight.position.set(x, 400, z);
    if (this.onThunder) this.onThunder();
  }

  dispose() {
    this.scene.remove(this.sky, this.hemi, this.ambient, this.sun, this.sun.target, this.lightningLight, this.stars, this.sunSprite, this.moonSprite, this.lightningGroup);
    for (const c of this.clouds) { this.scene.remove(c); c.material.dispose(); }
    this.sky.geometry.dispose();
    this.skyMat.dispose();
  }
}

import * as THREE from 'three';

/* ---------------------------------------------------------------------------
   Hong Kong-inspired destructible city. Buildings are stacked structural
   sections: damage cracks glass, exposes rebar, then peels whole sections off
   as rigid debris instead of disappearing.
--------------------------------------------------------------------------- */

const TAU = Math.PI * 2;
const rnd = (() => { let s = 1337; return () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296; })();

function hexToRgb(hex) { return { r: (hex >> 16) & 255, g: (hex >> 8) & 255, b: hex & 255 }; }
function shade(hex, amt) { const c = hexToRgb(hex); return `rgb(${Math.max(0, c.r + amt)},${Math.max(0, c.g + amt)},${Math.max(0, c.b + amt)})`; }

function makeCanvas(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }

function asphaltTexture() {
  const c = makeCanvas(512, 512), ctx = c.getContext('2d');
  ctx.fillStyle = '#2b2d30'; ctx.fillRect(0, 0, 512, 512);
  for (let i = 0; i < 9000; i++) {
    const g = 30 + Math.random() * 40;
    ctx.fillStyle = `rgba(${g},${g},${g + 2},${0.2 + Math.random() * 0.4})`;
    ctx.fillRect(Math.random() * 512, Math.random() * 512, 1 + Math.random() * 2, 1 + Math.random() * 2);
  }
  for (let i = 0; i < 18; i++) {
    ctx.strokeStyle = 'rgba(12,12,14,0.55)'; ctx.lineWidth = 1 + Math.random() * 2;
    let x = Math.random() * 512, y = Math.random() * 512;
    ctx.beginPath(); ctx.moveTo(x, y);
    for (let k = 0; k < 5; k++) { x += (Math.random() - 0.5) * 50; y += (Math.random() - 0.5) * 50; ctx.lineTo(x, y); }
    ctx.stroke();
  }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(18, 18); return t;
}

function concreteTexture() {
  const c = makeCanvas(256, 256), ctx = c.getContext('2d');
  ctx.fillStyle = '#6d6c68'; ctx.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 4000; i++) {
    const g = 70 + Math.random() * 70;
    ctx.fillStyle = `rgba(${g},${g},${g - 3},0.25)`;
    ctx.fillRect(Math.random() * 256, Math.random() * 256, 1, 1);
  }
  ctx.strokeStyle = 'rgba(40,40,38,0.35)'; ctx.lineWidth = 1;
  for (let i = 0; i < 6; i++) { ctx.beginPath(); ctx.moveTo(i * 42, 0); ctx.lineTo(i * 42, 256); ctx.stroke(); }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(5, 5); return t;
}

function windowTextures(seed) {
  const W = 128, H = 256;
  const fac = makeCanvas(W, H), emi = makeCanvas(W, H);
  const fc = fac.getContext('2d'), ec = emi.getContext('2d');
  const r = (() => { let s = seed * 99991; return () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296; })();
  const palette = [
    ['#2b3038', '#3a414c', '#6f7885'],
    ['#4a443c', '#5b5348', '#8b7d68'],
    ['#34302f', '#45403d', '#76675b'],
    ['#26343c', '#33454f', '#6e8790'],
    ['#3c2f35', '#4c3b43', '#8c6c78'],
    ['#30383a', '#3d4749', '#6e807f'],
  ];
  const p = palette[Math.floor(r() * palette.length)];
  fc.fillStyle = p[0]; fc.fillRect(0, 0, W, H);
  ec.fillStyle = '#000'; ec.fillRect(0, 0, W, H);
  const cols = 5 + Math.floor(r() * 4);
  const rows = 12 + Math.floor(r() * 8);
  const mx = 7, my = 5;
  const cw = (W - mx * 2) / cols, ch = (H - my * 2) / rows;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const wx = mx + x * cw + cw * 0.14, wy = my + y * ch + ch * 0.16;
      const ww = cw * 0.72, wh = ch * 0.62;
      const lit = r() > 0.42;
      const dayCol = r() > 0.5 ? p[1] : p[2];
      fc.fillStyle = dayCol;
      fc.fillRect(wx, wy, ww, wh);
      fc.fillStyle = 'rgba(255,255,255,0.06)';
      fc.fillRect(wx + 1, wy + 1, ww * 0.4, wh * 0.3);
      if (lit) {
        const warm = r() > 0.32;
        ec.fillStyle = warm ? `rgba(255,${190 + r() * 40},${110 + r() * 60},${0.55 + r() * 0.4})` : `rgba(${120 + r() * 60},${210 + r() * 40},255,${0.5 + r() * 0.4})`;
        ec.fillRect(wx, wy, ww, wh);
        ec.fillStyle = 'rgba(0,0,0,0.25)';
        ec.fillRect(wx + ww * 0.5, wy, 1, wh);
      }
      if (r() > 0.9) {
        fc.fillStyle = 'rgba(20,20,22,0.7)';
        fc.fillRect(wx - 2, wy + wh + 1, ww + 4, 2);
      }
    }
  }
  // balconies / vertical ribs
  if (r() > 0.5) {
    fc.fillStyle = 'rgba(0,0,0,0.25)';
    for (let i = 0; i < cols; i++) fc.fillRect(mx + i * cw, 0, 1.5, H);
  }
  const map = new THREE.CanvasTexture(fac); map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = map.wrapT = THREE.RepeatWrapping;
  const em = new THREE.CanvasTexture(emi); em.colorSpace = THREE.SRGBColorSpace;
  em.wrapS = em.wrapT = THREE.RepeatWrapping;
  return { map, emissive: em, palette: p };
}

function crackTexture() {
  const c = makeCanvas(128, 128), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 128, 128);
  ctx.strokeStyle = 'rgba(18,16,14,0.92)';
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 7; i++) {
    let x = 64 + (Math.random() - 0.5) * 20, y = 64 + (Math.random() - 0.5) * 20;
    ctx.beginPath(); ctx.moveTo(x, y);
    for (let k = 0; k < 7; k++) {
      x += (Math.random() - 0.5) * 22; y += (Math.random() - 0.5) * 22;
      ctx.lineTo(x, y);
      if (Math.random() > 0.6) { ctx.moveTo(x, y); }
    }
    ctx.stroke();
  }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

function neonTexture(text, color) {
  const c = makeCanvas(256, 64), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 256, 64);
  ctx.font = 'bold 40px "Arial Narrow", sans-serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.shadowColor = color; ctx.shadowBlur = 18;
  ctx.fillStyle = color; ctx.fillText(text, 128, 32);
  ctx.shadowBlur = 0;
  ctx.strokeStyle = 'rgba(255,255,255,0.7)'; ctx.lineWidth = 1.5;
  ctx.strokeText(text, 128, 32);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

function waterNormal() {
  const c = makeCanvas(256, 256), ctx = c.getContext('2d');
  const img = ctx.createImageData(256, 256);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 120 + Math.random() * 60;
    img.data[i] = v; img.data[i + 1] = v; img.data[i + 2] = 255; img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(24, 24); return t;
}

class Building {
  constructor(city, x, z, opts) {
    this.city = city;
    this.x = x; this.z = z;
    this.width = opts.width; this.depth = opts.depth; this.height = opts.height;
    this.halfW = opts.width / 2; this.halfD = opts.depth / 2;
    this.style = opts.style;
    this.maxHp = opts.hp;
    this.hp = opts.hp;
    this.sectionCount = opts.sections;
    this.sectionHeight = opts.height / opts.sections;
    this.sections = [];
    this.destroyed = false;
    this.burning = 0;
    this.smokeTimer = 0;
    this.group = new THREE.Group();
    this.group.position.set(x, 0, z);
    city.group.add(this.group);
    this.box = new THREE.Box3();
    this.updateBox();
    this.build(opts);
  }

  build(opts) {
    const { width: w, depth: d, height: h, style } = opts;
    const city = this.city;
    const tex = city.windowTextures[Math.floor(Math.random() * city.windowTextures.length)];
    const map = tex.map.clone(); const em = tex.emissive.clone();
    map.needsUpdate = true; em.needsUpdate = true;
    map.repeat.set(Math.max(1, w / 7), Math.max(2, h / 9));
    em.repeat.copy(map.repeat);
    const mat = new THREE.MeshStandardMaterial({
      map, emissiveMap: em, emissive: 0xffffff, emissiveIntensity: 0,
      color: 0xffffff, roughness: style === 'glass' ? 0.26 : 0.72, metalness: style === 'glass' ? 0.42 : 0.08,
      side: THREE.FrontSide,
    });
    this.material = mat;
    city.windowMaterials.push(mat);
    // plinth
    const plinthMat = city.concreteMat;
    const plinth = new THREE.Mesh(new THREE.BoxGeometry(w + 3, 2, d + 3), plinthMat);
    plinth.position.y = 1;
    plinth.castShadow = true; plinth.receiveShadow = true;
    this.group.add(plinth);
    // sections
    const n = this.sectionCount;
    let secW = w, secD = d;
    for (let i = 0; i < n; i++) {
      const sh = this.sectionHeight;
      const y = 2 + i * sh + sh / 2;
      const mesh = new THREE.Mesh(city.boxGeo, mat);
      mesh.position.set(0, y, 0);
      mesh.scale.set(secW, sh, secD);
      mesh.castShadow = true; mesh.receiveShadow = true;
      this.group.add(mesh);
      const maxHp = (this.maxHp / n) * 1.18;
      this.sections.push({ mesh, hp: maxHp, maxHp, y, height: sh, width: secW, depth: secD, destroyed: false, cracks: [] });
      // floor band
      if (i > 0) {
        const band = new THREE.Mesh(new THREE.BoxGeometry(secW + 0.4, 0.5, secD + 0.4), city.darkConcreteMat);
        band.position.y = y - sh / 2;
        band.castShadow = false; band.receiveShadow = true;
        this.group.add(band);
        this.sections[i].band = band;
      }
      secW *= 0.965; secD *= 0.965;
    }
    // roof
    const roofY = 2 + h;
    this.roof = new THREE.Group();
    this.roof.position.y = roofY;
    this.group.add(this.roof);
    const roofMat = city.darkConcreteMat;
    const tank = new THREE.Mesh(new THREE.CylinderGeometry(w * 0.13, w * 0.13, 4, 10), roofMat);
    tank.position.set((Math.random() - 0.5) * w * 0.35, 2, (Math.random() - 0.5) * d * 0.35);
    tank.castShadow = true; this.roof.add(tank);
    const ac = new THREE.Mesh(new THREE.BoxGeometry(3, 2, 3), roofMat);
    ac.position.set((Math.random() - 0.5) * w * 0.5, 1, (Math.random() - 0.5) * d * 0.5);
    ac.castShadow = true; this.roof.add(ac);
    if (Math.random() > 0.35) {
      const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.25, 10 + Math.random() * 18, 5), city.metalMat);
      ant.position.set((Math.random() - 0.5) * w * 0.4, 10, (Math.random() - 0.5) * d * 0.4);
      ant.castShadow = true; this.roof.add(ant);
      const light = new THREE.Mesh(new THREE.SphereGeometry(0.55, 6, 5), city.redGlowMat);
      light.position.copy(ant.position); light.position.y += ant.geometry.parameters.height / 2;
      this.roof.add(light);
    }
    // neon signs
    if (style === 'commercial' || Math.random() > 0.55) {
      const texts = ['九龍', 'HONG KONG', 'MONSTER', 'NIGHT MARKET', 'KAIJU', '九龙城', 'APEX', 'TITAN'];
      const colors = ['#ff3b5c', '#ffb23b', '#3bffe8', '#ff5cf0', '#8dff5c'];
      const t = texts[Math.floor(Math.random() * texts.length)];
      const col = colors[Math.floor(Math.random() * colors.length)];
      const tex = neonTexture(t, col);
      const sign = new THREE.Mesh(new THREE.PlaneGeometry(12, 3), new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false, toneMapped: false, side: THREE.DoubleSide }));
      sign.position.set((Math.random() - 0.5) * w * 0.5, 6 + Math.random() * Math.max(4, h * 0.5), d / 2 + 0.15);
      this.group.add(sign);
      this.neon = sign;
      this.neonBaseOpacity = 0.95;
    }
    // red aircraft warning light
    if (h > 90) {
      const wl = new THREE.Mesh(new THREE.SphereGeometry(0.8, 6, 5), city.redGlowMat);
      wl.position.set(0, 2 + h + 1.5, 0);
      this.group.add(wl);
      this.warningLight = wl;
    }
    this.updateBox();
  }

  updateBox() {
    this.box.min.set(this.x - this.halfW, 0, this.z - this.halfD);
    this.box.max.set(this.x + this.halfW, this.height, this.z + this.halfD);
  }

  addCrack(section) {
    if (!section || section.destroyed || section.cracks.length >= 3) return;
    const mat = new THREE.MeshBasicMaterial({ map: this.city.crackTex, transparent: true, opacity: 0.72, depthWrite: false, color: 0x111111, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -1 });
    const geo = new THREE.PlaneGeometry(section.width * (0.5 + Math.random() * 0.4), section.height * (0.45 + Math.random() * 0.4));
    const m = new THREE.Mesh(geo, mat);
    const side = Math.random() > 0.5;
    if (side) {
      m.position.set(section.width / 2 + 0.06, 0, (Math.random() - 0.5) * section.depth * 0.5);
      m.rotation.y = Math.PI / 2;
    } else {
      m.position.set((Math.random() - 0.5) * section.width * 0.5, 0, section.depth / 2 + 0.06);
    }
    m.position.y = 0;
    section.mesh.add(m);
    section.cracks.push(m);
  }

  damage(amount, point, opts = {}) {
    if (this.destroyed || amount <= 0) return 0;
    this.hp -= amount;
    const secs = this.sections.filter(s => !s.destroyed);
    if (!secs.length) { this.collapseFrom(0); return amount; }
    // choose section nearest impact height, else top
    let target = secs[secs.length - 1];
    if (point) {
      const localY = point.y;
      const candidate = secs.find(s => localY >= s.y - s.height / 2 && localY <= s.y + s.height / 2);
      if (candidate) target = candidate;
    }
    target.hp -= amount;
    this.addCrack(target);
    const city = this.city;
    if (Math.random() < 0.8) {
      const p = new THREE.Vector3(
        this.x + (Math.random() - 0.5) * this.width * 0.9,
        target.y + (Math.random() - 0.5) * target.height,
        this.z + this.depth / 2 + 0.5,
      );
      city.effects.glass(p, Math.floor(5 + amount * 0.18));
      if (Math.random() < 0.4) city.audio.glass();
    }
    if (Math.random() < 0.45) {
      city.effects.dust(new THREE.Vector3(this.x + (Math.random() - 0.5) * this.width, target.y, this.z + this.depth / 2), 3, 6, 0x8f877b);
    }
    if (this.hp < this.maxHp * 0.55) this.burning = Math.max(this.burning, 3);
    if (target.hp <= 0 || this.hp <= 0) {
      const idx = this.sections.indexOf(target);
      this.collapseFrom(idx);
    }
    return amount;
  }

  collapseFrom(index) {
    if (this.destroyed) return;
    const city = this.city;
    const secs = this.sections;
    index = Math.max(0, Math.min(index, secs.length - 1));
    let any = false;
    for (let i = index; i < secs.length; i++) {
      const s = secs[i];
      if (s.destroyed) continue;
      any = true;
      s.destroyed = true;
      s.mesh.visible = false;
      if (s.band) s.band.visible = false;
      // spawn chunks
      const count = Math.max(2, Math.floor(3 * city.settings.destructionScale));
      for (let k = 0; k < count; k++) {
        const size = new THREE.Vector3(
          s.width * (0.15 + Math.random() * 0.28),
          Math.max(1.5, s.height * (0.18 + Math.random() * 0.3)),
          s.depth * (0.15 + Math.random() * 0.28),
        );
        const pos = new THREE.Vector3(
          this.x + (Math.random() - 0.5) * s.width * 0.9,
          s.y + (Math.random() - 0.5) * s.height,
          this.z + (Math.random() - 0.5) * s.depth * 0.9,
        );
        city.effects.debris.spawn(pos, size, {
          x: (Math.random() - 0.5) * 28, y: 4 + Math.random() * 18, z: (Math.random() - 0.5) * 28,
        }, { spin: 4, life: 18 + Math.random() * 14 });
      }
      city.effects.dust(new THREE.Vector3(this.x, Math.max(2, s.y - s.height / 2), this.z), s.width * 0.45, 24, 0x9a8f80);
      city.effects.smoke(new THREE.Vector3(this.x, s.y, this.z), 8, 0x554c44);
      // exposed rebar
      for (let k = 0; k < 5; k++) {
        const rebar = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 4 + Math.random() * 5, 4), city.metalMat);
        rebar.position.set(this.x + (Math.random() - 0.5) * s.width, s.y - s.height / 2, this.z + (Math.random() - 0.5) * s.depth);
        rebar.rotation.set((Math.random() - 0.5) * 0.7, 0, (Math.random() - 0.5) * 0.7);
        city.group.add(rebar);
      }
    }
    if (!any) return;
    const remaining = secs.filter(s => !s.destroyed);
    this.height = remaining.length ? Math.max(2, remaining[remaining.length - 1].y + remaining[remaining.length - 1].height / 2) : 0;
    this.updateBox();
    if (this.height < 4) {
      this.destroyed = true;
      this.burning = 8;
      // rubble mound
      for (let k = 0; k < 8; k++) {
        const size = new THREE.Vector3(3 + Math.random() * 8, 1 + Math.random() * 3, 3 + Math.random() * 8);
        city.effects.debris.spawn(new THREE.Vector3(this.x + (Math.random() - 0.5) * this.width, 2, this.z + (Math.random() - 0.5) * this.depth), size, { x: 0, y: 2, z: 0 }, { life: 60, spin: 0.5 });
      }
    }
    city.effects.shakeCamera(0.4, 0.8);
    city.audio.explosion(0.9);
    city.destructionCount++;
    city.onDestruction?.(this);
  }

  update(dt) {
    if (this.burning > 0) {
      this.burning -= dt;
      this.smokeTimer -= dt;
      if (this.smokeTimer <= 0) {
        this.smokeTimer = 0.35 + Math.random() * 0.5;
        const y = 4 + Math.random() * Math.max(4, this.height);
        this.city.effects.fire(new THREE.Vector3(this.x + (Math.random() - 0.5) * this.width, y, this.z + (Math.random() - 0.5) * this.depth), 3, 0xff7a2e, 2.2);
        this.city.effects.smoke(new THREE.Vector3(this.x + (Math.random() - 0.5) * this.width, y + 3, this.z + (Math.random() - 0.5) * this.depth), 4, 0x3a3430);
      }
    }
    if (this.warningLight) {
      const blink = (performance.now() * 0.001 + this.x) % 2 < 0.25;
      this.warningLight.visible = blink;
    }
    if (this.neon) {
      const flick = Math.sin(performance.now() * 0.002 + this.z) > 0.96 ? 0.2 : 1;
      this.neon.material.opacity = (0.4 + this.city.night * 0.6) * flick;
    }
  }
}

class Vehicle {
  constructor(city, opts) {
    this.city = city;
    this.road = opts.road;
    this.axis = opts.axis;
    this.lane = opts.lane;
    this.dir = opts.dir;
    this.speed = opts.speed;
    this.pos = opts.pos;
    this.type = opts.type;
    this.group = new THREE.Group();
    this.wreck = null;
    this.alive = true;
    this.stopped = 0;
    this.crushTimer = 0;
    this.build();
    city.group.add(this.group);
    this.place();
  }

  build() {
    const c = this.city;
    const colors = [0xb43a32, 0x2f5f9e, 0xe8e2d6, 0x22262b, 0xd6a52e, 0x3f7f57, 0x8c3a72];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: 0.35, metalness: 0.55 });
    const dark = c.vehicleDarkMat;
    const len = this.type === 'bus' ? 14 : this.type === 'truck' ? 11 : 7.5;
    const width = this.type === 'bus' ? 3.4 : 3.2;
    const height = this.type === 'bus' ? 4.2 : 2.4;
    const body = new THREE.Mesh(new THREE.BoxGeometry(width, height, len), bodyMat);
    body.position.y = 1.4 + height / 2;
    body.castShadow = true; body.receiveShadow = true;
    this.group.add(body);
    const cabin = new THREE.Mesh(new THREE.BoxGeometry(width * 0.9, height * 0.7, len * 0.4), dark);
    cabin.position.set(0, 1.4 + height + height * 0.28, -len * 0.08);
    cabin.castShadow = true;
    this.group.add(cabin);
    if (this.type === 'bus') {
      cabin.scale.set(1.0, 0.8, 1.7);
    }
    for (const sx of [-1, 1]) {
      for (const sz of [-1, 1]) {
        const wheel = new THREE.Mesh(c.vehicleWheelGeo, dark);
        wheel.position.set(sx * width * 0.52, 1.1, sz * len * 0.3);
        wheel.rotation.z = Math.PI / 2;
        wheel.castShadow = true;
        this.group.add(wheel);
      }
    }
    // lights
    const headMat = new THREE.MeshBasicMaterial({ color: 0xfff2c4, toneMapped: false });
    const tailMat = new THREE.MeshBasicMaterial({ color: 0xff2a2a, toneMapped: false });
    for (const sx of [-1, 1]) {
      const h = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.3, 0.1), headMat);
      h.position.set(sx * width * 0.3, 1.8, -len / 2 - 0.05);
      this.group.add(h);
      const t = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.25, 0.1), tailMat);
      t.position.set(sx * width * 0.3, 1.8, len / 2 + 0.05);
      this.group.add(t);
    }
    this.headMat = headMat;
    this.bodyMat = bodyMat;
    this.len = len; this.width = width;
  }

  place() {
    if (this.axis === 'x') {
      this.group.position.set(this.pos, 0, this.road + this.lane);
      this.group.rotation.y = this.dir > 0 ? Math.PI / 2 : -Math.PI / 2;
    } else {
      this.group.position.set(this.road + this.lane, 0, this.pos);
      this.group.rotation.y = this.dir > 0 ? 0 : Math.PI;
    }
  }

  crush(force = 1, dir = null) {
    if (!this.alive) return;
    this.alive = false;
    this.wreck = {
      vx: (dir?.x || (Math.random() - 0.5)) * 22 * force,
      vy: 8 + Math.random() * 16 * force,
      vz: (dir?.z || (Math.random() - 0.5)) * 22 * force,
      ax: (Math.random() - 0.5) * 8, ay: (Math.random() - 0.5) * 8, az: (Math.random() - 0.5) * 8,
      life: 30,
    };
    this.crushTimer = 30;
    this.city.effects.sparks(this.group.position.clone().setY(4), 12, 0xffb347, 20);
    this.city.effects.fire(this.group.position.clone().setY(4), 8, 0xff7a2e, 2);
    this.city.audio.impact(1.2);
    if (Math.random() < 0.4) this.city.audio.explosion(0.6);
  }

  update(dt, monsters) {
    if (!this.alive) {
      if (this.wreck) {
        const w = this.wreck;
        w.vy -= 42 * dt;
        this.group.position.x += w.vx * dt;
        this.group.position.y += w.vy * dt;
        this.group.position.z += w.vz * dt;
        this.group.rotation.x += w.ax * dt;
        this.group.rotation.y += w.ay * dt;
        this.group.rotation.z += w.az * dt;
        if (this.group.position.y < 0.6) {
          this.group.position.y = 0.6;
          w.vy *= -0.25; w.vx *= 0.6; w.vz *= 0.6; w.ax *= 0.6; w.az *= 0.6;
        }
        w.life -= dt;
        if (w.life < 0) { this.group.visible = false; this.wreck = null; }
      }
      return;
    }
    // stop for nearby titans
    let near = false;
    for (const m of monsters) {
      const d = this.group.position.distanceTo(m.root.position);
      if (d < 55) { near = true; break; }
    }
    if (near) this.stopped = Math.min(1, this.stopped + dt * 4);
    else this.stopped = Math.max(0, this.stopped - dt * 1.5);
    if (this.stopped < 0.4) this.pos += this.dir * this.speed * dt * (1 - this.stopped);
    const limit = 260;
    if (this.pos > limit) this.pos = -limit;
    if (this.pos < -limit) this.pos = limit;
    this.place();
    // headlights
    if (this.headMat) this.headMat.color.setHex(this.city.night > 0.4 ? 0xfff2c4 : 0xfff7dd);
  }
}

class Pedestrian {
  constructor(city, x, z) {
    this.city = city;
    this.group = new THREE.Group();
    this.group.position.set(x, 0, z);
    const palette = [0xd9c3a0, 0x8a5a44, 0x4a4f58, 0x2e5b7a, 0x8a2f3a, 0x3f6a4f, 0xd8d2c8];
    const col = palette[Math.floor(Math.random() * palette.length)];
    const mat = new THREE.MeshStandardMaterial({ color: col, roughness: 0.8 });
    this.body = new THREE.Mesh(new THREE.CapsuleGeometry(0.42, 1.15, 4, 6), mat);
    this.body.position.y = 1.9; this.body.castShadow = true;
    this.group.add(this.body);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.34, 8, 6), new THREE.MeshStandardMaterial({ color: 0xc99a72, roughness: 0.7 }));
    head.position.y = 3.0; head.castShadow = true;
    this.group.add(head);
    this.legL = new THREE.Mesh(new THREE.CapsuleGeometry(0.14, 0.9, 3, 5), new THREE.MeshStandardMaterial({ color: 0x25282e }));
    this.legL.position.set(-0.22, 0.85, 0); this.group.add(this.legL);
    this.legR = this.legL.clone(); this.legR.position.x = 0.22; this.group.add(this.legR);
    this.armL = new THREE.Mesh(new THREE.CapsuleGeometry(0.11, 0.75, 3, 5), mat);
    this.armL.position.set(-0.55, 2.1, 0); this.group.add(this.armL);
    this.armR = this.armL.clone(); this.armR.position.x = 0.55; this.group.add(this.armR);
    this.alive = true;
    this.speed = 2.5 + Math.random() * 2;
    this.dir = Math.random() * TAU;
    this.panic = 0;
    this.walk = Math.random() * TAU;
    this.turn = 0;
    city.group.add(this.group);
  }

  kill() {
    if (!this.alive) return;
    this.alive = false;
    this.panic = 0;
    this.group.rotation.z = Math.PI / 2;
    this.group.position.y = 0.4;
    this.city.effects.dust(this.group.position.clone().setY(1), 1.2, 4, 0x8a7a6a);
  }

  update(dt, monsters) {
    if (!this.alive) return;
    let threat = null, threatDist = 1e9;
    for (const m of monsters) {
      const d = this.group.position.distanceTo(m.root.position);
      if (d < 95 && d < threatDist) { threat = m; threatDist = d; }
    }
    if (threat) {
      this.panic = Math.min(1, this.panic + dt * 2);
      const dx = this.group.position.x - threat.root.position.x;
      const dz = this.group.position.z - threat.root.position.z;
      this.dir = Math.atan2(dx, dz);
      this.speed = 12;
    } else {
      this.panic = Math.max(0, this.panic - dt * 0.5);
      this.speed = 2.5;
      this.turn -= dt;
      if (this.turn <= 0) { this.turn = 2 + Math.random() * 5; this.dir += (Math.random() - 0.5) * 1.2; }
    }
    this.group.position.x += Math.sin(this.dir) * this.speed * dt;
    this.group.position.z += Math.cos(this.dir) * this.speed * dt;
    if (Math.abs(this.group.position.x) > 200) this.dir = Math.PI - this.dir;
    if (Math.abs(this.group.position.z) > 200) this.dir = -this.dir;
    this.group.rotation.y = this.dir;
    this.walk += dt * (this.panic > 0.2 ? 16 : 6);
    const swing = Math.sin(this.walk) * (this.panic > 0.2 ? 0.9 : 0.45);
    this.legL.rotation.x = swing; this.legR.rotation.x = -swing;
    this.armL.rotation.x = -swing * 0.8; this.armR.rotation.x = swing * 0.8;
    if (this.panic > 0.3) { this.armL.rotation.z = 0.8; this.armR.rotation.z = -0.8; }
    this.group.position.y = Math.abs(Math.sin(this.walk)) * 0.08;
  }
}

class StreetProp {
  constructor(city, type, x, z) {
    this.city = city;
    this.type = type;
    this.group = new THREE.Group();
    this.group.position.set(x, 0, z);
    this.alive = true;
    this.vx = 0; this.vz = 0; this.vy = 0;
    this.build();
    city.group.add(this.group);
  }
  build() {
    const c = this.city;
    if (this.type === 'tree') {
      const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.5, 4, 6), c.barkMat);
      trunk.position.y = 2; trunk.castShadow = true; this.group.add(trunk);
      for (let i = 0; i < 4; i++) {
        const leaf = new THREE.Mesh(new THREE.IcosahedronGeometry(2.4 + Math.random() * 1.6, 1), c.leafMat);
        leaf.position.set((Math.random() - 0.5) * 3, 5 + Math.random() * 3, (Math.random() - 0.5) * 3);
        leaf.castShadow = true; this.group.add(leaf);
      }
    } else if (this.type === 'streetlight') {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.22, 12, 6), c.metalMat);
      pole.position.y = 6; pole.castShadow = true; this.group.add(pole);
      const arm = new THREE.Mesh(new THREE.BoxGeometry(3.5, 0.2, 0.2), c.metalMat);
      arm.position.set(1.5, 12, 0); this.group.add(arm);
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.35, 8, 6), c.streetGlowMat);
      bulb.position.set(3.2, 11.8, 0); this.group.add(bulb);
      const cone = new THREE.Mesh(new THREE.ConeGeometry(4.5, 9, 16, 1, true), c.lightConeMat);
      cone.position.set(3.2, 7.5, 0); this.group.add(cone);
      this.cone = cone;
    } else if (this.type === 'barrier') {
      const m = new THREE.Mesh(new THREE.BoxGeometry(4, 1.2, 0.6), c.barrierMat);
      m.position.y = 0.8; m.castShadow = true; this.group.add(m);
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(4.1, 0.2, 0.62), c.yellowMat);
      stripe.position.y = 1.1; this.group.add(stripe);
    } else if (this.type === 'bench') {
      const seat = new THREE.Mesh(new THREE.BoxGeometry(3, 0.25, 1), c.barkMat);
      seat.position.y = 1; this.group.add(seat);
      for (const s of [-1, 1]) {
        const leg = new THREE.Mesh(new THREE.BoxGeometry(0.2, 1, 0.8), c.metalMat);
        leg.position.set(s * 1.1, 0.5, 0); this.group.add(leg);
      }
    } else if (this.type === 'dumpster') {
      const m = new THREE.Mesh(new THREE.BoxGeometry(3.4, 2.4, 2), c.greenMat);
      m.position.y = 1.4; m.castShadow = true; this.group.add(m);
    }
  }
  knock(force, dir) {
    if (!this.alive) return;
    this.alive = false;
    this.vx = (dir?.x || (Math.random() - 0.5)) * force * 12;
    this.vz = (dir?.z || (Math.random() - 0.5)) * force * 12;
    this.vy = 5 + Math.random() * 8;
  }
  update(dt) {
    if (this.alive) {
      if (this.type === 'streetlight' && this.cone) this.cone.material.opacity = this.city.night * 0.12;
      return;
    }
    this.vy -= 30 * dt;
    this.group.position.x += this.vx * dt;
    this.group.position.y += this.vy * dt;
    this.group.position.z += this.vz * dt;
    this.group.rotation.x += this.vx * dt * 0.05;
    this.group.rotation.z += this.vz * dt * 0.05;
    if (this.group.position.y < 0.5) {
      this.group.position.y = 0.5;
      this.vy *= -0.2; this.vx *= 0.7; this.vz *= 0.7;
      if (Math.abs(this.vy) < 0.5) { this.vx = 0; this.vz = 0; this.vy = 0; }
    }
  }
}

export class City {
  constructor(scene, settings, effects, audio) {
    this.scene = scene;
    this.settings = settings;
    this.effects = effects;
    this.audio = audio;
    this.group = new THREE.Group();
    scene.add(this.group);
    this.buildings = [];
    this.vehicles = [];
    this.pedestrians = [];
    this.props = [];
    this.windowMaterials = [];
    this.puddles = [];
    this.streetLights = [];
    this.night = 0.5;
    this.destructionCount = 0;
    this.onDestruction = null;
    this.boxGeo = new THREE.BoxGeometry(1, 1, 1);
    this.vehicleWheelGeo = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 10);
    this.crackTex = crackTexture();
    this.windowTextures = [];
    for (let i = 0; i < 8; i++) this.windowTextures.push(windowTextures(i + 3));
    this.asphaltTex = asphaltTexture();
    this.concreteTex = concreteTexture();
    this.materials();
    this.buildGround();
    this.buildRoads();
    this.buildCity();
    this.buildHarbor();
    this.buildBridge();
    this.buildMountains();
    this.buildPlaza();
    this.spawnTraffic();
    this.spawnCrowd();
    this.spawnProps();
    this.setNight(0.5);
  }

  materials() {
    this.asphaltMat = new THREE.MeshStandardMaterial({ map: this.asphaltTex, color: 0x9a9a9a, roughness: 0.92, metalness: 0.05 });
    this.concreteMat = new THREE.MeshStandardMaterial({ map: this.concreteTex, color: 0xa8a8a4, roughness: 0.9, metalness: 0.02 });
    this.darkConcreteMat = new THREE.MeshStandardMaterial({ map: this.concreteTex, color: 0x5e5d58, roughness: 0.92 });
    this.metalMat = new THREE.MeshStandardMaterial({ color: 0x5a5f66, roughness: 0.35, metalness: 0.85 });
    this.vehicleDarkMat = new THREE.MeshStandardMaterial({ color: 0x17191d, roughness: 0.4, metalness: 0.5 });
    this.barkMat = new THREE.MeshStandardMaterial({ color: 0x4a3426, roughness: 0.95 });
    this.leafMat = new THREE.MeshStandardMaterial({ color: 0x2e4d2a, roughness: 0.9 });
    this.barrierMat = new THREE.MeshStandardMaterial({ color: 0xd05a2a, roughness: 0.7 });
    this.yellowMat = new THREE.MeshStandardMaterial({ color: 0xffc93b, roughness: 0.5 });
    this.greenMat = new THREE.MeshStandardMaterial({ color: 0x2d5a3d, roughness: 0.7, metalness: 0.2 });
    this.redGlowMat = new THREE.MeshBasicMaterial({ color: 0xff2a2a, toneMapped: false });
    this.streetGlowMat = new THREE.MeshBasicMaterial({ color: 0xffd9a0, toneMapped: false });
    this.lightConeMat = new THREE.MeshBasicMaterial({ color: 0xffd9a0, transparent: true, opacity: 0.06, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    this.puddleMat = new THREE.MeshStandardMaterial({ color: 0x14242e, roughness: 0.08, metalness: 0.85, transparent: true, opacity: 0 });
    this.lineMat = new THREE.MeshBasicMaterial({ color: 0xd8d2bd, transparent: true, opacity: 0.55 });
    this.waterMat = new THREE.MeshStandardMaterial({ color: 0x0a2532, roughness: 0.14, metalness: 0.72, bumpMap: waterNormal(), bumpScale: 0.8 });
  }

  buildGround() {
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(1600, 1600), this.asphaltMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    ground.position.y = -0.05;
    this.group.add(ground);
    this.ground = ground;
    // outer terrain
    const outer = new THREE.Mesh(new THREE.PlaneGeometry(4000, 4000), new THREE.MeshStandardMaterial({ color: 0x20262a, roughness: 0.95 }));
    outer.rotation.x = -Math.PI / 2;
    outer.position.y = -0.12;
    outer.receiveShadow = true;
    this.group.add(outer);
  }

  buildRoads() {
    const roads = [0, -86, 86, -172, 172];
    const length = 420;
    for (const r of roads) {
      for (const axis of ['x', 'z']) {
        const strip = new THREE.Mesh(new THREE.PlaneGeometry(24, length), this.asphaltMat);
        strip.rotation.x = -Math.PI / 2;
        if (axis === 'x') { strip.position.set(0, 0.02, r); strip.rotation.z = Math.PI / 2; }
        else strip.position.set(r, 0.02, 0);
        strip.receiveShadow = true;
        this.group.add(strip);
        // lane dashes
        for (let i = -length / 2; i < length / 2; i += 13) {
          if (Math.abs(i) < 14) continue;
          const dash = new THREE.Mesh(new THREE.PlaneGeometry(0.35, 4.5), this.lineMat);
          dash.rotation.x = -Math.PI / 2;
          if (axis === 'x') { dash.position.set(i, 0.035, r); dash.rotation.z = Math.PI / 2; }
          else dash.position.set(r, 0.035, i);
          this.group.add(dash);
        }
      }
    }
    // crosswalks at central intersections
    for (const x of [-86, 0, 86]) {
      for (const z of [-86, 0, 86]) {
        for (let i = -5; i <= 5; i++) {
          const stripe = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 7), this.lineMat);
          stripe.rotation.x = -Math.PI / 2;
          stripe.position.set(x + i * 2.1, 0.04, z + 14);
          this.group.add(stripe);
          const stripe2 = stripe.clone();
          stripe2.position.z = z - 14;
          this.group.add(stripe2);
        }
      }
    }
    // curbs around blocks
    const blockCenters = [-129, -43, 43, 129];
    for (const bx of blockCenters) {
      for (const bz of blockCenters) {
        for (const [dx, dz, w, d] of [[0, -33, 68, 1.2], [0, 33, 68, 1.2], [-33, 0, 1.2, 68], [33, 0, 1.2, 68]]) {
          const curb = new THREE.Mesh(new THREE.BoxGeometry(w, 0.55, d), this.concreteMat);
          curb.position.set(bx + dx, 0.22, bz + dz);
          curb.receiveShadow = true;
          this.group.add(curb);
        }
      }
    }
  }

  buildCity() {
    const centers = [-129, -43, 43, 129];
    for (const bx of centers) {
      for (const bz of centers) {
        const central = Math.abs(bx) <= 43 && Math.abs(bz) <= 43;
        if (central) continue;
        // sidewalk slab
        const slab = new THREE.Mesh(new THREE.BoxGeometry(64, 0.35, 64), this.concreteMat);
        slab.position.set(bx, 0.17, bz);
        slab.receiveShadow = true;
        this.group.add(slab);
        const lots = 2 + Math.floor(rnd() * 2);
        const placed = [];
        for (let k = 0; k < lots; k++) {
          let w = 18 + rnd() * 16, d = 18 + rnd() * 16;
          let lx = bx + (rnd() - 0.5) * (58 - w);
          let lz = bz + (rnd() - 0.5) * (58 - d);
          let tries = 0;
          while (placed.some(p => Math.abs(p.x - lx) < (p.w + w) / 2 + 3 && Math.abs(p.z - lz) < (p.d + d) / 2 + 3) && tries++ < 20) {
            lx = bx + (rnd() - 0.5) * (58 - w);
            lz = bz + (rnd() - 0.5) * (58 - d);
          }
          if (placed.some(p => Math.abs(p.x - lx) < (p.w + w) / 2 + 2 && Math.abs(p.z - lz) < (p.d + d) / 2 + 2)) continue;
          placed.push({ x: lx, z: lz, w, d });
          const dist = Math.hypot(lx, lz);
          const heightBase = dist < 130 ? 110 : dist < 200 ? 80 : 55;
          const height = heightBase + rnd() * 120 - 20;
          const sections = 4 + Math.floor(rnd() * 5);
          const hp = 180 + height * 1.8;
          const style = rnd() > 0.55 ? 'glass' : rnd() > 0.4 ? 'commercial' : 'apartment';
          this.buildings.push(new Building(this, lx, lz, { width: w, depth: d, height: Math.max(35, height), sections, hp, style }));
        }
      }
    }
    // outer low-rise ring
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * TAU + rnd() * 0.2;
      const r = 245 + rnd() * 90;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (Math.abs(x) < 220 && Math.abs(z) < 220) continue;
      const w = 20 + rnd() * 25, d = 20 + rnd() * 25;
      const h = 30 + rnd() * 85;
      this.buildings.push(new Building(this, x, z, { width: w, depth: d, height: h, sections: 3 + Math.floor(rnd() * 3), hp: 130 + h * 1.4, style: 'apartment' }));
    }
    // a few mega towers
    for (const [x, z, w, d, h] of [[-155, 155, 30, 30, 230], [155, -155, 28, 28, 210], [-160, -160, 26, 26, 190]]) {
      this.buildings.push(new Building(this, x, z, { width: w, depth: d, height: h, sections: 9, hp: 520, style: 'glass' }));
    }
  }

  buildHarbor() {
    const water = new THREE.Mesh(new THREE.PlaneGeometry(1500, 1800), this.waterMat);
    water.rotation.x = -Math.PI / 2;
    water.position.set(980, 0.06, 0);
    water.receiveShadow = true;
    this.group.add(water);
    this.water = water;
    // dock
    const dock = new THREE.Mesh(new THREE.BoxGeometry(100, 1.2, 520), this.concreteMat);
    dock.position.set(270, 0.6, 0);
    dock.receiveShadow = true; this.group.add(dock);
    for (let i = 0; i < 6; i++) {
      const bollard = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 2.2, 6), this.metalMat);
      bollard.position.set(315, 1.2, -200 + i * 80); this.group.add(bollard);
    }
    // cargo ships
    for (let s = 0; s < 2; s++) {
      const ship = new THREE.Group();
      const hull = new THREE.Mesh(new THREE.BoxGeometry(55, 12, 220), new THREE.MeshStandardMaterial({ color: 0x3a2f2a, roughness: 0.8 }));
      hull.position.y = 4; hull.castShadow = true; ship.add(hull);
      const deck = new THREE.Mesh(new THREE.BoxGeometry(52, 1, 210), new THREE.MeshStandardMaterial({ color: 0x5b5148, roughness: 0.8 }));
      deck.position.y = 10; ship.add(deck);
      const colors = [0xc23a2a, 0x2a6ac2, 0x2aa25a, 0xd8a02a, 0x7a2a8a];
      for (let i = 0; i < 32; i++) {
        const c = new THREE.Mesh(new THREE.BoxGeometry(9, 6, 18), new THREE.MeshStandardMaterial({ color: colors[i % colors.length], roughness: 0.7, metalness: 0.3 }));
        c.position.set((i % 4 - 1.5) * 11, 14, -85 + Math.floor(i / 4) * 20);
        c.castShadow = true; ship.add(c);
      }
      const bridge = new THREE.Mesh(new THREE.BoxGeometry(20, 18, 24), new THREE.MeshStandardMaterial({ color: 0xd8d2c4, roughness: 0.6 }));
      bridge.position.set(0, 19, 90); ship.add(bridge);
      ship.position.set(430 + s * 220, 0, -120 + s * 300);
      ship.rotation.y = Math.PI / 2 + (s ? 0.06 : -0.04);
      this.group.add(ship);
    }
    // cranes
    for (let i = 0; i < 3; i++) {
      const crane = new THREE.Group();
      const legMat = this.metalMat;
      for (const [dx, dz] of [[-6, -6], [6, -6], [-6, 6], [6, 6]]) {
        const leg = new THREE.Mesh(new THREE.BoxGeometry(1.4, 34, 1.4), legMat);
        leg.position.set(dx, 17, dz); leg.castShadow = true; crane.add(leg);
      }
      const top = new THREE.Mesh(new THREE.BoxGeometry(50, 1.6, 4), legMat);
      top.position.set(10, 34, 0); crane.add(top);
      const cab = new THREE.Mesh(new THREE.BoxGeometry(6, 5, 6), this.yellowMat);
      cab.position.set(0, 32, 0); crane.add(cab);
      crane.position.set(290, 1, -180 + i * 160);
      this.group.add(crane);
    }
  }

  buildBridge() {
    const bridge = new THREE.Group();
    const deckMat = new THREE.MeshStandardMaterial({ color: 0x555a60, roughness: 0.7, metalness: 0.4 });
    const deck = new THREE.Mesh(new THREE.BoxGeometry(650, 3, 18), deckMat);
    deck.position.set(600, 28, -260);
    deck.castShadow = true; deck.receiveShadow = true;
    bridge.add(deck);
    for (const x of [350, 850]) {
      const tower = new THREE.Group();
      for (const s of [-1, 1]) {
        const leg = new THREE.Mesh(new THREE.BoxGeometry(4, 120, 4), deckMat);
        leg.position.set(0, 60, s * 16); leg.castShadow = true; tower.add(leg);
      }
      const cross = new THREE.Mesh(new THREE.BoxGeometry(5, 5, 38), deckMat);
      cross.position.y = 78; tower.add(cross);
      tower.position.set(x, 0, -260);
      bridge.add(tower);
      // cables
      for (let i = 0; i < 12; i++) {
        const t = i / 11;
        const px = x + (t - 0.5) * 300;
        const py = 78 - Math.abs(t - 0.5) * 52;
        const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x, 112, -260), new THREE.Vector3(px, py, -260)]), new THREE.LineBasicMaterial({ color: 0x9aa3ad, transparent: true, opacity: 0.7 }));
        bridge.add(line);
      }
    }
    // pillars
    for (let i = 0; i < 6; i++) {
      const p = new THREE.Mesh(new THREE.BoxGeometry(8, 28, 8), this.concreteMat);
      p.position.set(320 + i * 100, 14, -260);
      p.castShadow = true; bridge.add(p);
    }
    this.group.add(bridge);
  }

  buildMountains() {
    const mat = new THREE.MeshStandardMaterial({ color: 0x222c33, roughness: 0.95, flatShading: true });
    for (let i = 0; i < 16; i++) {
      const a = -Math.PI * 0.9 + (i / 15) * Math.PI * 1.1;
      const r = 800 + rnd() * 450;
      const h = 180 + rnd() * 420;
      const geo = new THREE.ConeGeometry(220 + rnd() * 260, h, 5 + Math.floor(rnd() * 3));
      const pos = geo.attributes.position;
      for (let v = 0; v < pos.count; v++) {
        pos.setX(v, pos.getX(v) * (0.75 + rnd() * 0.5));
        pos.setZ(v, pos.getZ(v) * (0.75 + rnd() * 0.5));
      }
      geo.computeVertexNormals();
      const m = new THREE.Mesh(geo, mat);
      m.position.set(Math.cos(a) * r, h / 2 - 20, Math.sin(a) * r);
      m.rotation.y = rnd() * TAU;
      this.group.add(m);
    }
  }

  buildPlaza() {
    const plaza = new THREE.Mesh(new THREE.BoxGeometry(124, 0.3, 124), this.concreteMat);
    plaza.position.set(0, 0.15, 0);
    plaza.receiveShadow = true;
    this.group.add(plaza);
    // broken monument
    const mon = new THREE.Group();
    const base = new THREE.Mesh(new THREE.CylinderGeometry(8, 10, 3, 8), this.darkConcreteMat);
    base.position.y = 1.5; mon.add(base);
    const col = new THREE.Mesh(new THREE.CylinderGeometry(2, 2.8, 20, 8), this.concreteMat);
    col.position.y = 12; col.rotation.z = 0.12; mon.add(col);
    const top = new THREE.Mesh(new THREE.IcosahedronGeometry(3, 0), this.darkConcreteMat);
    top.position.set(-1.5, 23, 0); mon.add(top);
    mon.position.set(0, 0, -20);
    this.group.add(mon);
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU;
      this.props.push(new StreetProp(this, 'tree', Math.cos(a) * 48, Math.sin(a) * 48));
      if (i % 3 === 0) this.props.push(new StreetProp(this, 'bench', Math.cos(a) * 38, Math.sin(a) * 38));
    }
    // puddles
    for (let i = 0; i < 16; i++) {
      const p = new THREE.Mesh(new THREE.CircleGeometry(2 + Math.random() * 6, 12), this.puddleMat);
      p.rotation.x = -Math.PI / 2;
      p.position.set((Math.random() - 0.5) * 380, 0.06, (Math.random() - 0.5) * 380);
      p.scale.y = 0.4 + Math.random() * 0.7;
      this.group.add(p);
      this.puddles.push(p);
    }
  }

  spawnTraffic() {
    const roads = [-172, -86, 0, 86, 172];
    const colors = ['car', 'car', 'car', 'truck', 'bus'];
    for (let i = 0; i < 22; i++) {
      const axis = Math.random() > 0.5 ? 'x' : 'z';
      const road = roads[Math.floor(Math.random() * roads.length)];
      const dir = Math.random() > 0.5 ? 1 : -1;
      const lane = dir > 0 ? -5.5 : 5.5;
      const pos = (Math.random() - 0.5) * 400;
      this.vehicles.push(new Vehicle(this, { axis, road, lane, dir, pos, speed: 14 + Math.random() * 12, type: colors[Math.floor(Math.random() * colors.length)] }));
    }
  }

  spawnCrowd() {
    for (let i = 0; i < 40; i++) {
      let x = (Math.random() - 0.5) * 360;
      let z = (Math.random() - 0.5) * 360;
      if (Math.abs(x) < 20 || Math.abs(z) < 20) x += 30;
      this.pedestrians.push(new Pedestrian(this, x, z));
    }
  }

  spawnProps() {
    const roads = [-172, -86, 0, 86, 172];
    for (const x of roads) {
      for (const z of roads) {
        if (Math.random() > 0.35) this.props.push(new StreetProp(this, 'streetlight', x + 14, z + 14));
        if (Math.random() > 0.7) this.props.push(new StreetProp(this, 'barrier', x - 12, z + 8));
      }
    }
    for (let i = 0; i < 14; i++) {
      this.props.push(new StreetProp(this, 'dumpster', (Math.random() - 0.5) * 300, (Math.random() - 0.5) * 300));
    }
  }

  setNight(night) {
    this.night = night;
    for (const m of this.windowMaterials) m.emissiveIntensity = night * 1.9;
    for (const p of this.puddles) p.material.opacity = this.wet ? 0.65 : 0;
    if (this.water) this.water.material.emissive = new THREE.Color(0x06121a).multiplyScalar(night * 0.3);
    for (const v of this.vehicles) if (v.headMat) v.headMat.color.setHex(night > 0.35 ? 0xfff2c4 : 0xfff7dd);
    for (const s of this.props) if (s.cone) s.cone.material.opacity = night * 0.12;
  }

  setWetness(wet) {
    this.wet = wet;
    this.asphaltMat.roughness = wet ? 0.32 : 0.92;
    this.asphaltMat.metalness = wet ? 0.35 : 0.05;
    this.asphaltMat.color.setHex(wet ? 0x8a8a8a : 0x9a9a9a);
    this.concreteMat.roughness = wet ? 0.55 : 0.9;
    for (const p of this.puddles) p.material.opacity = wet ? 0.62 : 0;
    if (this.water) this.water.material.roughness = wet ? 0.08 : 0.14;
  }

  setFog(color, density) {
    // reserved for per-material fog tinting
  }

  damageAt(point, radius, amount, opts = {}) {
    let hits = 0;
    for (const b of this.buildings) {
      if (b.destroyed) continue;
      const dx = Math.max(b.box.min.x - point.x, 0, point.x - b.box.max.x);
      const dz = Math.max(b.box.min.z - point.z, 0, point.z - b.box.max.z);
      const d = Math.hypot(dx, dz);
      if (d <= radius) {
        const fall = 1 - d / Math.max(1, radius);
        hits += b.damage(amount * (0.45 + fall * 0.75), point, opts);
      }
    }
    for (const v of this.vehicles) {
      if (!v.alive) continue;
      if (v.group.position.distanceTo(point) < radius + 6) {
        v.crush(1, new THREE.Vector3().subVectors(v.group.position, point).normalize());
        hits++;
      }
    }
    for (const p of this.pedestrians) {
      if (!p.alive) continue;
      if (p.group.position.distanceTo(point) < radius + 3) {
        if (Math.random() < 0.4) p.kill(); else p.panic = 1;
        hits++;
      }
    }
    for (const p of this.props) {
      if (!p.alive) continue;
      if (p.group.position.distanceTo(point) < radius + 4) {
        p.knock(1, new THREE.Vector3().subVectors(p.group.position, point).normalize());
        hits++;
      }
    }
    return hits;
  }

  raycastBuilding(origin, dir, maxDist = 300) {
    const ray = new THREE.Ray(origin, dir.clone().normalize());
    let best = null;
    for (const b of this.buildings) {
      if (b.destroyed) continue;
      const hit = ray.intersectBox(b.box, new THREE.Vector3());
      if (hit) {
        const dist = hit.distanceTo(origin);
        if (dist <= maxDist && (!best || dist < best.distance)) best = { distance: dist, point: hit, building: b };
      }
    }
    return best;
  }

  collideCircle(x, z, radius) {
    let pushX = 0, pushZ = 0, hit = null;
    for (const b of this.buildings) {
      if (b.destroyed) continue;
      const minX = b.box.min.x - radius, maxX = b.box.max.x + radius;
      const minZ = b.box.min.z - radius, maxZ = b.box.max.z + radius;
      if (x > minX && x < maxX && z > minZ && z < maxZ) {
        const left = x - minX, right = maxX - x, top = z - minZ, bottom = maxZ - z;
        const m = Math.min(left, right, top, bottom);
        if (m === left) pushX -= left;
        else if (m === right) pushX += right;
        else if (m === top) pushZ -= top;
        else pushZ += bottom;
        hit = b;
      }
    }
    return { pushX, pushZ, hit };
  }

  update(dt, camera, monsters) {
    for (const b of this.buildings) b.update(dt);
    for (const v of this.vehicles) v.update(dt, monsters);
    for (const p of this.pedestrians) p.update(dt, monsters);
    for (const p of this.props) p.update(dt);
    if (this.water) {
      const t = performance.now() * 0.00005;
      this.waterMat.bumpMap.offset.set(t * 0.4, t);
    }
    // keep NPC / traffic simulation bounded
    if (this.pedestrians.length < 24) this.spawnCrowd();
  }

  spawnVehicle(type = 'car', pos = null) {
    const p = pos || new THREE.Vector3((Math.random() - 0.5) * 120, 0, (Math.random() - 0.5) * 120);
    const v = new Vehicle(this, { axis: 'z', road: p.x, lane: 0, dir: 1, pos: p.z, speed: 10, type });
    this.vehicles.push(v);
    return v;
  }

  spawnNPC(pos) {
    const p = pos || new THREE.Vector3((Math.random() - 0.5) * 100, 0, (Math.random() - 0.5) * 100);
    const n = new Pedestrian(this, p.x, p.z);
    this.pedestrians.push(n);
    return n;
  }

  spawnProp(type, pos) {
    const p = new StreetProp(this, type, pos.x, pos.z);
    this.props.push(p);
    return p;
  }

  reset() {
    this.dispose();
    this.buildings = [];
    this.vehicles = [];
    this.pedestrians = [];
    this.props = [];
    this.windowMaterials = [];
    this.puddles = [];
    this.destructionCount = 0;
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.buildGround();
    this.buildRoads();
    this.buildCity();
    this.buildHarbor();
    this.buildBridge();
    this.buildMountains();
    this.buildPlaza();
    this.spawnTraffic();
    this.spawnCrowd();
    this.spawnProps();
    this.setNight(this.night);
    this.setWetness(this.wet);
  }

  dispose() {
    this.scene.remove(this.group);
    this.group.traverse(o => {
      if (o.geometry && o.geometry !== this.boxGeo && o.geometry !== this.vehicleWheelGeo) o.geometry.dispose?.();
      if (o.material && o.material !== this.asphaltMat && o.material !== this.concreteMat) {
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  }
}

import * as THREE from 'three';
import { createMonsterModel } from '../monsters/models.js';
import { animateMonster, setRigTeamColor } from '../monsters/animation.js';
import { TEAM_COLORS } from '../monsters/data.js';

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const damp = (v, target, lambda, dt) => v + (target - v) * (1 - Math.exp(-lambda * dt));

function attackStats(def) {
  const a = def.attack / 100;
  const h = def.height;
  return {
    light: { dur: 0.52, hit: 0.28, range: h * 0.44, arc: 0.95, damage: 9 + a * 11, force: 6 + a * 7, stamina: 4, cd: 0.04 },
    heavy: { dur: 0.94, hit: 0.5, range: h * 0.56, arc: 0.8, damage: 18 + a * 19, force: 14 + a * 12, stamina: 12, cd: 0.35 },
    tail: { dur: 0.82, hit: 0.4, range: h * 0.72, arc: 1.85, damage: 14 + a * 13, force: 12 + a * 9, stamina: 10, cd: 0.25 },
    bite: { dur: 0.62, hit: 0.3, range: h * 0.36, arc: 0.62, damage: 12 + a * 15, force: 8 + a * 7, stamina: 5, cd: 0.08 },
    stomp: { dur: 0.82, hit: 0.56, range: h * 0.46, arc: TAU, damage: 14 + a * 13, force: 16 + a * 11, stamina: 10, cd: 0.4, aoe: true },
    grab: { dur: 1.5, hit: 0.34, range: h * 0.34, arc: 0.7, damage: 6, force: 10, stamina: 14, cd: 3 },
    roar: { dur: 1.5, hit: 0.18, range: 0, arc: TAU, damage: 0, force: 0, stamina: 4, cd: 4.5 },
    axe: { dur: 1.0, hit: 0.52, range: h * 0.55, arc: 0.8, damage: 22 + a * 20, force: 18 + a * 12, stamina: 14, cd: 0.6 },
  };
}

class MonsterAI {
  constructor(monster) {
    this.m = monster;
    this.think = 0;
    this.target = null;
    this.blockTimer = 0;
    this.strafe = Math.random() > 0.5 ? 1 : -1;
    this.strafeTimer = 0;
    this.rampage = false;
    this.attackCooldown = 0;
    this.specialWish = 0;
  }

  update(dt) {
    const m = this.m;
    if (m.dead || m.state.grabbed) return;
    this.think -= dt;
    this.attackCooldown -= dt;
    this.blockTimer -= dt;
    this.strafeTimer -= dt;
    if (this.strafeTimer <= 0) { this.strafeTimer = 1.5 + Math.random() * 2.5; this.strafe *= -1; }
    if (this.think > 0) return;
    this.think = 0.18 + Math.random() * 0.18;

    const enemies = m.game.monsters.filter(o => o !== m && !o.dead && o.team !== m.team);
    let target = null, best = 1e9;
    for (const e of enemies) {
      const d = m.root.position.distanceTo(e.root.position);
      if (d < best) { best = d; target = e; }
    }
    if (!target && m.game.mode === 'battle' && m.game.player && m.game.player.team !== m.team && !m.game.player.dead) {
      target = m.game.player; best = m.root.position.distanceTo(target.root.position);
    }
    this.target = target;
    m.target = target;
    const intent = m.intent;
    intent.moveX = 0; intent.moveZ = 0; intent.run = false; intent.block = false;
    intent.attack = null; intent.special = false; intent.dodge = false; intent.jump = false; intent.grab = false; intent.roar = false;

    if (m.state.ragdoll) return;

    if (!target) {
      // rampage: hunt the nearest standing building
      const buildings = m.game.city.buildings.filter(b => !b.destroyed);
      if (!buildings.length) return;
      let b = null, bd = 1e9;
      for (const cand of buildings) {
        const d = Math.hypot(cand.x - m.root.position.x, cand.z - m.root.position.z);
        if (d < bd) { bd = d; b = cand; }
      }
      if (!b) return;
      const dx = b.x - m.root.position.x, dz = b.z - m.root.position.z;
      const dist = Math.hypot(dx, dz);
      if (dist > Math.max(b.width, b.depth) * 0.7 + m.radius + 8) {
        intent.moveX = dx / (dist || 1); intent.moveZ = dz / (dist || 1); intent.run = dist > 90;
      } else {
        intent.aimYaw = Math.atan2(-dx, -dz);
        if (this.attackCooldown <= 0) {
          intent.attack = Math.random() > 0.55 ? 'heavy' : 'light';
          this.attackCooldown = 0.9 + Math.random() * 0.8;
        }
      }
      return;
    }

    const dx = target.root.position.x - m.root.position.x;
    const dz = target.root.position.z - m.root.position.z;
    const dist = Math.hypot(dx, dz);
    const range = m.attackDefs.light.range + m.radius * 0.5;
    const heavyRange = m.attackDefs.heavy.range + m.radius * 0.4;
    intent.aimYaw = Math.atan2(-dx, -dz);
    intent.faceTarget = target;

    // react to incoming attacks
    if (target.state.attack && dist < range * 1.7) {
      const kind = target.state.attack.kind;
      if (kind === 'heavy' && Math.random() < 0.3) intent.dodge = true;
      else if (Math.random() < 0.26) { intent.block = true; this.blockTimer = 0.5; }
    }
    if (this.blockTimer > 0) intent.block = true;

    if (m.hp < m.maxHp * 0.28 && Math.random() < 0.15) intent.roar = true;

    const special = m.def.special;
    const specialRange = special.type === 'beam' || special.type === 'tripleBeam' || special.type === 'freezeBeam' || special.type === 'godrays' ? special.range * 0.7 : special.range;
    if (m.cooldowns.special <= 0 && m.stamina > 28 && dist < specialRange && Math.random() < 0.5) {
      intent.special = true;
    }

    if (dist > range * 1.05) {
      let mx = dx / (dist || 1), mz = dz / (dist || 1);
      // slight strafe / flank
      if (dist < range * 2.6 && Math.random() < 0.35) {
        mx += -dz / (dist || 1) * 0.35 * this.strafe;
        mz += dx / (dist || 1) * 0.35 * this.strafe;
      }
      const len = Math.hypot(mx, mz) || 1;
      intent.moveX = mx / len; intent.moveZ = mz / len;
      intent.run = dist > range * 2.4;
      // if stuck against a building, swing at it
      if (m.blockedTimer > 0.45 && this.attackCooldown <= 0) {
        intent.attack = 'heavy';
        this.attackCooldown = 1.1;
      }
      if (dist < heavyRange && this.attackCooldown <= 0 && Math.random() < 0.35) {
        intent.attack = 'heavy';
        this.attackCooldown = 1.2 + Math.random() * 0.6;
      }
    } else {
      if (this.attackCooldown <= 0 && !m.state.attack && !m.state.ragdoll) {
        const r = Math.random();
        if (r < 0.55) intent.attack = 'light';
        else if (r < 0.78) intent.attack = 'heavy';
        else if (r < 0.88) intent.attack = 'bite';
        else if (r < 0.95) intent.attack = 'tail';
        else intent.grab = true;
        this.attackCooldown = 0.7 + Math.random() * 0.9;
      }
      // keep a little distance while attacking
      if (dist < range * 0.45 && Math.random() < 0.4) {
        intent.moveX = -dx / (dist || 1) * 0.4;
        intent.moveZ = -dz / (dist || 1) * 0.4;
      }
    }
    if (target.state.ragdoll && dist < heavyRange && this.attackCooldown <= 0) {
      intent.attack = 'heavy';
      this.attackCooldown = 1.4;
    }
    if (target.state.attack?.kind === 'special' && Math.random() < 0.2) intent.dodge = true;
    if (m.hp < m.maxHp * 0.35 && Math.random() < 0.25) intent.dodge = true;
  }
}

export class Monster {
  constructor(game, def, opts = {}) {
    this.game = game;
    this.def = def;
    this.team = opts.team ?? 0;
    this.isPlayer = !!opts.player;
    this.name = def.name;
    this.height = def.height;
    this.radius = def.height * 0.135;
    this.maxHp = def.health;
    this.hp = this.maxHp;
    this.maxStamina = def.stamina;
    this.stamina = this.maxStamina;
    this.mass = def.mass;
    this.attackDefs = attackStats(def);
    this.cooldowns = { special: 0, grab: 0, dodge: 0, roar: 0, jump: 0 };
    this.state = {
      speed: 0, running: false, walkPhase: Math.random() * TAU, grounded: true,
      attack: null, block: false, hitPulse: 0, hitDir: 1, ragdoll: false, dead: false,
      grabbed: false, dodge: 0, jumpY: 0, jumpVel: 0, burn: 0, freeze: 0, shock: 0,
      specialTick: 0, recovery: 0, flying: false,
    };
    this.intent = { moveX: 0, moveZ: 0, run: false, block: false, attack: null, special: false, dodge: false, jump: false, grab: false, roar: false, aimYaw: null, faceTarget: null };
    this.velocity = new THREE.Vector3();
    this.yaw = opts.yaw ?? 0;
    this.target = null;
    this.balance = 100;
    this.maxBalance = 100;
    this.ragdollTime = 0;
    this.ragdollTotal = 0;
    this.fallPitch = 0;
    this.fallRoll = 0;
    this.grabTarget = null;
    this.grabbedBy = null;
    this.activeBeams = [];
    this.beamStop = null;
    this.invuln = 0;
    this.blockedTimer = 0;
    this.stepTimer = 0;
    this.deathTimer = 0;
    this.statusTimer = 0;
    this.combo = 0;
    this.queued = null;
    this.spawnPoint = new THREE.Vector3(opts.x ?? 0, 0, opts.z ?? 0);
    this.root = new THREE.Group();
    const { group, rig } = createMonsterModel(def);
    this.rig = rig;
    this.model = group;
    this.root.add(group);
    this.root.position.copy(this.spawnPoint);
    this.root.rotation.y = this.yaw;
    game.scene.add(this.root);
    setRigTeamColor(rig, TEAM_COLORS[this.team] ?? 0xffffff);
    rig.teamRingMat.opacity = this.isPlayer ? 0.45 : 0.28;
    this.visual = rig.visual;
    this.baseY = 0;
    this.createHealthBar();
    this.ai = opts.ai === false ? null : new MonsterAI(this);
    this.state.hitFlash = 0;
    this.audioStepTimer = 0;
    this.lastDamageTime = 0;
    this.game.hud?.onMonsterSpawn?.(this);
  }

  createHealthBar() {
    const w = this.height * 0.6;
    const h = this.height * 0.028;
    const g = new THREE.Group();
    const bg = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: 0x090b0d, transparent: true, opacity: 0.82, depthTest: false, depthWrite: false }));
    bg.renderOrder = 20;
    g.add(bg);
    const fill = new THREE.Mesh(new THREE.PlaneGeometry(w, h * 0.72), new THREE.MeshBasicMaterial({ color: TEAM_COLORS[this.team] ?? 0x4fc3ff, depthTest: false, depthWrite: false, toneMapped: false }));
    fill.position.z = 0.01;
    fill.renderOrder = 21;
    g.add(fill);
    g.position.y = this.height * 1.12;
    this.game.scene.add(g);
    this.healthBar = g;
    this.healthFill = fill;
    this.healthWidth = w;
  }

  setPlayer(on) {
    this.isPlayer = on;
    this.rig.teamRingMat.opacity = on ? 0.45 : 0.28;
    if (on) { this.ai = null; this.intent.attack = null; }
    else if (!this.ai) this.ai = new MonsterAI(this);
    this.healthBar.visible = !on;
  }

  get forward() { return new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw)); }
  get forwardFlat() { return new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw)); }
  get right() { return new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw)); }

  headWorld(out = new THREE.Vector3()) {
    if (this.rig.head) this.rig.head.getWorldPosition(out);
    else out.copy(this.root.position).add(new THREE.Vector3(0, this.height * 0.8, 0));
    return out;
  }

  canAct() { return !this.dead && !this.state.ragdoll && !this.state.grabbed; }

  update(dt) {
    this.invuln = Math.max(0, this.invuln - dt);
    this.blockedTimer = Math.max(0, this.blockedTimer - dt);
    this.state.hitPulse = Math.max(0, this.state.hitPulse - dt * 4);
    this.state.hitFlash = Math.max(0, this.state.hitFlash - dt * 5);
    for (const k of Object.keys(this.cooldowns)) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
    this.stamina = Math.min(this.maxStamina, this.stamina + dt * (this.state.block ? 2 : 14));
    if (this.state.block) this.stamina = Math.max(0, this.stamina - dt * 9);
    this.balance = Math.min(this.maxBalance, this.balance + dt * (this.state.ragdoll ? 0 : 9));
    this.statusUpdate(dt);

    if (this.state.grabbed) {
      this.followGrab(dt);
      this.updateVisual(dt);
      return;
    }
    if (this.state.dead) {
      this.updateRagdoll(dt, true);
      this.updateVisual(dt);
      return;
    }
    if (this.state.ragdoll) {
      this.updateRagdoll(dt, false);
      this.updateVisual(dt);
      return;
    }
    if (this.ai) this.ai.update(dt);

    // player / AI intent
    const intent = this.intent;
    this.state.block = !!intent.block && this.stamina > 0;
    if (this.state.block) {
      this.state.attack = null;
    }
    if (this.state.dodge > 0) {
      this.state.dodge -= dt;
      this.root.position.addScaledVector(this.velocity, dt);
      this.resolveCollisions(dt, true);
      this.updateVisual(dt);
      return;
    }
    if (intent.dodge && this.cooldowns.dodge <= 0 && this.stamina > 12 && this.canAct()) {
      this.startDodge(intent);
    }
    if (intent.jump && this.cooldowns.jump <= 0 && this.canAct()) {
      this.startJump();
    }
    if (intent.attack && this.canAct() && !this.state.attack) {
      this.startAttack(intent.attack, intent.aimYaw);
      this.intent.attack = null;
    }
    if (intent.special && this.canAct() && !this.state.attack && this.cooldowns.special <= 0 && this.stamina > 24) {
      this.startSpecial(intent.aimYaw);
      this.intent.special = false;
    }
    if (intent.grab && this.canAct() && !this.state.attack && this.cooldowns.grab <= 0 && this.stamina > 12) {
      this.startAttack('grab', intent.aimYaw);
      this.intent.grab = false;
    }
    if (intent.roar && this.canAct() && !this.state.attack && this.cooldowns.roar <= 0) {
      this.startAttack('roar', intent.aimYaw);
      this.intent.roar = false;
    }

    if (this.state.attack) {
      this.updateAttack(dt);
    } else {
      this.updateMovement(dt, intent);
    }

    // jump physics
    if (this.state.jumpVel !== 0 || this.state.jumpY > 0) {
      this.state.jumpVel -= 42 * dt;
      this.state.jumpY += this.state.jumpVel * dt;
      if (this.state.jumpY <= 0) {
        this.state.jumpY = 0;
        if (this.state.jumpVel < -4) this.land();
        this.state.jumpVel = 0;
      }
    }
    this.root.position.y = this.state.jumpY;
    this.updateVisual(dt);
  }

  updateMovement(dt, intent) {
    let mx = intent.moveX || 0, mz = intent.moveZ || 0;
    const len = Math.hypot(mx, mz);
    let targetSpeed = 0;
    if (len > 0.05 && !this.state.block) {
      mx /= len; mz /= len;
      targetSpeed = (intent.run ? this.def.runSpeed : this.def.speed) * (this.state.freeze > 0 ? 0.55 : 1);
      if (this.state.block) targetSpeed *= 0.25;
      const desiredYaw = Math.atan2(-mx, -mz);
      this.yaw = damp(this.yaw, desiredYaw, 8, dt);
    } else if (intent.faceTarget && !this.state.attack) {
      const dx = intent.faceTarget.root.position.x - this.root.position.x;
      const dz = intent.faceTarget.root.position.z - this.root.position.z;
      this.yaw = damp(this.yaw, Math.atan2(-dx, -dz), 5, dt);
    }
    if (this.state.block) targetSpeed = 0;
    const accel = targetSpeed > 0 ? 22 : 30;
    const vx = Math.sin(this.yaw) * -targetSpeed;
    const vz = Math.cos(this.yaw) * -targetSpeed;
    this.velocity.x = damp(this.velocity.x, vx, accel / 8, dt);
    this.velocity.z = damp(this.velocity.z, vz, accel / 8, dt);
    if (len < 0.05 && !this.state.attack) {
      this.velocity.x = damp(this.velocity.x, 0, 4, dt);
      this.velocity.z = damp(this.velocity.z, 0, 4, dt);
    }
    this.root.position.x += this.velocity.x * dt;
    this.root.position.z += this.velocity.z * dt;
    this.state.speed = Math.hypot(this.velocity.x, this.velocity.z);
    this.state.running = intent.run && this.state.speed > this.def.speed * 0.7;
    if (this.state.speed > 0.3) this.state.walkPhase += dt * (this.state.running ? 2.1 : 1.15) * (0.7 + this.state.speed / 60);
    this.resolveCollisions(dt, false);
    this.root.rotation.y = this.yaw;
    // footstep FX
    this.stepTimer -= dt * (0.4 + this.state.speed / 30);
    if (this.stepTimer <= 0 && this.state.speed > 1) {
      this.stepTimer = this.state.running ? 0.28 : 0.5;
      this.footstep();
    }
    // clamp world
    this.root.position.x = clamp(this.root.position.x, -420, 420);
    this.root.position.z = clamp(this.root.position.z, -420, 420);
  }

  footstep() {
    const f = this.forward;
    const p = this.root.position.clone().add(new THREE.Vector3(f.z * this.radius * 0.5, 0.5, -f.x * this.radius * 0.5));
    this.game.effects.dust(p, this.radius * 0.4, 4, 0xa89a86);
    if (this.isPlayer || this.game.camera.position.distanceTo(p) < 220) {
      this.audioStepTimer -= 1;
      if (this.audioStepTimer <= 0) {
        this.game.audio.stomp(0.55);
        this.audioStepTimer = 2;
        this.game.effects.shakeCamera(0.08, 0.2);
      }
    }
  }

  resolveCollisions(dt, dodging) {
    const hit = this.game.city.collideCircle(this.root.position.x, this.root.position.z, this.radius);
    if (hit.pushX || hit.pushZ) {
      this.root.position.x += hit.pushX;
      this.root.position.z += hit.pushZ;
      this.blockedTimer = 0.5;
      const speed = Math.hypot(this.velocity.x, this.velocity.z);
      if (speed > 8 && hit.hit) {
        const dmg = (speed * this.mass) / 250000 * (dodging ? 0.4 : 1);
        hit.hit.damage(dmg, this.root.position.clone().setY(this.height * 0.5), { source: this });
        this.velocity.multiplyScalar(0.55);
        this.game.effects.dust(this.root.position.clone().setY(this.height * 0.3), this.radius, 8, 0x9a8f80);
        this.game.audio.impact(0.6);
      }
    }
  }

  startAttack(kind, aimYaw = null) {
    if (!this.canAct()) return;
    if (kind === 'grab' && this.grabTarget) {
      this.throwGrabbed();
      return;
    }
    const stats = this.attackDefs[kind] || this.attackDefs.light;
    if (this.stamina < stats.stamina) {
      if (this.isPlayer) this.game.hud?.toast('NOT ENOUGH STAMINA', 'warn');
      return;
    }
    if (kind === 'grab' && this.cooldowns.grab > 0) return;
    if (aimYaw !== null && aimYaw !== undefined) this.yaw = aimYaw;
    this.stamina -= stats.stamina;
    this.state.attack = {
      kind, t: 0, dur: stats.dur, hit: stats.hit, hitDone: false,
      alt: this.combo % 2 === 1, stats, aimYaw,
    };
    this.combo++;
    if (kind === 'roar') {
      this.cooldowns.roar = stats.cd;
      this.game.audio.roar(this.def);
      this.game.roarWave?.(this);
    }
    if (kind === 'grab') this.cooldowns.grab = stats.cd;
    if (this.isPlayer) this.game.hud?.onAction(kind);
  }

  startSpecial(aimYaw = null) {
    if (!this.canAct() || this.cooldowns.special > 0) return;
    const sp = this.def.special;
    if (aimYaw !== null && aimYaw !== undefined) this.yaw = aimYaw;
    this.stamina -= 24;
    this.cooldowns.special = sp.cooldown;
    this.state.attack = {
      kind: 'special', t: 0, dur: sp.type === 'beam' || sp.type === 'tripleBeam' || sp.type === 'freezeBeam' || sp.type === 'godrays' ? 1.8 : 1.15,
      hit: 0.42, hitDone: false, special: sp, stats: { damage: sp.damage, range: sp.range, force: 20 }, aimYaw,
    };
    this.game.audio.roar(this.def);
    this.game.hud?.onAction('special');
    if (this.isPlayer) this.game.hud?.setSpecialName(sp.name);
  }

  startDodge(intent) {
    this.stamina -= 12;
    this.cooldowns.dodge = 1.4;
    this.invuln = 0.45;
    this.state.dodge = 0.38;
    this.state.attack = null;
    const f = this.forward;
    let dx = intent.moveX || 0, dz = intent.moveZ || 0;
    if (Math.hypot(dx, dz) < 0.1) { dx = -f.x; dz = -f.z; }
    const l = Math.hypot(dx, dz) || 1;
    this.velocity.set(dx / l * this.def.runSpeed * 1.8, 0, dz / l * this.def.runSpeed * 1.8);
    this.game.effects.dust(this.root.position.clone(), this.radius * 0.7, 12, 0xa89a86);
    this.game.audio.whoosh();
  }

  startJump() {
    this.stamina -= 8;
    this.cooldowns.jump = 1.8;
    this.state.jumpVel = this.def.family === 'rodan' || this.def.family === 'mothra' ? 34 : 20;
    this.state.jumpY = 0.1;
    this.game.effects.dust(this.root.position.clone(), this.radius, 10, 0xa89a86);
  }

  land() {
    const r = this.radius * 2.4;
    this.game.effects.dust(this.root.position.clone(), r, 26, 0xa89a86);
    this.game.effects.shakeCamera(0.5, 0.5);
    this.game.audio.stomp(1.2);
    this.game.aoe(this, this.root.position, r, 8 + this.def.attack * 0.08, 12, 'impact', { shake: true });
  }

  updateAttack(dt) {
    const a = this.state.attack;
    a.t += dt;
    const p = a.t / a.dur;
    // slight forward lean / movement during attacks
    if (a.kind !== 'special' && a.kind !== 'roar') {
      const lunge = Math.sin(clamp(p, 0, 1) * Math.PI) * (a.kind === 'heavy' ? 5 : 3);
      const f = this.forward;
      this.root.position.x += f.x * lunge * dt;
      this.root.position.z += f.z * lunge * dt;
      this.resolveCollisions(dt, false);
    }
    if (!a.hitDone && a.t >= a.hit) {
      a.hitDone = true;
      this.executeHit(a);
    }
    if (a.kind === 'special' && a.special) this.updateSpecial(dt, a);
    if (a.t >= a.dur) {
      this.state.attack = null;
      this.state.speed = 0;
      if (this.activeBeams.length) this.endBeams();
    }
    this.state.speed = 0;
    this.root.rotation.y = this.yaw;
    this.state.walkPhase += dt * 0.4;
  }

  executeHit(a) {
    const stats = a.stats;
    if (a.kind === 'roar') {
      this.game.roarWave?.(this);
      this.game.effects.shockwave(this.root.position, this.height * 0.6, this.def.colors.glow);
      return;
    }
    if (a.kind === 'grab') {
      const target = this.game.findGrabTarget(this);
      if (target) {
        this.grabTarget = target;
        target.grabbedBy = this;
        target.state.grabbed = true;
        target.state.attack = null;
        target.state.ragdoll = false;
        target.velocity.set(0, 0, 0);
        this.game.audio.impact(1.1);
        this.game.hud?.toast(`${target.name} GRABBED`, 'info');
      }
      return;
    }
    if (a.kind === 'special') {
      this.fireSpecial(a);
      return;
    }
    // melee / stomp
    const dmg = stats.damage * (1 + (this.state.burn > 0 ? 0.08 : 0));
    const result = this.game.melee(this, a.kind, stats);
    if (a.kind === 'stomp') {
      this.game.effects.shockwave(this.root.position, this.height * 0.7, this.def.colors.glow);
      this.game.effects.dust(this.root.position.clone(), this.height * 0.4, 32, 0xa89a86);
      this.game.effects.shakeCamera(0.55, 0.5);
      this.game.audio.stomp(1.1);
    }
    if (result.hit) {
      this.game.effects.shakeCamera(this.isPlayer ? 0.24 : 0.12, 0.28);
    }
  }

  fireSpecial(a) {
    const sp = a.special;
    const head = this.headWorld(new THREE.Vector3());
    const dir = this.forward;
    if (sp.type === 'beam' || sp.type === 'freezeBeam') {
      const beam = this.game.spawnBeam(this, head, dir, sp, 1.25, this.isPlayer ? 2.6 : 2.2);
      this.activeBeams.push(beam);
      this.beamStop = this.game.audio.beamStart(this.def, 1.4);
      this.game.effects.explosion(head, 0.35, sp.color);
      this.game.hud?.cinematic(this, 1.0);
    } else if (sp.type === 'tripleBeam') {
      const origins = [];
      if (this.rig.necks) for (const n of this.rig.necks) {
        const p = new THREE.Vector3(); n.head.getWorldPosition(p); origins.push(p);
      } else origins.push(head);
      for (const o of origins) {
        this.activeBeams.push(this.game.spawnBeam(this, o, dir, sp, 1.15, 1.6, 0.4));
      }
      this.beamStop = this.game.audio.beamStart(this.def, 1.4);
      this.game.hud?.cinematic(this, 1.0);
    } else if (sp.type === 'godrays') {
      const origins = [head.clone().add(new THREE.Vector3(-this.height * 0.18, 0, 0)), head, head.clone().add(new THREE.Vector3(this.height * 0.18, 0, 0))];
      for (const o of origins) this.activeBeams.push(this.game.spawnBeam(this, o, dir, sp, 1.0, 1.1, 0.35));
      this.beamStop = this.game.audio.beamStart(this.def, 1.2);
      this.game.hud?.cinematic(this, 1.0);
    } else if (sp.type === 'pulse' || sp.type === 'shockwave' || sp.type === 'cleave' || sp.type === 'firestorm' || sp.type === 'acid') {
      const center = this.root.position.clone().addScaledVector(dir, this.height * 0.28);
      const radius = sp.range;
      this.game.aoe(this, center, radius, sp.damage, 26, sp.type, { building: true, color: sp.color });
      this.game.effects.shockwave(this.root.position, radius, sp.color);
      if (sp.type === 'firestorm') this.game.effects.fire(center, 60, sp.color, 5);
      if (sp.type === 'acid') this.game.effects.acid(center, 50, sp.color);
      if (sp.type === 'cleave') this.game.effects.sparks(center, 40, sp.color, 30);
      this.game.effects.explosion(center, sp.type === 'pulse' ? 1.3 : 0.8, sp.color);
      this.game.audio.explosion(1.2);
      this.game.effects.shakeCamera(0.9, 0.8);
    }
  }

  updateSpecial(dt, a) {
    const sp = a.special;
    if (!this.activeBeams.length) return;
    a.tick = (a.tick || 0) - dt;
    // update beam ends each frame
    const head = this.headWorld(new THREE.Vector3());
    const dir = this.forward;
    for (const beam of this.activeBeams) {
      if (beam.dead) continue;
      const res = this.game.beamTarget(this, beam.start || head, dir, sp.range);
      beam.target = res;
      beam.effect.end.copy(res.point);
      beam.effect.start.copy(beam.start || head);
      beam.effect.updateStart = (v) => { v.copy(beam.start || head); };
      if (a.tick <= 0) {
        a.tick = 0.12;
        this.game.beamDamage(this, res, sp, beam);
      }
    }
  }

  endBeams() {
    for (const b of this.activeBeams) {
      if (b.effect) b.effect.life = Math.min(b.effect.life, 0.08);
      b.dead = true;
    }
    this.activeBeams = [];
    try { this.beamStop?.(); } catch {}
    this.beamStop = null;
  }

  followGrab(dt) {
    const attacker = this.grabbedBy;
    if (!attacker || attacker.dead) { this.releaseGrab(); return; }
    const f = attacker.forward;
    const targetPos = attacker.root.position.clone().addScaledVector(f, attacker.radius + this.radius * 0.8);
    targetPos.y = Math.max(0, attacker.state.jumpY + this.height * 0.08);
    this.root.position.lerp(targetPos, 1 - Math.exp(-dt * 12));
    this.yaw = attacker.yaw + Math.PI;
    this.root.rotation.y = this.yaw;
    this.state.speed = 0;
    this.velocity.set(0, 0, 0);
    this.balance = 0;
    if (attacker.state.attack?.kind !== 'grab') this.releaseGrab();
  }

  releaseGrab() {
    this.grabbedBy = null;
    this.state.grabbed = false;
    this.balance = 30;
    this.invuln = 0.3;
  }

  throwGrabbed() {
    const t = this.grabTarget;
    if (!t) return;
    const f = this.forward;
    t.releaseGrab();
    t.velocity.copy(f).multiplyScalar(42).add(new THREE.Vector3(0, 12, 0));
    t.knockdown(f, 24);
    this.grabTarget = null;
    this.game.effects.shockwave(this.root.position, this.height * 0.5, this.def.colors.glow);
    this.game.audio.impact(1.6);
    this.game.effects.shakeCamera(0.7, 0.6);
  }

  takeDamage(amount, attacker, hitPoint, force = 10, type = 'impact') {
    if (this.dead || this.invuln > 0) return 0;
    if (this.state.grabbed) amount *= 0.7;
    let dmg = amount;
    let blocked = false;
    if (this.state.block && attacker) {
      const toAtt = attacker.root.position.clone().sub(this.root.position).setY(0).normalize();
      if (toAtt.dot(this.forward) > -0.1) {
        dmg *= 0.28;
        blocked = true;
        this.stamina = Math.max(0, this.stamina - amount * 0.7);
        this.game.effects.sparks(hitPoint || this.root.position.clone().setY(this.height * 0.55), 10, 0x9fd8ff, 12);
        this.game.audio.impact(0.5);
        if (this.stamina <= 0) { this.state.block = false; this.stagger(attacker); }
      }
    }
    this.hp -= dmg;
    this.state.hitPulse = 1;
    this.state.hitFlash = 1;
    this.state.hitDir = Math.random() > 0.5 ? 1 : -1;
    this.balance -= force * (blocked ? 0.25 : 1.2);
    const p = hitPoint || this.root.position.clone().setY(this.height * 0.55);
    this.game.effects.sparks(p, Math.round(6 + dmg * 0.3), type === 'freeze' ? 0x9feaff : type === 'acid' ? 0xc6ff4d : 0xffc46b, 12 + force);
    if (dmg > 12) this.game.effects.blood(p, Math.round(4 + dmg * 0.12));
    this.game.audio.impact(clamp(dmg / 18, 0.4, 1.6));
    if (this.isPlayer) this.game.effects.shakeCamera(clamp(dmg / 30, 0.12, 0.5), 0.35);
    if (attacker) {
      const dir = this.root.position.clone().sub(attacker.root.position).setY(0).normalize();
      if (!blocked) this.velocity.addScaledVector(dir, force * (1.4 - this.mass / 250000));
      if (type === 'burn') this.state.burn = Math.max(this.state.burn, 4);
      if (type === 'freeze') this.state.freeze = Math.max(this.state.freeze, 4);
      if (type === 'acid') this.state.shock = Math.max(this.state.shock, 4);
    }
    if (!blocked && this.balance <= 0 && !this.state.ragdoll) {
      const dir = attacker ? this.root.position.clone().sub(attacker.root.position).setY(0).normalize() : this.forward.clone().negate();
      this.knockdown(dir, force + 8);
    }
    this.lastDamageTime = 0;
    if (this.hp <= 0) this.die(attacker);
    this.game.hud?.onDamage?.(this, dmg, blocked);
    return dmg;
  }

  stagger(attacker) {
    if (attacker) {
      const dir = this.root.position.clone().sub(attacker.root.position).setY(0).normalize();
      this.velocity.addScaledVector(dir, 8);
    }
    this.state.hitPulse = 1;
  }

  knockdown(dir, force) {
    if (this.dead) return;
    this.state.ragdoll = true;
    this.state.attack = null;
    this.state.block = false;
    this.state.dodge = 0;
    this.ragdollTime = 2.3 + Math.random() * 0.8;
    this.ragdollTotal = this.ragdollTime;
    this.balance = 0;
    const d = dir.clone().setY(0).normalize();
    this.velocity.addScaledVector(d, Math.min(30, force * 1.1));
    const f = this.forward;
    const side = d.dot(this.right);
    const front = d.dot(f);
    this.fallPitch = clamp(-front * 1.35, -1.35, 1.35);
    this.fallRoll = clamp(side * 1.3, -1.3, 1.3);
    if (Math.abs(this.fallPitch) < 0.2 && Math.abs(this.fallRoll) < 0.2) this.fallPitch = 1.2;
    this.game.effects.dust(this.root.position.clone(), this.height * 0.3, 20, 0xa89a86);
    this.game.effects.shakeCamera(0.45, 0.5);
    this.game.audio.impact(1.4);
    this.game.hud?.toast(`${this.name} DOWN`, 'warn');
  }

  updateRagdoll(dt, dead) {
    this.state.ragdoll = true;
    const t = dead ? 0 : this.ragdollTime;
    // slide
    this.velocity.x = damp(this.velocity.x, 0, 2.2, dt);
    this.velocity.z = damp(this.velocity.z, 0, 2.2, dt);
    this.root.position.x += this.velocity.x * dt;
    this.root.position.z += this.velocity.z * dt;
    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    const hit = this.game.city.collideCircle(this.root.position.x, this.root.position.z, this.radius * 0.85);
    if (hit.pushX || hit.pushZ) {
      this.root.position.x += hit.pushX;
      this.root.position.z += hit.pushZ;
      if (hit.hit && speed > 5) {
        hit.hit.damage(speed * 3, this.root.position.clone().setY(this.height * 0.25), { source: this });
        this.game.effects.dust(this.root.position.clone(), this.radius, 12, 0x9a8f80);
        this.game.audio.impact(1);
      }
      this.velocity.multiplyScalar(0.4);
    }
    this.root.position.x = clamp(this.root.position.x, -420, 420);
    this.root.position.z = clamp(this.root.position.z, -420, 420);
    if (speed > 4 && Math.random() < 0.15) {
      this.game.effects.dust(this.root.position.clone(), this.radius * 0.8, 3, 0xa89a86);
    }
    if (!dead) {
      this.ragdollTime -= dt;
      if (this.ragdollTime > 0.55) {
        const p = clamp(1 - this.ragdollTime / 0.4, 0, 1);
        const e = 1 - Math.pow(1 - p, 3);
        this.visual.rotation.x = this.fallPitch * e;
        this.visual.rotation.z = this.fallRoll * e;
      } else {
        const k = clamp(this.ragdollTime / 0.55, 0, 1);
        this.visual.rotation.x = this.fallPitch * k;
        this.visual.rotation.z = this.fallRoll * k;
        if (this.ragdollTime <= 0) {
          this.state.ragdoll = false;
          this.state.recovery = 0.4;
          this.balance = 55;
          this.invuln = 0.55;
          this.visual.rotation.set(0, 0, 0);
          this.velocity.set(0, 0, 0);
          this.game.hud?.toast(`${this.name} RECOVERS`, 'info');
        }
      }
    } else {
      this.deathTimer += dt;
      const e = 1 - Math.pow(1 - clamp(this.deathTimer / 0.8, 0, 1), 3);
      this.visual.rotation.x = this.fallPitch * e;
      this.visual.rotation.z = this.fallRoll * e;
      this.healthBar.visible = false;
    }
    this.root.rotation.y = this.yaw;
  }

  die(attacker) {
    if (this.dead) return;
    this.dead = true;
    this.state.ragdoll = true;
    this.state.attack = null;
    this.hp = 0;
    this.deathTimer = 0;
    this.healthBar.visible = false;
    this.rig.teamRingMat.opacity = 0.05;
    const dir = attacker ? this.root.position.clone().sub(attacker.root.position).setY(0).normalize() : this.forward.clone().negate();
    this.knockdown(dir, 18);
    this.state.ragdoll = true;
    this.game.effects.explosion(this.root.position.clone().setY(this.height * 0.4), 1.1, this.def.colors.glow);
    this.game.audio.explosion(1.2);
    this.game.onMonsterDeath?.(this, attacker);
    this.game.hud?.toast(`${this.name} DEFEATED`, 'kill');
  }

  statusUpdate(dt) {
    if (this.state.burn > 0) {
      this.state.burn -= dt;
      this.hp -= dt * 5;
      if (Math.random() < dt * 8) this.game.effects.fire(this.root.position.clone().setY(this.height * (0.3 + Math.random() * 0.5)), 2, 0xff6a2e, 1.6);
      if (this.hp <= 0) this.die(null);
    }
    if (this.state.freeze > 0) {
      this.state.freeze -= dt;
      if (Math.random() < dt * 4) this.game.effects.ice(this.root.position.clone().setY(this.height * 0.4), 2);
    }
    if (this.state.shock > 0) {
      this.state.shock -= dt;
      this.hp -= dt * 3;
      if (Math.random() < dt * 5) this.game.effects.sparks(this.root.position.clone().setY(this.height * 0.5), 2, 0xc6ff4d, 10);
      if (this.hp <= 0) this.die(null);
    }
  }

  updateVisual(dt) {
    // materials hit/status tint
    const skin = this.rig.mats?.skin;
    if (skin) {
      const flash = this.state.hitFlash;
      if (this.state.freeze > 0) { skin.emissive.setHex(0x2a6c8f); skin.emissiveIntensity = 0.5; }
      else if (this.state.burn > 0) { skin.emissive.setHex(0x6a1e08); skin.emissiveIntensity = 0.6; }
      else if (flash > 0) { skin.emissive.setHex(0x6a1515); skin.emissiveIntensity = flash * 0.8; }
      else { skin.emissiveIntensity = 0; }
    }
    animateMonster(this.rig, this.state, this.game.time, dt);
    // ragdoll / death visual transform (after animation so it wins)
    if (this.state.ragdoll || this.state.dead) {
      if (this.state.dead) {
        const e = 1 - Math.pow(1 - clamp(this.deathTimer / 0.8, 0, 1), 3);
        this.visual.rotation.x = this.fallPitch * e;
        this.visual.rotation.z = this.fallRoll * e;
      } else {
        const t = this.ragdollTime;
        if (t > 0.55) {
          const p = clamp(1 - t / 0.4, 0, 1);
          const e = 1 - Math.pow(1 - p, 3);
          this.visual.rotation.x = this.fallPitch * e;
          this.visual.rotation.z = this.fallRoll * e;
        } else {
          const k = clamp(t / 0.55, 0, 1);
          this.visual.rotation.x = this.fallPitch * k;
          this.visual.rotation.z = this.fallRoll * k;
        }
      }
      this.visual.position.y = 0;
    } else {
      this.visual.rotation.x = 0;
      this.visual.rotation.z = 0;
    }
    // health bar
    const cam = this.game.camera;
    if (this.healthBar) {
      this.healthBar.position.copy(this.root.position);
      this.healthBar.position.y += this.height * (this.state.ragdoll ? 0.55 : 1.12);
      this.healthBar.quaternion.copy(cam.quaternion);
      const dist = cam.position.distanceTo(this.root.position);
      this.healthBar.visible = !this.isPlayer && !this.dead && dist < 700;
      if (this.healthBar.visible) {
        const ratio = clamp(this.hp / this.maxHp, 0, 1);
        this.healthFill.scale.x = Math.max(0.001, ratio);
        this.healthFill.position.x = -(this.healthWidth / 2) * (1 - ratio);
        this.healthFill.material.color.setHex(ratio > 0.5 ? (TEAM_COLORS[this.team] ?? 0x4fc3ff) : ratio > 0.22 ? 0xffb347 : 0xff3b4d);
      }
    }
    // team ring pulse for player
    if (this.rig.teamRing) {
      this.rig.teamRingMat.opacity = this.isPlayer ? 0.3 + Math.sin(this.game.time * 3) * 0.08 : 0.22;
    }
  }

  dispose() {
    this.endBeams();
    this.game.scene.remove(this.root);
    this.game.scene.remove(this.healthBar);
    this.root.traverse(o => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
        else o.material.dispose?.();
      }
    });
    this.healthBar.traverse(o => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) o.material.dispose?.();
    });
  }
}

import * as THREE from 'three';

const KEY_ACTIONS = {
  KeyJ: 'light', KeyK: 'heavy', KeyF: 'tail', KeyB: 'bite', KeyH: 'stomp',
  KeyE: 'special', KeyG: 'grab', KeyR: 'roar', KeyQ: 'dodge', Space: 'jump',
};

export class Input {
  constructor(renderer, settings) {
    this.renderer = renderer;
    this.settings = settings;
    this.keys = new Set();
    this.actions = [];
    this.dragging = false;
    this.dragMoved = 0;
    this.dragButton = 0;
    this.lastX = 0;
    this.lastY = 0;
    this.yaw = 0;
    this.pitch = 0.18;
    this.distance = 240;
    this.zoomTarget = 240;
    this.joystick = { x: 0, y: 0, active: false, pointerId: null };
    this.touchCamera = { active: false, id: null, x: 0, y: 0 };
    this.enabled = false;
    this.onAction = null;
    this.el = renderer.domElement;
    this.bind();
  }

  bind() {
    window.addEventListener('keydown', e => {
      if (!this.enabled) return;
      if (e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
      const action = KEY_ACTIONS[e.code];
      if (action) {
        e.preventDefault();
        if (!e.repeat) this.trigger(action);
      }
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') e.preventDefault();
      if (e.code === 'KeyC') e.preventDefault();
      this.keys.add(e.code);
    });
    window.addEventListener('keyup', e => { this.keys.delete(e.code); });
    window.addEventListener('blur', () => { this.keys.clear(); this.joystick.active = false; this.joystick.x = this.joystick.y = 0; });

    this.el.addEventListener('contextmenu', e => e.preventDefault());
    this.el.addEventListener('pointerdown', e => {
      if (!this.enabled) return;
      if (e.pointerType === 'touch') {
        if (e.clientX > window.innerWidth * 0.5) {
          this.touchCamera.active = true; this.touchCamera.id = e.pointerId;
          this.touchCamera.x = e.clientX; this.touchCamera.y = e.clientY;
          this.el.setPointerCapture?.(e.pointerId);
          e.preventDefault();
        }
        return;
      }
      this.dragging = true;
      this.dragButton = e.button;
      this.dragMoved = 0;
      this.lastX = e.clientX; this.lastY = e.clientY;
      this.el.setPointerCapture?.(e.pointerId);
      e.preventDefault();
    });
    this.el.addEventListener('pointermove', e => {
      if (e.pointerType === 'touch' && this.touchCamera.active && e.pointerId === this.touchCamera.id) {
        const dx = e.clientX - this.touchCamera.x;
        const dy = e.clientY - this.touchCamera.y;
        this.touchCamera.x = e.clientX; this.touchCamera.y = e.clientY;
        this.yaw -= dx * 0.006;
        this.pitch = Math.max(-0.25, Math.min(0.95, this.pitch + dy * 0.005));
        return;
      }
      if (!this.dragging) return;
      const dx = e.clientX - this.lastX;
      const dy = e.clientY - this.lastY;
      this.lastX = e.clientX; this.lastY = e.clientY;
      this.dragMoved += Math.abs(dx) + Math.abs(dy);
      this.yaw -= dx * 0.0045;
      this.pitch = Math.max(-0.3, Math.min(1.05, this.pitch + dy * 0.0038));
    });
    const endDrag = e => {
      if (e.pointerType === 'touch') {
        if (e.pointerId === this.touchCamera.id) this.touchCamera.active = false;
        return;
      }
      if (!this.dragging) return;
      const moved = this.dragMoved;
      const button = this.dragButton;
      this.dragging = false;
      if (moved < 6) this.trigger(button === 2 ? 'heavy' : 'light');
    };
    this.el.addEventListener('pointerup', endDrag);
    this.el.addEventListener('pointercancel', e => {
      if (e.pointerType === 'touch') this.touchCamera.active = false;
      else this.dragging = false;
    });
    this.el.addEventListener('wheel', e => {
      if (!this.enabled) return;
      this.zoomTarget = Math.max(90, Math.min(520, this.zoomTarget + e.deltaY * 0.35));
      e.preventDefault();
    }, { passive: false });
  }

  attachJoystick(el, knob) {
    this.joystickEl = el;
    this.joystickKnob = knob;
    const setFromEvent = e => {
      const r = el.getBoundingClientRect();
      const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
      let dx = e.clientX - cx, dy = e.clientY - cy;
      const max = r.width * 0.38;
      const len = Math.hypot(dx, dy);
      if (len > max) { dx = dx / len * max; dy = dy / len * max; }
      this.joystick.x = dx / max;
      this.joystick.y = dy / max;
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
    };
    el.addEventListener('pointerdown', e => {
      if (!this.enabled) return;
      e.preventDefault(); e.stopPropagation();
      this.joystick.active = true;
      this.joystick.pointerId = e.pointerId;
      el.setPointerCapture?.(e.pointerId);
      setFromEvent(e);
    });
    el.addEventListener('pointermove', e => {
      if (!this.joystick.active || e.pointerId !== this.joystick.pointerId) return;
      e.preventDefault(); e.stopPropagation();
      setFromEvent(e);
    });
    const end = e => {
      if (e.pointerId !== this.joystick.pointerId) return;
      this.joystick.active = false;
      this.joystick.pointerId = null;
      this.joystick.x = this.joystick.y = 0;
      knob.style.transform = 'translate(0px, 0px)';
    };
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
  }

  trigger(action) {
    this.actions.push(action);
    this.onAction?.(action);
  }

  get block() {
    return this.keys.has('KeyC') || this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.mobileBlock;
  }
  get run() { return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.mobileRun; }

  getMove(cameraYaw) {
    let x = 0, z = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) z += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) z -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.joystick.active) {
      x += this.joystick.x;
      z += -this.joystick.y;
    }
    const len = Math.hypot(x, z);
    if (len > 1) { x /= len; z /= len; }
    if (len < 0.05) return { x: 0, z: 0, active: false };
    // camera-relative basis: forward = (-sin yaw, -cos yaw), right = (cos yaw, -sin yaw)
    const fx = -Math.sin(cameraYaw), fz = -Math.cos(cameraYaw);
    const rx = Math.cos(cameraYaw), rz = -Math.sin(cameraYaw);
    return { x: fx * z + rx * x, z: fz * z + rz * x, active: true };
  }

  consumeActions() {
    const a = this.actions;
    this.actions = [];
    return a;
  }

  reset() {
    this.keys.clear();
    this.actions = [];
    this.dragging = false;
    this.joystick.active = false;
    this.joystick.x = this.joystick.y = 0;
    this.mobileBlock = false;
    this.mobileRun = false;
  }
}

export class CameraRig {
  constructor(camera, settings, effects) {
    this.camera = camera;
    this.settings = settings;
    this.effects = effects;
    this.position = new THREE.Vector3(0, 100, 260);
    this.look = new THREE.Vector3(0, 50, 0);
    this.target = new THREE.Vector3();
    this.currentDistance = 240;
    this.currentYaw = 0;
    this.currentPitch = 0.2;
    this.intro = 0;
    this.introDuration = 0;
    this.introFrom = new THREE.Vector3();
    this.introFromLook = new THREE.Vector3();
    this.cinematic = 0;
    this.cinematicFocus = null;
    this.spectate = false;
    this.spectateAngle = 0;
    this.tmp = new THREE.Vector3();
  }

  snapTo(target, input) {
    this.target.copy(target.root.position);
    this.currentYaw = input.yaw;
    this.currentPitch = input.pitch;
    this.currentDistance = input.distance;
    const off = this.offset(this.currentYaw, this.currentPitch, this.currentDistance, target);
    this.position.copy(target.root.position).add(off);
    this.look.copy(target.root.position).add(new THREE.Vector3(0, target.height * 0.55, 0));
    this.camera.position.copy(this.position);
    this.camera.lookAt(this.look);
  }

  offset(yaw, pitch, distance, target) {
    const h = target.height;
    const d = distance * (0.7 + h / 180);
    return new THREE.Vector3(
      Math.sin(yaw) * Math.cos(pitch) * d,
      Math.sin(pitch) * d + h * 0.35,
      Math.cos(yaw) * Math.cos(pitch) * d,
    );
  }

  startIntro(duration = 2.2) {
    this.intro = duration;
    this.introDuration = duration;
    this.introFrom.copy(this.camera.position);
    this.introFromLook.copy(this.look);
  }

  update(dt, target, input, monsters = []) {
    const shake = this.effects.getShake(dt);
    this.cinematic = Math.max(0, this.cinematic - dt);
    if (this.intro > 0) {
      this.intro -= dt;
      const t = 1 - Math.max(0, this.intro) / this.introDuration;
      const e = 1 - Math.pow(1 - t, 3);
      const off = this.offset(input.yaw, input.pitch, input.distance, target);
      const desired = target.root.position.clone().add(off);
      const desiredLook = target.root.position.clone().add(new THREE.Vector3(0, target.height * 0.55, 0));
      // cinematic sweep from a high, wide angle
      const from = this.introFrom;
      const lookFrom = this.introFromLook;
      this.camera.position.lerpVectors(from, desired, e);
      this.look.lerpVectors(lookFrom, desiredLook, e);
      this.camera.lookAt(this.look);
      return;
    }
    if (this.spectate) {
      this.spectateAngle += dt * 0.12;
      const center = new THREE.Vector3();
      let count = 0;
      for (const m of monsters) if (!m.dead) { center.add(m.root.position); count++; }
      if (count) center.divideScalar(count);
      else center.set(0, 0, 0);
      const radius = 320;
      this.camera.position.set(center.x + Math.sin(this.spectateAngle) * radius, 160 + Math.sin(this.spectateAngle * 0.7) * 40, center.z + Math.cos(this.spectateAngle) * radius);
      this.look.set(center.x, 70, center.z);
      this.camera.lookAt(this.look);
      return;
    }
    this.target.lerp(target.root.position, 1 - Math.exp(-dt * 8));
    this.currentYaw = input.yaw;
    this.currentPitch = input.pitch;
    this.currentDistance += (input.zoomTarget - this.currentDistance) * (1 - Math.exp(-dt * 6));
    const off = this.offset(this.currentYaw, this.currentPitch, this.currentDistance, target);
    const desired = this.target.clone().add(off);
    // simple building-aware camera: lift if too low / close
    desired.y = Math.max(desired.y, 12);
    this.position.lerp(desired, 1 - Math.exp(-dt * 6));
    const lookTarget = this.target.clone().add(new THREE.Vector3(0, target.height * (0.5 + Math.sin(this.currentPitch) * 0.12), 0));
    this.look.lerp(lookTarget, 1 - Math.exp(-dt * 9));
    this.camera.position.copy(this.position);
    this.camera.position.x += shake.x * 4;
    this.camera.position.y += shake.y * 4;
    this.camera.lookAt(this.look);
  }

  cinematicPush(focus, strength = 1) {
    this.cinematic = 0.8 * strength;
    this.cinematicFocus = focus;
  }
}

import * as THREE from 'three';
import { Effects } from '../core/effects.js';
import { Environment } from '../world/environment.js';
import { City } from '../world/city.js';
import { Monster } from './monster.js';
import { Input, CameraRig } from './input.js';
import { getMonster, TEAM_NAMES } from '../monsters/data.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (v, t, l, dt) => v + (t - v) * (1 - Math.exp(-l * dt));

const QUICK_BATTLE = {
  mode: 'battle',
  playerId: 'godzilla2019',
  enemies: ['ghidorah'],
  allies: [],
  weather: 'rain',
  time: 'sunset',
  intro: true,
  title: 'GODZILLA VS KING GHIDORAH',
};

export class Game {
  constructor({ renderer, settings, audio, ui, onExit }) {
    this.renderer = renderer;
    this.settings = settings;
    this.audio = audio;
    this.ui = ui;
    this.onExit = onExit;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(56, window.innerWidth / window.innerHeight, 1, 4500);
    this.camera.position.set(220, 180, 380);
    this.time = 0;
    this.active = false;
    this.paused = false;
    this.mode = 'battle';
    this.config = null;
    this.monsters = [];
    this.player = null;
    this.introTimer = 0;
    this.resultPending = 0;
    this.resultShown = false;
    this.stats = { damageDealt: 0, damageTaken: 0, kills: 0, startTime: 0 };
    this.spectate = false;
    this.hasStarted = false;
    this.objective = '';
    this.subObjective = '';
    this.tmp = new THREE.Vector3();

    this.effects = new Effects(this.scene, settings);
    this.environment = new Environment(this.scene, settings, this.effects);
    this.environment.attachRenderer(renderer);
    this.environment.onThunder = () => this.audio.thunder();
    this.city = new City(this.scene, settings, this.effects, audio);
    this.environment.attachCity(this.city);
    this.city.onDestruction = () => {
      if (this.ui) this.ui.toast('STRUCTURE COLLAPSED', 'info');
    };

    this.input = new Input(renderer, settings);
    this.cameraRig = new CameraRig(this.camera, settings, this.effects);
    this.input.enabled = false;
    this.input.onAction = (action) => this.ui?.flashAction?.(action);
    this.bindUi();
    this.setWeather('rain', true);
    this.environment.setTimePreset('sunset');
    this.city.setWetness(true);
  }

  bindUi() {
    // The UI calls back into the game for live sandbox/HUD actions.
    if (this.ui) {
      this.ui.game = this;
      this.ui.onGameAction = (action, payload) => this.handleUiAction(action, payload);
    }
  }

  handleUiAction(action, payload) {
    switch (action) {
      case 'pause': this.pause(); break;
      case 'resume': this.resume(); break;
      case 'restart': this.restart(); break;
      case 'menu': this.exitToMenu(); break;
      case 'switch-monster': this.switchPlayer(); break;
      case 'weather': this.cycleWeather(); break;
      case 'time': this.cycleTime(); break;
      case 'set-weather': this.setWeather(payload); break;
      case 'set-time': this.setTime(payload); break;
      case 'spawn-monster': this.spawnSandboxMonster(payload); break;
      case 'spawn-vehicle': this.spawnSandboxVehicle(payload); break;
      case 'spawn-npc': this.spawnSandboxNPC(); break;
      case 'spawn-prop': this.spawnSandboxProp(payload); break;
      case 'spawn-building': this.spawnSandboxBuilding(); break;
      case 'toggle-ai': this.setAI(payload); break;
      case 'possess': this.switchPlayer(payload); break;
      case 'reset-world': this.resetWorld(); break;
      case 'spectate': this.setSpectate(payload); break;
      case 'rematch': this.restart(); break;
      case 'sandbox': this.start({ ...this.config, mode: 'sandbox', title: 'SANDBOX' }); break;
      default: break;
    }
  }

  start(config = QUICK_BATTLE) {
    this.config = JSON.parse(JSON.stringify(config));
    this.mode = config.mode || 'battle';
    this.spectate = !!config.spectate;
    this.resultPending = 0;
    this.resultShown = false;
    this.stats = { damageDealt: 0, damageTaken: 0, kills: 0, startTime: this.time };
    this.ui?.hideMenu();
    this.ui?.closeOverlays();
    this.clearMonsters();
    this.effects.clear();
    this.city.reset();
    this.city.setWetness(config.weather === 'rain' || config.weather === 'storm');
    this.setWeather(config.weather || 'clear', true);
    this.setTime(config.time || 'sunset');
    this.paused = false;
    this.input.reset();
    this.input.enabled = true;
    this.input.yaw = 0;
    this.input.pitch = 0.18;
    this.input.zoomTarget = this.mode === 'battle' ? 260 : 240;
    this.introTimer = config.intro ? 2.6 : 0;

    const spawn = [];
    if (this.spectate) {
      spawn.push({ id: config.playerId || 'godzilla2019', team: 0, ai: true, x: 0, z: 100, yaw: 0 });
      for (const id of config.enemies || []) spawn.push({ id, team: 1, ai: true, x: 0, z: -100, yaw: Math.PI });
    } else {
      spawn.push({ id: config.playerId || 'godzilla2019', team: 0, ai: false, x: 0, z: 110, yaw: 0 });
      let i = 0;
      for (const id of config.allies || []) {
        spawn.push({ id, team: 0, ai: true, x: -90 + i * 90, z: 150, yaw: 0 });
        i++;
      }
      i = 0;
      for (const id of config.enemies || []) {
        const angle = Math.PI + (i - ((config.enemies || []).length - 1) / 2) * 0.35;
        spawn.push({ id, team: 1, ai: true, x: Math.sin(angle) * -70, z: -110, yaw: Math.PI });
        i++;
      }
    }
    // battle spawn positions
    if (this.mode === 'battle') {
      for (const s of spawn) {
        if (s.team === 0 && !s.ai) { s.x = 0; s.z = 115; s.yaw = 0; }
        if (s.team === 1) { s.x = (Math.random() - 0.5) * 40; s.z = -105 - Math.random() * 25; s.yaw = Math.PI; }
      }
    }
    for (const s of spawn) {
      const m = this.addMonster(s.id, { team: s.team, x: s.x, z: s.z, yaw: s.yaw, ai: s.ai });
      if (s.ai === false) this.player = m;
    }
    if (this.spectate) this.player = null;
    if (!this.player && !this.spectate) this.player = this.monsters[0] || null;
    if (this.player) this.player.setPlayer(true);
    if (this.spectate) this.cameraRig.spectate = true;
    else this.cameraRig.spectate = false;

    // camera
    const target = this.player || this.monsters[0];
    if (target) {
      if (this.mode === 'battle' && config.intro) {
        this.camera.position.set(260, 230, 420);
        this.cameraRig.look.set(0, 60, 0);
        this.camera.lookAt(this.cameraRig.look);
        this.cameraRig.startIntro(2.6);
        this.ui?.showVersus?.(this.player, this.monsters.filter(m => m.team !== (this.player?.team ?? 0)));
      } else {
        this.cameraRig.snapTo(target, this.input);
      }
    }
    this.introTimer = this.cameraRig.intro;

    this.active = true;
    this.hasStarted = true;
    this.ui?.showHUD(this);
    this.ui?.closeOverlays();
    this.updateObjective();
    this.ui?.toast(this.mode === 'battle' ? 'BATTLE START' : this.mode === 'sandbox' ? 'SANDBOX ONLINE' : 'FREE ROAM', 'info');
    this.audio.setWeather(this.mode === 'battle' ? (config.weather || 'rain') : (config.weather || 'clear'));
    if (this.mode === 'battle' && config.title) this.ui?.showTitle?.(config.title);
    // spawn roar
    setTimeout(() => {
      if (this.active && this.player && !this.player.dead) this.audio.roar(this.player.def);
    }, 1200);
  }

  addMonster(id, opts) {
    const def = getMonster(id);
    const m = new Monster(this, def, opts);
    this.monsters.push(m);
    return m;
  }

  clearMonsters() {
    for (const m of this.monsters) m.dispose();
    this.monsters = [];
    this.player = null;
  }

  update(dt) {
    if (!this.active || this.paused) return;
    dt = Math.min(dt, 0.05);
    this.time += dt;
    this.environment.update(dt, this.camera);
    this.city.update(dt, this.camera, this.monsters);

    // player intent
    const p = this.player;
    if (p && !p.dead && !this.spectate) {
      const move = this.input.getMove(this.input.yaw);
      p.intent.moveX = move.x;
      p.intent.moveZ = move.z;
      p.intent.run = this.input.run && !this.input.block;
      p.intent.block = this.input.block;
      p.intent.attack = null;
      p.intent.special = false;
      p.intent.dodge = false;
      p.intent.jump = false;
      p.intent.grab = false;
      p.intent.roar = false;
      p.intent.aimYaw = this.input.yaw;
      // soft lock nearest hostile in front for satisfying melee
      let best = null, bestD = 1e9;
      const camF = new THREE.Vector3(-Math.sin(this.input.yaw), 0, -Math.cos(this.input.yaw));
      for (const m of this.monsters) {
        if (m === p || m.dead || m.team === p.team) continue;
        const to = m.root.position.clone().sub(p.root.position).setY(0);
        const d = to.length();
        if (d < p.height * 2.2 && d < bestD) {
          to.normalize();
          if (to.dot(camF) > 0.1) { best = m; bestD = d; }
        }
      }
      const actions = this.input.consumeActions();
      for (const a of actions) {
        if (a === 'light' || a === 'heavy' || a === 'tail' || a === 'bite' || a === 'stomp') {
          if (best) p.intent.aimYaw = Math.atan2(-(best.root.position.x - p.root.position.x), -(best.root.position.z - p.root.position.z));
          p.intent.attack = a;
        } else if (a === 'special') { p.intent.special = true; if (best) p.intent.aimYaw = Math.atan2(-(best.root.position.x - p.root.position.x), -(best.root.position.z - p.root.position.z)); }
        else if (a === 'grab') p.intent.grab = true;
        else if (a === 'roar') p.intent.roar = true;
        else if (a === 'dodge') p.intent.dodge = true;
        else if (a === 'jump') p.intent.jump = true;
      }
      if (p.state.grabbed && this.input.keys.has('KeyG')) p.throwGrabbed?.();
    } else if (p) {
      p.intent.moveX = p.intent.moveZ = 0;
      p.intent.attack = null;
      p.intent.special = false;
      this.input.consumeActions();
    }

    for (const m of this.monsters) m.update(dt);
    this.effects.update(dt, this.camera);
    const target = this.player && !this.player.dead ? this.player : (this.monsters.find(m => !m.dead) || null);
    if (target) {
      if (this.spectate) this.cameraRig.spectate = true;
      this.cameraRig.update(dt, target, this.input, this.monsters);
    }
    // cinematic fov
    const wantFov = this.cameraRig.cinematic > 0 ? 46 : 56;
    this.camera.fov = damp(this.camera.fov, wantFov, 3, dt);
    this.camera.updateProjectionMatrix();

    if (this.introTimer > 0) {
      this.introTimer -= dt;
      if (this.introTimer <= 0) this.ui?.hideVersus?.();
    }
    this.checkEnd(dt);
    this.updateObjective();
    this.ui?.updateHUD?.(this, dt);
  }

  updateObjective() {
    if (this.mode === 'battle') {
      const enemies = this.monsters.filter(m => m.team !== (this.player?.team ?? 0) && !m.dead);
      const names = enemies.map(m => m.name.toUpperCase()).join(' + ');
      this.objective = enemies.length ? `SLAY ${names}` : 'HOSTILES ELIMINATED';
      this.subObjective = `HONG KONG // ${this.environment.weather.toUpperCase()} // ${this.environment.hour.toFixed(1).padStart(4, '0')}:00`;
    } else if (this.mode === 'sandbox') {
      this.objective = 'SANDBOX';
      this.subObjective = 'SPAWN, POSSESS, DESTROY';
    } else {
      this.objective = 'FREE ROAM';
      this.subObjective = `${this.city.destructionCount} STRUCTURES DESTROYED`;
    }
  }

  checkEnd(dt) {
    if (this.mode !== 'battle' || this.resultShown || this.spectate) return;
    if (!this.player) return;
    const enemies = this.monsters.filter(m => m.team !== this.player.team);
    const allies = this.monsters.filter(m => m.team === this.player.team);
    const enemiesAlive = enemies.some(m => !m.dead);
    const alliesAlive = allies.some(m => !m.dead);
    if (!enemiesAlive && enemies.length) {
      this.resultPending += dt;
      if (this.resultPending > 1.5) this.showResult(true);
    } else if (!alliesAlive) {
      this.resultPending += dt;
      if (this.resultPending > 1.5) this.showResult(false);
    }
  }

  showResult(win) {
    if (this.resultShown) return;
    this.resultShown = true;
    this.paused = true;
    if (win) { this.audio.victory(); this.cameraRig.cinematic = 2; }
    else this.audio.defeat();
    const stats = {
      time: Math.max(1, Math.round(this.time - this.stats.startTime)),
      destroyed: this.city.destructionCount,
      damage: Math.round(this.stats.damageDealt),
      kills: this.stats.kills,
    };
    this.ui?.showResult?.(win, stats);
  }

  onMonsterDeath(monster, attacker) {
    if (attacker === this.player) this.stats.kills++;
    if (monster === this.player) {
      this.stats.damageTaken = Math.round(monster.maxHp);
    }
    if (this.mode === 'battle' && !this.spectate) {
      this.resultPending = 0;
    }
  }

  melee(attacker, kind, stats) {
    const f = attacker.forward;
    const origin = attacker.root.position.clone().addScaledVector(f, attacker.radius * 0.5);
    const centerY = attacker.root.position.y + attacker.height * 0.52;
    const range = stats.range + attacker.radius * 0.45;
    let hits = 0;
    for (const m of this.monsters) {
      if (m === attacker || m.dead) continue;
      if (m.team === attacker.team && this.mode !== 'sandbox') continue;
      const to = m.root.position.clone().sub(attacker.root.position).setY(0);
      const d = to.length();
      if (d > range + m.radius) continue;
      to.normalize();
      const dot = to.dot(f);
      if (dot < Math.cos(Math.min(Math.PI, stats.arc) / 2)) continue;
      const point = m.root.position.clone().setY(centerY + (Math.random() - 0.5) * m.height * 0.2);
      const dmg = stats.damage * (1 - Math.max(0, d - attacker.radius) / (range * 2.2));
      const dealt = m.takeDamage(dmg, attacker, point, stats.force, 'impact');
      if (attacker === this.player) this.stats.damageDealt += dealt;
      this.effects.sparks(point, 10, 0xffd28a, 18);
      this.effects.blood(point, 4);
      hits++;
    }
    // city destruction in front
    const hitPoint = attacker.root.position.clone().addScaledVector(f, stats.range * 0.55).setY(Math.max(2, centerY * 0.7));
    const cityRadius = Math.max(attacker.radius, stats.range * 0.65);
    const before = this.city.destructionCount;
    this.city.damageAt(hitPoint, cityRadius, stats.damage * 0.9, { source: attacker });
    if (this.city.destructionCount > before) this.effects.shakeCamera(0.35, 0.5);
    this.effects.dust(hitPoint, attacker.radius * 0.5, 6, 0x9a8f80);
    return { hit: hits, point: hitPoint };
  }

  aoe(attacker, center, radius, damage, force, type = 'impact', opts = {}) {
    let hits = 0;
    for (const m of this.monsters) {
      if (m === attacker || m.dead) continue;
      if (m.team === attacker.team) continue;
      const d = m.root.position.distanceTo(center);
      if (d > radius + m.radius) continue;
      const fall = 1 - d / (radius + m.radius);
      const dir = m.root.position.clone().sub(center).setY(0).normalize();
      const status = type === 'firestorm' ? 'burn' : type === 'acid' ? 'acid' : type === 'freezeBeam' ? 'freeze' : 'impact';
      const dealt = m.takeDamage(damage * (0.45 + fall * 0.75), attacker, center.clone(), force * (0.5 + fall), status);
      if (attacker === this.player) this.stats.damageDealt += dealt;
      hits++;
    }
    if (opts.building !== false) {
      this.city.damageAt(center, radius, damage * 0.8, { source: attacker });
    }
    if (opts.color) this.effects.shockwave(center, radius, opts.color);
    this.effects.shakeCamera(0.3 + radius / 100, 0.5);
    return hits;
  }

  roarWave(monster) {
    const center = monster.root.position;
    this.effects.shockwave(center, monster.height * 0.9, monster.def.colors.glow);
    this.effects.dust(center.clone(), monster.radius * 1.2, 24, 0x9a8f80);
    this.effects.shakeCamera(0.3, 0.7);
    this.cameraRig.cinematic = Math.max(this.cameraRig.cinematic, 0.5);
    for (const m of this.monsters) {
      if (m === monster || m.dead) continue;
      const d = m.root.position.distanceTo(center);
      if (d < monster.height * 2.6) {
        if (m.team === monster.team) {
          m.stamina = Math.min(m.maxStamina, m.stamina + 18);
        } else {
          m.balance -= 12;
          const dir = m.root.position.clone().sub(center).setY(0).normalize();
          m.velocity.addScaledVector(dir, 5);
          if (m.balance <= 0) m.knockdown(dir, 6);
        }
      }
    }
    for (const ped of this.city.pedestrians) {
      if (ped.group.position.distanceTo(center) < 220) ped.panic = 1;
    }
  }

  findGrabTarget(monster) {
    const f = monster.forward;
    let best = null, bd = 1e9;
    for (const m of this.monsters) {
      if (m === monster || m.dead) continue;
      if (m.team === monster.team) continue;
      const to = m.root.position.clone().sub(monster.root.position).setY(0);
      const d = to.length();
      if (d > monster.radius + m.radius + monster.height * 0.22) continue;
      to.normalize();
      if (to.dot(f) < 0.15) continue;
      if (d < bd) { bd = d; best = m; }
    }
    return best;
  }

  beamTarget(monster, origin, dir, range) {
    const ray = new THREE.Ray(origin, dir.clone().normalize());
    let best = { point: origin.clone().addScaledVector(dir, range), distance: range, monster: null, building: null };
    for (const m of this.monsters) {
      if (m === monster || m.dead) continue;
      if (m.team === monster.team) continue;
      const center = m.root.position.clone().add(new THREE.Vector3(0, m.height * 0.55, 0));
      const sphere = new THREE.Sphere(center, m.height * 0.32);
      const hit = ray.intersectSphere(sphere, new THREE.Vector3());
      if (hit) {
        const d = hit.distanceTo(origin);
        if (d < best.distance) best = { point: hit, distance: d, monster: m, building: null };
      }
    }
    const b = this.city.raycastBuilding(origin, dir, Math.min(range, best.distance));
    if (b) best = { point: b.point, distance: b.distance, monster: null, building: b.building };
    if (dir.y < -0.02) {
      const t = -origin.y / dir.y;
      if (t > 0 && t < best.distance) {
        best = { point: origin.clone().addScaledVector(dir, t).setY(0.6), distance: t, monster: null, building: null };
      }
    }
    return best;
  }

  spawnBeam(monster, origin, dir, sp, width, duration, offset = 0) {
    const start = origin.clone();
    if (offset) start.add(new THREE.Vector3((Math.random() - 0.5) * offset, (Math.random() - 0.5) * offset, (Math.random() - 0.5) * offset));
    const res = this.beamTarget(monster, start, dir, sp.range);
    const effect = this.effects.beam({ start, end: res.point, color: sp.color, secondary: sp.secondary, width, duration });
    return { start, effect, target: res, dead: false };
  }

  beamDamage(monster, res, sp, beam) {
    const dmg = sp.damage * 0.28;
    const type = sp.type === 'freezeBeam' ? 'freeze' : 'impact';
    if (res.monster) {
      const dir = res.monster.root.position.clone().sub(monster.root.position).setY(0).normalize();
      const dealt = res.monster.takeDamage(dmg, monster, res.point, 6, type);
      if (monster === this.player) this.stats.damageDealt += dealt;
      this.effects.sparks(res.point, 6, sp.color, 12);
    } else if (res.building) {
      res.building.damage(dmg * 1.5, res.point, { source: monster });
      this.effects.glass(res.point, 5);
      this.effects.dust(res.point, 3, 4, 0x9a8f80);
    } else {
      this.city.damageAt(res.point, 9, dmg * 0.8, { source: monster });
      this.effects.dust(res.point, 5, 4, 0x9a8f80);
    }
    if (sp.type === 'freezeBeam') this.effects.ice(res.point, 5);
    if (monster === this.player) this.effects.shakeCamera(0.1, 0.2);
  }

  cycleWeather() {
    const order = ['clear', 'rain', 'storm', 'fog'];
    const i = order.indexOf(this.environment.weather);
    this.setWeather(order[(i + 1) % order.length]);
  }

  setWeather(kind, silent = false) {
    this.environment.setWeather(kind, true);
    this.audio.setWeather(kind);
    this.city.setWetness(kind === 'rain' || kind === 'storm');
    this.ui?.setWeatherLabel?.(kind);
    if (!silent) this.ui?.toast(`WEATHER // ${kind.toUpperCase()}`, 'info');
  }

  cycleTime() {
    const order = ['sunrise', 'day', 'sunset', 'night'];
    const names = ['sunrise', 'day', 'sunset', 'night'];
    const cur = this.environment.hour;
    let idx = cur < 8 ? 0 : cur < 16.5 ? 1 : cur < 20 ? 2 : 3;
    this.setTime(order[(idx + 1) % order.length]);
  }

  setTime(preset) {
    this.environment.setTimePreset(preset);
    this.ui?.setTimeLabel?.(preset);
    this.ui?.toast(`TIME // ${preset.toUpperCase()}`, 'info');
  }

  pause() {
    if (!this.active || this.resultShown) return;
    this.paused = true;
    this.ui?.openPause?.();
  }

  resume() {
    this.paused = false;
    this.ui?.closeOverlays();
  }

  restart() {
    const cfg = JSON.parse(JSON.stringify(this.config || QUICK_BATTLE));
    this.resultShown = false;
    this.start(cfg);
  }

  exitToMenu() {
    this.active = false;
    this.paused = false;
    this.input.enabled = false;
    this.input.reset();
    this.ui?.hideHUD?.();
    this.ui?.closeOverlays();
    this.ui?.showMenu?.();
    this.clearMonsters();
    this.effects.clear();
    this.onExit?.();
  }

  switchPlayer(index = null) {
    const alive = this.monsters.filter(m => !m.dead);
    if (!alive.length) return;
    let next;
    if (typeof index === 'number' && this.monsters[index] && !this.monsters[index].dead) next = this.monsters[index];
    else {
      const cur = this.player ? alive.indexOf(this.player) : -1;
      next = alive[(cur + 1) % alive.length];
    }
    if (next === this.player) return;
    if (this.player) this.player.setPlayer(false);
    this.player = next;
    next.setPlayer(true);
    this.cameraRig.snapTo(next, this.input);
    this.ui?.toast(`NOW CONTROLLING ${next.name.toUpperCase()}`, 'info');
    this.updateObjective();
  }

  setSpectate(on) {
    this.spectate = !!on;
    this.cameraRig.spectate = this.spectate;
    if (this.player) { this.player.setPlayer(false); this.player.ai = this.player.ai || null; }
    if (!this.spectate && this.player) this.player.setPlayer(true);
    this.ui?.toast(this.spectate ? 'SPECTATOR MODE' : 'CONTROL RESTORED', 'info');
  }

  setAI(on) {
    for (const m of this.monsters) {
      if (m === this.player) continue;
      if (on) { if (!m.ai) m.ai = m.constructor.prototype.ai; } else m.ai = null;
    }
    // The AI is a small class; recreate through its module helper.
    for (const m of this.monsters) {
      if (m === this.player) continue;
      if (on && !m.ai) { m.ai = new (m._aiClass || Object)(); }
    }
    this.ui?.toast(`AI ${on ? 'ENABLED' : 'DISABLED'}`, 'info');
  }

  spawnSandboxMonster(id, opts = {}) {
    if (!id) return;
    const p = this.spawnPoint(130);
    const team = opts.team ?? 1;
    const m = this.addMonster(id, { team, x: p.x, z: p.z, yaw: Math.atan2(-(this.player?.root.position.x - p.x || 0), -(this.player?.root.position.z - p.z || -1)), ai: opts.ai !== false });
    this.effects.dust(m.root.position.clone(), m.radius, 20, 0xa89a86);
    this.ui?.toast(`${m.name.toUpperCase()} SPAWNED`, 'info');
    if (this.ui?.refreshSandbox) this.ui.refreshSandbox(this);
    return m;
  }

  spawnSandboxVehicle(type = 'car') {
    const p = this.spawnPoint(80);
    const v = this.city.spawnVehicle(type, p);
    this.ui?.toast('VEHICLE DEPLOYED', 'info');
    return v;
  }

  spawnSandboxNPC() {
    const p = this.spawnPoint(70);
    const n = this.city.spawnNPC(p);
    this.ui?.toast('CIVILIAN DEPLOYED', 'info');
    return n;
  }

  spawnSandboxProp(type = 'tree') {
    const p = this.spawnPoint(90);
    const n = this.city.spawnProp(type, p);
    this.ui?.toast('PROP DEPLOYED', 'info');
    return n;
  }

  spawnSandboxBuilding() {
    const p = this.spawnPoint(150);
    const b = this.city.spawnBuilding(p.x, p.z, 24 + Math.random() * 18, 24 + Math.random() * 18, 60 + Math.random() * 120);
    this.ui?.toast('STRUCTURE DEPLOYED', 'info');
    return b;
  }

  spawnPoint(dist = 100) {
    const base = this.player ? this.player.root.position : this.camera.position;
    const f = new THREE.Vector3(-Math.sin(this.input.yaw), 0, -Math.cos(this.input.yaw));
    const p = base.clone().addScaledVector(f, dist);
    p.y = 0;
    p.x = clamp(p.x, -380, 380);
    p.z = clamp(p.z, -380, 380);
    const hit = this.city.collideCircle(p.x, p.z, 20);
    p.x += hit.pushX; p.z += hit.pushZ;
    return p;
  }

  resetWorld() {
    this.city.reset();
    this.effects.clear();
    this.ui?.toast('WORLD RESET', 'info');
  }

  setWeatherLabel() {}
}

