82:       case 'restart': this.restart(); break;
83:       case 'menu': this.exitToMenu(); break;
84:       case 'switch-monster': this.switchPlayer(); break;
85:       case 'weather': this.cycleWeather(); break;
86:       case 'time': this.cycleTime(); break;
87:       case 'set-weather': this.setWeather(payload); break;
88:       case 'set-time': this.setTime(payload); break;
89:       case 'spawn-monster': this.spawnSandboxMonster(payload); break;
90:       case 'spawn-vehicle': this.spawnSandboxVehicle(payload); break;
91:       case 'spawn-npc': this.spawnSandboxNPC(); break;
92:       case 'spawn-prop': this.spawnSandboxProp(payload); break;
93:       case 'spawn-building': this.spawnSandboxBuilding(); break;
94:       case 'toggle-ai': this.setAI(payload); break;
95:       case 'possess': this.switchPlayer(payload); break;
96:       case 'reset-world': this.resetWorld(); break;
97:       case 'spectate': this.setSpectate(payload); break;
98:       case 'rematch': this.restart(); break;
99:       case 'sandbox': this.start({ ...this.config, mode: 'sandbox', title: 'SANDBOX' }); break;
100:       default: break;
