104:   start(config = QUICK_BATTLE) {
105:     this.config = JSON.parse(JSON.stringify(config));
106:     this.mode = config.mode || 'battle';
107:     this.spectate = !!config.spectate;
108:     this.resultPending = 0;
109:     this.resultShown = false;
110:     this.stats = { damageDealt: 0, damageTaken: 0, kills: 0, startTime: this.time };
111:     this.ui?.hideMenu();
112:     this.ui?.closeOverlays();
113:     this.clearMonsters();
114:     this.effects.clear();
115:     this.city.reset();
116:     this.city.setWetness(config.weather === 'rain' || config.weather === 'storm');
117:     this.setWeather(config.weather || 'clear', true);
118:     this.setTime(config.time || 'sunset');
119:     this.paused = false;
120:     this.input.reset();
121:     this.input.enabled = true;
122:     this.input.yaw = 0;
123:     this.input.pitch = 0.18;
124:     this.input.zoomTarget = this.mode === 'battle' ? 260 : 240;
125:     this.introTimer = config.intro ? 2.6 : 0;
126: 
127:     const spawn = [];
128:     if (this.spectate) {
129:       spawn.push({ id: config.playerId || 'godzilla2019', team: 0, ai: true, x: 0, z: 100, yaw: 0 });
130:       for (const id of config.enemies || []) spawn.push({ id, team: 1, ai: true, x: 0, z: -100, yaw: Math.PI });
131:     } else {
132:       spawn.push({ id: config.playerId || 'godzilla2019', team: 0, ai: false, x: 0, z: 110, yaw: 0 });
133:       let i = 0;
134:       for (const id of config.allies || []) {
135:         spawn.push({ id, team: 0, ai: true, x: -90 + i * 90, z: 150, yaw: 0 });
136:         i++;
137:       }
138:       i = 0;
139:       for (const id of config.enemies || []) {
140:         const angle = Math.PI + (i - ((config.enemies || []).length - 1) / 2) * 0.35;
141:         spawn.push({ id, team: 1, ai: true, x: Math.sin(angle) * -70, z: -110, yaw: Math.PI });
142:         i++;
143:       }
144:     }
145:     // battle spawn positions
146:     if (this.mode === 'battle') {
147:       for (const s of spawn) {
148:         if (s.team === 0 && !s.ai) { s.x = 0; s.z = 115; s.yaw = 0; }
149:         if (s.team === 1) { s.x = (Math.random() - 0.5) * 40; s.z = -105 - Math.random() * 25; s.yaw = Math.PI; }
150:       }
151:     }
152:     for (const s of spawn) {
153:       const m = this.addMonster(s.id, { team: s.team, x: s.x, z: s.z, yaw: s.yaw, ai: s.ai });
154:       if (s.ai === false) this.player = m;
155:     }
156:     if (this.spectate) this.player = null;
157:     if (!this.player && !this.spectate) this.player = this.monsters[0] || null;
158:     if (this.player) this.player.setPlayer(true);
159:     if (this.spectate) this.cameraRig.spectate = true;
160:     else this.cameraRig.spectate = false;
161: 
162:     // camera
163:     const target = this.player || this.monsters[0];
164:     if (target) {
165:       if (this.mode === 'battle' && config.intro) {
166:         this.camera.position.set(260, 230, 420);
167:         this.cameraRig.look.set(0, 60, 0);
168:         this.camera.lookAt(this.cameraRig.look);
169:         this.cameraRig.startIntro(2.6);
170:         this.ui?.showVersus?.(this.player, this.monsters.filter(m => m.team !== (this.player?.team ?? 0)));
171:       } else {
172:         this.cameraRig.snapTo(target, this.input);
173:       }
174:     }
