324:   onMonsterDeath(monster, attacker) {
325:     if (attacker === this.player) this.stats.kills++;
326:     if (monster === this.player) {
327:       this.stats.damageTaken = Math.round(monster.maxHp);
328:     }
329:     if (this.mode === 'battle' && !this.spectate) {
330:       this.resultPending = 0;
331:     }
332:   }
