463:   beamDamage(monster, res, sp, beam) {
464:     const dmg = sp.damage * 0.28;
465:     const type = sp.type === 'freezeBeam' ? 'freeze' : 'impact';
466:     if (res.monster) {
467:       const dir = res.monster.root.position.clone().sub(monster.root.position).setY(0).normalize();
468:       const dealt = res.monster.takeDamage(dmg, monster, res.point, 6, type);
469:       if (monster === this.player) this.stats.damageDealt += dealt;
470:       this.effects.sparks(res.point, 6, sp.color, 12);
471:     } else if (res.building) {
472:       res.building.damage(dmg * 1.5, res.point, { source: monster });
473:       this.effects.glass(res.point, 5);
474:       this.effects.dust(res.point, 3, 4, 0x9a8f80);
475:     } else {
476:       this.city.damageAt(res.point, 9, dmg * 0.8, { source: monster });
477:       this.effects.dust(res.point, 5, 4, 0x9a8f80);
478:     }
479:     if (sp.type === 'freezeBeam') this.effects.ice(res.point, 5);
480:     if (monster === this.player) this.effects.shakeCamera(0.1, 0.2);
481:   }
