345:   updateMovement(dt, intent) {
346:     let mx = intent.moveX || 0, mz = intent.moveZ || 0;
347:     const len = Math.hypot(mx, mz);
348:     let targetSpeed = 0;
349:     if (len > 0.05 && !this.state.block) {
