352:       if (this.state.block) targetSpeed *= 0.25;
353:       const desiredYaw = Math.atan2(-mx, -mz);
354:       this.yaw = damp(this.yaw, desiredYaw, 8, dt);
355:     } else if (intent.faceTarget && !this.state.attack) {
356:       const dx = intent.faceTarget.root.position.x - this.root.position.x;
357:       const dz = intent.faceTarget.root.position.z - this.root.position.z;
358:       this.yaw = damp(this.yaw, Math.atan2(-dx, -dz), 5, dt);
359:     }
360:     if (this.state.block) targetSpeed = 0;
361:     const accel = targetSpeed > 0 ? 22 : 30;
362:     const vx = Math.sin(this.yaw) * -targetSpeed;
363:     const vz = Math.cos(this.yaw) * -targetSpeed;
364:     this.velocity.x = damp(this.velocity.x, vx, accel / 8, dt);
365:     this.velocity.z = damp(this.velocity.z, vz, accel / 8, dt);
366:     if (len < 0.05 && !this.state.attack) {
367:       this.velocity.x = damp(this.velocity.x, 0, 4, dt);
368:       this.velocity.z = damp(this.velocity.z, 0, 4, dt);
369:     }
