63: class ParticleLayer {
64:   constructor(scene, max, additive, texture) {
65:     this.max = max;
66:     this.items = [];
67:     this.positions = new Float32Array(max * 3);
68:     this.colors = new Float32Array(max * 3);
69:     this.sizes = new Float32Array(max);
70:     this.alphas = new Float32Array(max);
71:     const geo = new THREE.BufferGeometry();
72:     geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
73:     geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
74:     geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
75:     geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
76:     geo.setDrawRange(0, 0);
77:     const mat = new THREE.ShaderMaterial({
78:       uniforms: { map: { value: texture } },
79:       vertexShader: PARTICLE_VERT,
80:       fragmentShader: PARTICLE_FRAG,
81:       transparent: true,
82:       depthWrite: false,
83:       vertexColors: true,
84:       blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
85:     });
86:     this.points = new THREE.Points(geo, mat);
87:     this.points.frustumCulled = false;
88:     this.points.renderOrder = additive ? 4 : 2;
89:     scene.add(this.points);
90:     this.geo = geo;
91:   }
92: 
93:   emit(p) {
94:     if (this.items.length >= this.max) this.items.shift();
95:     this.items.push(p);
96:   }
97: 
98:   update(dt) {
99:     const items = this.items;
100:     let write = 0;
101:     for (let i = 0; i < items.length; i++) {
102:       const p = items[i];
103:       p.life -= dt;
104:       if (p.life <= 0) continue;
105:       p.vy -= (p.gravity || 0) * dt;
106:       const drag = Math.max(0, 1 - (p.drag || 0) * dt);
107:       p.vx *= drag; p.vz *= drag;
108:       p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
109:       if (p.y < 0.4 && p.vy < 0) {
110:         p.y = 0.4;
111:         p.vy *= -0.18;
112:         p.vx *= 0.7; p.vz *= 0.7;
113:       }
114:       const t = p.life / p.maxLife;
115:       const alpha = p.fade === 'in' ? Math.min(1, (1 - t) * 4) * t : t * (p.alpha ?? 1);
116:       const size = p.size * (p.grow ? (1 + (1 - t) * p.grow) : 1);
117:       const idx = write++;
118:       this.positions[idx * 3] = p.x;
119:       this.positions[idx * 3 + 1] = p.y;
120:       this.positions[idx * 3 + 2] = p.z;
121:       this.colors[idx * 3] = p.r;
122:       this.colors[idx * 3 + 1] = p.g;
123:       this.colors[idx * 3 + 2] = p.b;
124:       this.sizes[idx] = size;
125:       this.alphas[idx] = Math.max(0, Math.min(1, alpha));
126:       // keep alive items compacted
127:       if (write - 1 !== i) items[write - 1] = p;
128:     }
129:     items.length = write;
130:     this.geo.setDrawRange(0, write);
131:     this.geo.attributes.position.needsUpdate = true;
132:     this.geo.attributes.color.needsUpdate = true;
133:     this.geo.attributes.aSize.needsUpdate = true;
134:     this.geo.attributes.aAlpha.needsUpdate = true;
135:   }
136: 
137:   clear() { this.items.length = 0; this.geo.setDrawRange(0, 0); }
138: }
