572:   fireSpecial(a) {
573:     const sp = a.special;
574:     const head = this.headWorld(new THREE.Vector3());
575:     const dir = this.forward;
576:     if (sp.type === 'beam' || sp.type === 'freezeBeam') {
577:       const beam = this.game.spawnBeam(this, head, dir, sp, 1.25, this.isPlayer ? 2.6 : 2.2);
578:       this.activeBeams.push(beam);
579:       this.beamStop = this.game.audio.beamStart(this.def, 1.4);
580:       this.game.effects.explosion(head, 0.35, sp.color);
581:       this.game.hud?.cinematic(this, 1.0);
582:     } else if (sp.type === 'tripleBeam') {
583:       const origins = [];
584:       if (this.rig.necks) for (const n of this.rig.necks) {
585:         const p = new THREE.Vector3(); n.head.getWorldPosition(p); origins.push(p);
586:       } else origins.push(head);
587:       for (const o of origins) {
588:         this.activeBeams.push(this.game.spawnBeam(this, o, dir, sp, 1.15, 1.6, 0.4));
589:       }
590:       this.beamStop = this.game.audio.beamStart(this.def, 1.4);
591:       this.game.hud?.cinematic(this, 1.0);
592:     } else if (sp.type === 'godrays') {
593:       const origins = [head.clone().add(new THREE.Vector3(-this.height * 0.18, 0, 0)), head, head.clone().add(new THREE.Vector3(this.height * 0.18, 0, 0))];
594:       for (const o of origins) this.activeBeams.push(this.game.spawnBeam(this, o, dir, sp, 1.0, 1.1, 0.35));
595:       this.beamStop = this.game.audio.beamStart(this.def, 1.2);
596:       this.game.hud?.cinematic(this, 1.0);
597:     } else if (sp.type === 'pulse' || sp.type === 'shockwave' || sp.type === 'cleave' || sp.type === 'firestorm' || sp.type === 'acid') {
598:       const center = this.root.position.clone().addScaledVector(dir, this.height * 0.28);
599:       const radius = sp.range;
600:       this.game.aoe(this, center, radius, sp.damage, 26, sp.type, { building: true, color: sp.color });
601:       this.game.effects.shockwave(this.root.position, radius, sp.color);
602:       if (sp.type === 'firestorm') this.game.effects.fire(center, 60, sp.color, 5);
603:       if (sp.type === 'acid') this.game.effects.acid(center, 50, sp.color);
604:       if (sp.type === 'cleave') this.game.effects.sparks(center, 40, sp.color, 30);
605:       this.game.effects.explosion(center, sp.type === 'pulse' ? 1.3 : 0.8, sp.color);
606:       this.game.audio.explosion(1.2);
607:       this.game.effects.shakeCamera(0.9, 0.8);
608:     }
