677:   takeDamage(amount, attacker, hitPoint, force = 10, type = 'impact') {
678:     if (this.dead || this.invuln > 0) return 0;
679:     if (this.state.grabbed) amount *= 0.7;
680:     let dmg = amount;
681:     let blocked = false;
682:     if (this.state.block && attacker) {
683:       const toAtt = attacker.root.position.clone().sub(this.root.position).setY(0).normalize();
684:       if (toAtt.dot(this.forward) > -0.1) {
685:         dmg *= 0.28;
686:         blocked = true;
687:         this.stamina = Math.max(0, this.stamina - amount * 0.7);
688:         this.game.effects.sparks(hitPoint || this.root.position.clone().setY(this.height * 0.55), 10, 0x9fd8ff, 12);
689:         this.game.audio.impact(0.5);
690:         if (this.stamina <= 0) { this.state.block = false; this.stagger(attacker); }
691:       }
692:     }
693:     this.hp -= dmg;
694:     this.state.hitPulse = 1;
695:     this.state.hitFlash = 1;
696:     this.state.hitDir = Math.random() > 0.5 ? 1 : -1;
697:     this.balance -= force * (blocked ? 0.25 : 1.2);
698:     const p = hitPoint || this.root.position.clone().setY(this.height * 0.55);
699:     this.game.effects.sparks(p, Math.round(6 + dmg * 0.3), type === 'freeze' ? 0x9feaff : type === 'acid' ? 0xc6ff4d : 0xffc46b, 12 + force);
700:     if (dmg > 12) this.game.effects.blood(p, Math.round(4 + dmg * 0.12));
701:     this.game.audio.impact(clamp(dmg / 18, 0.4, 1.6));
702:     if (this.isPlayer) this.game.effects.shakeCamera(clamp(dmg / 30, 0.12, 0.5), 0.35);
703:     if (attacker) {
704:       const dir = this.root.position.clone().sub(attacker.root.position).setY(0).normalize();
705:       if (!blocked) this.velocity.addScaledVector(dir, force * (1.4 - this.mass / 250000));
706:       if (type === 'burn') this.state.burn = Math.max(this.state.burn, 4);
707:       if (type === 'freeze') this.state.freeze = Math.max(this.state.freeze, 4);
708:       if (type === 'acid') this.state.shock = Math.max(this.state.shock, 4);
709:     }
710:     if (!blocked && this.balance <= 0 && !this.state.ragdoll) {
711:       const dir = attacker ? this.root.position.clone().sub(attacker.root.position).setY(0).normalize() : this.forward.clone().negate();
712:       this.knockdown(dir, force + 8);
713:     }
714:     this.lastDamageTime = 0;
715:     if (this.hp <= 0) this.die(attacker);
716:     this.game.hud?.onDamage?.(this, dmg, blocked);
717:     return dmg;
718:   }
