735:     this.ragdollTotal = this.ragdollTime;
736:     this.balance = 0;
737:     const d = dir.clone().setY(0).normalize();
738:     this.velocity.addScaledVector(d, Math.min(30, force * 1.1));
739:     const f = this.forward;
740:     const side = d.dot(this.right);
741:     const front = d.dot(f);
742:     this.fallPitch = clamp(-front * 1.35, -1.35, 1.35);
743:     this.fallRoll = clamp(side * 1.3, -1.3, 1.3);
744:     if (Math.abs(this.fallPitch) < 0.2 && Math.abs(this.fallRoll) < 0.2) this.fallPitch = 1.2;
745:     this.game.effects.dust(this.root.position.clone(), this.height * 0.3, 20, 0xa89a86);
746:     this.game.effects.shakeCamera(0.45, 0.5);
747:     this.game.audio.impact(1.4);
748:     this.game.hud?.toast(`${this.name} DOWN`, 'warn');
749:   }
