751:   updateRagdoll(dt, dead) {
752:     this.state.ragdoll = true;
753:     const t = dead ? 0 : this.ragdollTime;
754:     // slide
755:     this.velocity.x = damp(this.velocity.x, 0, 2.2, dt);
756:     this.velocity.z = damp(this.velocity.z, 0, 2.2, dt);
757:     this.root.position.x += this.velocity.x * dt;
758:     this.root.position.z += this.velocity.z * dt;
759:     const speed = Math.hypot(this.velocity.x, this.velocity.z);
760:     const hit = this.game.city.collideCircle(this.root.position.x, this.root.position.z, this.radius * 0.85);
761:     if (hit.pushX || hit.pushZ) {
762:       this.root.position.x += hit.pushX;
763:       this.root.position.z += hit.pushZ;
764:       if (hit.hit && speed > 5) {
765:         hit.hit.damage(speed * 3, this.root.position.clone().setY(this.height * 0.25), { source: this });
766:         this.game.effects.dust(this.root.position.clone(), this.radius, 12, 0x9a8f80);
767:         this.game.audio.impact(1);
768:       }
769:       this.velocity.multiplyScalar(0.4);
770:     }
771:     this.root.position.x = clamp(this.root.position.x, -420, 420);
772:     this.root.position.z = clamp(this.root.position.z, -420, 420);
773:     if (speed > 4 && Math.random() < 0.15) {
774:       this.game.effects.dust(this.root.position.clone(), this.radius * 0.8, 3, 0xa89a86);
775:     }
776:     if (!dead) {
777:       this.ragdollTime -= dt;
778:       if (this.ragdollTime > 0.55) {
779:         const p = clamp(1 - this.ragdollTime / 0.4, 0, 1);
780:         const e = 1 - Math.pow(1 - p, 3);
781:         this.visual.rotation.x = this.fallPitch * e;
782:         this.visual.rotation.z = this.fallRoll * e;
783:       } else {
784:         const k = clamp(this.ragdollTime / 0.55, 0, 1);
785:         this.visual.rotation.x = this.fallPitch * k;
786:         this.visual.rotation.z = this.fallRoll * k;
787:         if (this.ragdollTime <= 0) {
788:           this.state.ragdoll = false;
789:           this.state.recovery = 0.4;
790:           this.balance = 55;
791:           this.invuln = 0.55;
792:           this.visual.rotation.set(0, 0, 0);
793:           this.velocity.set(0, 0, 0);
794:           this.game.hud?.toast(`${this.name} RECOVERS`, 'info');
795:         }
796:       }
797:     } else {
798:       this.deathTimer += dt;
799:       const e = 1 - Math.pow(1 - clamp(this.deathTimer / 0.8, 0, 1), 3);
800:       this.visual.rotation.x = this.fallPitch * e;
801:       this.visual.rotation.z = this.fallRoll * e;
802:       this.healthBar.visible = false;
803:     }
804:     this.root.rotation.y = this.yaw;
805:   }
