819:     if (this.grabbedBy) { this.grabbedBy.grabTarget = null; this.grabbedBy = null; this.state.grabbed = false; }
820:     if (this.grabTarget) { this.grabTarget.releaseGrab(); this.grabTarget = null; }
821:     const dir = attacker
822:       ? this.root.position.clone().sub(attacker.root.position).setY(0).normalize()
823:       : this.forward.clone().negate();
824:     const side = dir.dot(this.right);
825:     const front = dir.dot(this.forward);
826:     this.fallPitch = clamp(-front * 1.35, -1.35, 1.35);
827:     this.fallRoll = clamp(side * 1.3, -1.3, 1.3);
828:     if (Math.abs(this.fallPitch) < 0.2 && Math.abs(this.fallRoll) < 0.2) this.fallPitch = 1.2;
829:     this.velocity.addScaledVector(dir, 20);
830:     this.game.effects.explosion(this.root.position.clone().setY(this.height * 0.4), 1.1, this.def.colors.glow);
831:     this.game.audio.explosion(1.2);
